INSERT INTO `aspiration` (`id`, `description`, `img`, `nom`, `dlc_id`, `trait_id`, `type`) VALUES
(2, 'Devenir le loup-garou le plus fort et le plus redouté, et y arriver seul !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-aspirations-262376/62-lone-wolf.png', 'Loup-garou ultime', 8, 8, 'LYCANTHROPIE'),
(9, 'Ce Sim veut s\'entraîner et devenir le plus fort possible !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-aspirations-262376/4-bodybuilder.png', 'Culturiste', 6, 156, 'SPORT'),
(10, 'Ce Sim veut libérer la bête qui est en lui et devenir un loup-garou', 'https://luniversims.fr/uploads/monthly_2023_07/werewolf_Initiation_0x413278c48726d16d_Normal.thumb.png.fb1de861ca33952f1c95489645e0948c.png', 'Initié à la lycanthropie', 8, 179, 'LYCANTHROPIE'),
(11, 'Rejoignez les rangs dignes et amicaux du Collectif de la lune !', 'https://luniversims.fr/uploads/monthly_2023_07/werewolf_PackA_0xfcb31fef22b8a824_Normal.thumb.png.21a119ee6113260a57c699f289b71002.png', 'Émissaire du Collectif', 8, 180, 'LYCANTHROPIE'),
(13, 'Rejoignez les Crocs sauvages et montrez au monde qui commande !', 'https://static.wikia.nocookie.net/sims/images/0/0c/Wildfang_Renegade.png/revision/latest?cb=20220619233722', 'Rénégat des Crocs sauvages', 8, 181, 'LYCANTHROPIE'),
(14, 'Cherchez le remède pour continuer votre vie en tant que Sim normal !', 'https://static.wikia.nocookie.net/sims/images/e/ea/Cure_Seeker.png/revision/latest?cb=20220619233659', 'Chercheur de remède', 8, 182, 'LYCANTHROPIE'),
(15, 'Votre Sim veut s\'amuser et aller à des rencards avec toutes sortes de personnes intéressantes !', 'https://static.wikia.nocookie.net/sims/images/d/dd/Romantique_en_s%C3%A9rie.webp/revision/latest?cb=20220314095429&path-prefix=fr', 'Romantique en série', 6, 183, 'AMOUR'),
(17, 'Votre Sim veut trouver le Grand Amour et mener une vie gratifiante avec lui.', 'https://static.wikia.nocookie.net/sims/images/0/08/%C3%82me_soeur.webp/revision/latest?cb=20220314100627&path-prefix=fr', 'Âme sœur', 6, 184, 'AMOUR'),
(18, 'Votre Sim veut faire pousser des plantes et devenir un expert du jardinage.', 'https://static.wikia.nocookie.net/sims/images/5/52/Botaniste_ind%C3%A9pendant.webp/revision/latest?cb=20220315144343&path-prefix=fr', 'Botaniste indépendant', 6, 185, 'NATURE'),
(19, 'Votre Sim veut tout savoir sur la pêche !', 'https://static.wikia.nocookie.net/sims/images/7/7c/Pro_de_la_p%C3%AAche.webp/revision/latest?cb=20220315145710&path-prefix=fr', 'Pro de la pêche', 6, 186, 'NATURE'),
(20, 'Votre Sim veut collectionner tout ce que le monde a à offrir.', 'https://static.wikia.nocookie.net/sims/images/0/07/Conservateur.webp/revision/latest?cb=20220315150323&path-prefix=fr', 'Conservateur', 6, 187, 'NATURE'),
(21, 'Les gardiens de la campagne veulent découvrir la campagne et devenir ami avec tous les animaux du quartier, qu\'ils soient domestiques ou sauvages.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-aspirations-262376/45-country-caretaker.png', 'Gardien de la campagne', 23, 188, 'NATURE'),
(22, 'Les amateurs de plein air veulent profiter de tout ce que la nature a à offrir !', 'https://static.wikia.nocookie.net/sims/images/5/51/Amateur_de_plein_air.webp/revision/latest?cb=20220315142710&path-prefix=fr', 'Amateur de plein air', 33, 189, 'NATURE'),
(23, 'Ce Sim veut apprendre toutes les recettes de potions et toutes les préparer !', 'https://static.wikia.nocookie.net/sims/images/f/f5/Pr%C3%A9parateur_de_potions.webp/revision/latest?cb=20220315143603&path-prefix=fr', 'Préparateur de potions', 121, 190, 'NATURE'),
(24, 'Ce Sim veut explorer la jungle !', 'https://static.wikia.nocookie.net/sims/images/d/d3/Explorateur_de_la_jungle.webp/revision/latest?cb=20220316162014&path-prefix=fr', 'Explorateur de la jungle', 37, 191, 'NATURE'),
(25, 'Ce Sim veut créer une communauté meilleure et plus écologique.', 'https://static.wikia.nocookie.net/sims/images/d/d3/Eco-innovateur.webp/revision/latest?cb=20220316162807&path-prefix=fr', 'Éco-innovateur', 12, 192, 'NATURE'),
(26, 'Ce Sim adore la vie dans la nature et aime satisfaire le moindre de ses besoins en plein air.', 'https://luniversims.fr/uploads/monthly_2025_07/Track_Nature_BohemianStyle_0xb9c54f17a24488cc_Normal.thumb.png.c83ef01c3a15c5ad5926b2da556765c0.png', 'Nomade de la nature', 31, 193, 'NATURE'),
(27, 'Ce Sim veut fournir toutes sortes de conseils pour avoir une influence positive sur la vie de ses voisins.', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Popularity_FriendlyNeighbor_0x2c88a37f12453d93_Normal.thumb.png.260975a79c210386200cc32a859d9a38.png', 'Confident du quartier', 6, 194, 'POPULARITE'),
(28, 'Ce Sim veut devenir extrêmement célèbre.', 'https://static.wikia.nocookie.net/sims/images/d/d6/C%C3%A9l%C3%A9brit%C3%A9_de_renomm%C3%A9e_mondiale.webp/revision/latest?cb=20220316164544&path-prefix=fr', 'Célébrité de renommée mondiale', 19, 195, 'POPULARITE'),
(29, 'Ce Sims veut être le chef du meilleur groupe de la ville.', 'https://static.wikia.nocookie.net/sims/images/b/ba/Chef_de_la_bande.webp/revision/latest?cb=20220316165435&path-prefix=fr', 'Chef de la bande', 16, 196, 'POPULARITE'),
(30, 'Ce Sim veut raconter des blagues et devenir un humoriste célèbre.', 'https://static.wikia.nocookie.net/sims/images/c/c7/As_des_blagues.webp/revision/latest?cb=20220316170057&path-prefix=fr', 'As des blagues', 6, 197, 'POPULARITE'),
(31, 'Ce Sim veut se faire un maximum d\'amis et les garder !', 'https://luniversims.fr/uploads/monthly_2025_02/Track_Popularity_B_0xdad37710fe1cc331_Normal.thumb.png.2d0b3423d1d4ff8d53c21a9dd6fe6b0f.png', 'Ami de tous', 6, 198, 'POPULARITE'),
(32, 'Ce Sim veut gérer une petite entreprise ayant une clientèle nombreuse et satisfaite, que ce soit grâce à des pratiques commerciales s\'appuyant sur des rêves idéalistes ou à des fraudes rusées basées sur des méthodes pragmatiques.', 'https://luniversims.fr/uploads/monthly_2025_03/Entrepreneurestim.thumb.png.2d8d60b4b8ae4c39973088d5fdce2561.png', 'Entrepreneur estimé', 30, 204, 'POPULARITE'),
(33, 'Ce Sim veut contrôler sa soif et rester aussi humain que possible.', 'https://static.wikia.nocookie.net/sims/images/1/1d/Bon_vampire.webp/revision/latest?cb=20220316171908&path-prefix=fr', 'Bon vampire', 36, 200, 'POPULARITE'),
(34, 'Ce Sim veut être le locataire et voisin parfait dans une location résidentielle !', 'https://static.wikia.nocookie.net/sims/images/8/8f/Aspiration_TS4_Discerning_Dweller.png/revision/latest?cb=20231211194607', 'Habitant averti', 27, 205, 'POPULARITE'),
(35, 'Un conflit grandit dans le monde de Batuu. Votre Sim veut explorer l\'Avant-Poste de la Flèche-Noire afin de comprendre s\'il doit soutenir la Résistance ou le Premier Ordre.', 'https://static.wikia.nocookie.net/sims/images/5/5e/Espoir_ou_Ordre.png/revision/latest?cb=20220317090128&path-prefix=fr', 'Espoir ou Ordre', 122, NULL, 'STAR_WARS'),
(36, 'Ce Sim veut rejoindre la résistance et renverser l\'Empire !', 'https://luniversims.fr/uploads/monthly_2023_07/Star_Wars_Track_Resistance_0xff069906df8c6597_Normal.thumb.png.531650f85649a1579d29f5413d09cacc.png', 'Paragon d\'espoir', 122, 201, 'STAR_WARS'),
(37, 'Ce Sim veut rejoindre le Premier Ordre et détruire la Résistance !', 'https://luniversims.fr/uploads/monthly_2023_07/Star_Wars_Track_FirstOrder_0x756366ecb2c92ff2_Normal.thumb.png.16888385478afd48a0e28703ecf0e16b.png', 'Exécuteur de l\'Ordre', 122, 202, 'STAR_WARS'),
(38, 'Ce Sim veut s\'enrichir sans prendre parti pour un des deux camps !', 'https://luniversims.fr/uploads/monthly_2023_07/Star_Wars_Track_Scoundrel_0x56762c8b59a92295_Normal.thumb.png.727d1c4550ec4652fc28586e67672e4a.png', 'Corsaire Galactique', 122, 203, 'STAR_WARS'),
(39, 'Ce Sim veut partager sa maîtrise du bien-être avec le monde, et former un successeur à qui transmettre son savoir.', 'https://static.wikia.nocookie.net/sims/images/9/96/Gourou_zen.webp/revision/latest?cb=20220317093509&path-prefix=fr', 'Gourou Zen', 34, 206, 'BIEN_ETRE'),
(40, 'Ce Sim mène une quête pour atteindre la paix intérieure. Même si la véritable harmonie est parfois éphémère, l\'important est de développer des outils qui permettent de réduire les émotions négatives.', 'https://static.wikia.nocookie.net/sims/images/5/57/Paix_int%C3%A9rieure.webp/revision/latest?cb=20220317092724&path-prefix=fr', 'Paix Intérieure', 34, 207, 'BIEN_ETRE'),
(41, 'Ce Sim veut gagner beaucoup de Simflouz avec des activités liées au bien-être : pour cela, il peut par exemple proposer de manucures ou utiliser la table de massage pour travailler dans un spa.', 'https://static.wikia.nocookie.net/sims/images/5/59/Sp%C3%A9cialiste_des_soins_pour_soi.webp/revision/latest?cb=20220317094026&path-prefix=fr', 'Spécialiste des soins pour soi', 34, 208, 'BIEN_ETRE'),
(42, 'Ce Sim rêve de réussir dans l\'art !', 'https://static.wikia.nocookie.net/sims/images/f/fc/Peintre_extraordinaire.webp/revision/latest?cb=20220312162900&path-prefix=fr', 'Prodige artistique', 6, 212, 'CREATIVITE_ENFANT'),
(43, 'Ce Sim veut être l\'enfant le plus intelligent de l\'école !', 'https://static.wikia.nocookie.net/sims/images/d/db/Petit_g%C3%A9nie.webp/revision/latest?cb=20220317110847&path-prefix=fr', 'Petit génie', 6, 211, 'FACULTES_MENTALES'),
(44, 'Ce Sim veut être joueur et agile !', 'https://static.wikia.nocookie.net/sims/images/7/74/Enfant_turbulent.webp/revision/latest?cb=20220317111525&path-prefix=fr', 'Enfant turbulent', 6, 210, 'FACULTES_MOTRICES'),
(45, 'Ce Sim veut parler à tout le monde et se faire des amis !', 'https://static.wikia.nocookie.net/sims/images/2/2d/Enfant_tr%C3%A8s_sociable.webp/revision/latest?cb=20220317112257&path-prefix=fr', 'Enfant très sociable', 6, 209, 'FACULTES_SOCIALES'),
(47, 'Ce Sim veut avoir une relation exceptionnelle avec tous les animaux !', 'https://static.wikia.nocookie.net/sims/images/9/93/Aspiration_Amie_des_animaux.webp/revision/latest?cb=20220312145305&path-prefix=fr', 'Ami des animaux', 18, NULL, 'ANIMAL'),
(48, 'Ce Sim veut explorer la nature sauvage de Mont Komorebi et faire des sports d\'hiver extrêmes.', 'https://static.wikia.nocookie.net/sims/images/8/82/Aspiration_Passionn%C3%A9_de_sports_extr%C3%AAmes.webp/revision/latest?cb=20220312152843&path-prefix=fr', 'Passionné de sports extrêmes', 22, 214, 'SPORT'),
(49, 'Ce Sim veut faire partie des meilleurs cavaliers du monde et va le prouver en participant à des concours hippiques.', 'https://static.wikia.nocookie.net/sims/images/b/b1/Cavaliere_de_championat_aspiration.webp/revision/latest?cb=20250426130835&path-prefix=fr', 'Cavalier de championnat', 26, 215, 'SPORT'),
(50, 'Ce Sim veut que sa vie ne soit faite que d\'art et de peinture !', 'https://tiermaker.com/images/media/template_images/2024/15057677/sims-4-adult-aspirations-15057677/aspirationts4painterextraordinaire.png', 'Peintre extraordinaire', 6, 213, 'CREATIVITE'),
(51, 'Ce Sim veut écrire des  livres et devenir un auteur célèbre !', 'https://static.wikia.nocookie.net/sims/images/3/30/Auteur_de_best-sellers.webp/revision/latest?cb=20220312164148&path-prefix=fr', 'Auteur de best-sellers', 6, 217, 'CREATIVITE'),
(52, 'Ce Sim veut être un musicien et compositeur expert !', 'https://static.wikia.nocookie.net/sims/images/2/2c/G%C3%A9nie_de_la_musique.webp/revision/latest?cb=20220312165303&path-prefix=fr', 'Génie de la musique', 6, 218, 'CREATIVITE'),
(53, 'Ce Sim veut perfectionner son art et devenir un acteur acclamé !', 'https://static.wikia.nocookie.net/sims/images/9/99/Cat%C3%A9gorie_Grand_acteur.webp/revision/latest?cb=20220312160039&path-prefix=fr', 'Grand acteur', 19, 219, 'CREATIVITE'),
(54, 'Ce Sim a de la laine qui coule dans ses veines ; rien ne l\'arrêtera dans sa quête de l\'objet tricoté parfait !', 'https://static.wikia.nocookie.net/sims/images/c/c2/Aspiration_Seigneur_du_tricot.webp/revision/latest?cb=20220312170823&path-prefix=fr', 'Seigneur du tricot', 14, 220, 'CREATIVITE'),
(55, 'Ce Sim veut devenir un expert en fabrication d\'objets !', 'https://static.wikia.nocookie.net/sims/images/7/7c/Aspiration_Cr%C3%A9ateur_magistral.webp/revision/latest?cb=20220312171703&path-prefix=fr', 'Créateur magistral', 12, 221, 'CREATIVITE'),
(56, 'Ce Sim veut se faire des ennemis et devenir un criminel célèbre !', 'https://static.wikia.nocookie.net/sims/images/9/95/Cat%C3%A9gorie_Ennemi_publique.webp/revision/latest?cb=20220312181733&path-prefix=fr', 'Ennemi public', 6, 222, 'DEVIANCE'),
(57, 'Ce Sim ne vit que pour faire des blagues et semer le chaos !', 'https://static.wikia.nocookie.net/sims/images/7/70/Roi_des_b%C3%AAtises.webp/revision/latest?cb=20220312182538&path-prefix=fr', 'Roi des bêtises', 6, 223, 'DEVIANCE'),
(58, 'Ce Sim veut détruire la vie amoureuse de tous les Sims, y compris la sienne !', 'https://static.wikia.nocookie.net/sims/images/f/f1/Vilain_Valentin.webp/revision/latest?cb=20220312183746&path-prefix=fr', 'Vilain Valentin', 6, 224, 'DEVIANCE'),
(59, 'Ce Sim veut devenir un fournisseur et redistributeur magistral d\'objets et d\'argent dans ses propres poches.', 'https://luniversims.fr/uploads/monthly_2025_02/incorrigiblekleptomane.thumb.png.03aea364d919497715a0a4c8be907908.png', 'Incorrigible kleptomane', 6, 225, 'DEVIANCE'),
(60, 'Ce Sim adore l\'excitation que procure la découverte de secrets croustillants sur d\'autres Sims. Ce qu\'il fera de ces informations est encore à déterminer...', 'https://static.wikia.nocookie.net/sims/images/f/fc/Chercheur_de_secret.webp/revision/latest?cb=20250426173415&path-prefix=fr', 'Chercheur de secret', 27, 226, 'DEVIANCE'),
(61, 'Ce Sim veut avoir une  famille qui réussit dans la vie !', 'https://static.wikia.nocookie.net/sims/images/6/6f/Descendance_qui_r%C3%A9ussit.webp/revision/latest?cb=20220313151740&path-prefix=fr', 'Descendance qui réussit', 6, 227, 'FAMILLE'),
(62, 'Ce Sim veut fonder un grand foyer plein d\'amour !', 'https://static.wikia.nocookie.net/sims/images/6/6e/Grande_famille_heureuse.webp/revision/latest?cb=20220313152629&path-prefix=fr', 'Grande  famille heureuse', 6, 228, 'FAMILLE'),
(63, 'Ce Sim veut être le meilleur des parents !', 'https://static.wikia.nocookie.net/sims/images/8/86/Superparent.webp/revision/latest?cb=20220313150627&path-prefix=fr', 'Superparent', 10, 230, 'FAMILLE'),
(64, 'Ce Sim veut créer une famille de vampires !', 'https://static.wikia.nocookie.net/sims/images/f/fb/Famille_de_vampires.webp/revision/latest?cb=20220313153453&path-prefix=fr', 'Famille de vampires', 36, 229, 'FAMILLE'),
(65, 'Ce Sim veut maîtriser les arts culinaires.', 'https://static.wikia.nocookie.net/sims/images/1/11/Grand_chef.webp/revision/latest?cb=20220313154312&path-prefix=fr', 'Grand chef', 6, 231, 'NOURRITURE'),
(66, 'Ce Sim veut savoir tout ce qu\'il y a à savoir sur la mixologie !', 'https://static.wikia.nocookie.net/sims/images/7/78/Grand_mixologue.webp/revision/latest?cb=20220313155139&path-prefix=fr', 'Grand mixologue', 6, 233, 'NOURRITURE'),
(67, 'Ce Sim veut manger, parler, dormir, rêver et vivre de sandwichs au fromage fondu.', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Food_GrilledCheese_0x414076cbc974f0c0_Normal.thumb.png.323c07be0bfe5324a01fbb8fb37462f9.png', 'Sandwich au fromage fondu', 6, 232, 'NOURRITURE'),
(68, 'Ce Sim veut maîtriser l\'art de la fabrication de nectar, en peaufinant ses aptitudes pour ne fabriquer systématiquement que les meilleurs nectars. Il veut aussi gagner une quantité absurde de simflouz avec cette activité.', 'https://static.wikia.nocookie.net/sims/images/8/82/Expert_en_fabrication_de_nectar.webp/revision/latest?cb=20250426182330&path-prefix=fr', 'Expert en fabrication de nectar', 26, 234, 'NOURRITURE'),
(69, 'Ce Sim manie parfaitement les petits appareils de cuisine !', 'https://static.wikia.nocookie.net/sims/images/e/ee/As_des_appareils.webp/revision/latest?cb=20250426182642&path-prefix=fr', 'As des appareils', 140, 235, 'NOURRITURE'),
(70, 'Ce Sim veut avoir la plus grande demeure possible !', 'https://static.wikia.nocookie.net/sims/images/1/11/Baron_de_l%27immobilier.webp/revision/latest?cb=20220313161416&path-prefix=fr', 'Baron de l\'immobilier', 6, 236, 'FORTUNE'),
(71, 'Ce Sim veut devenir le Sim le plus riche qui existe !', 'https://static.wikia.nocookie.net/sims/images/e/e1/Incroyablement_riche.webp/revision/latest?cb=20220313160317&path-prefix=fr', 'Incroyablement riche', 6, 237, 'FORTUNE'),
(72, 'Ce Sim veut être le meilleur propriétaire que le monde ait jamais connu !', 'https://static.wikia.nocookie.net/sims/images/e/e9/Proprietaire_5etoiles.webp/revision/latest?cb=20250427052925&path-prefix=fr', 'Propriétaire cinq étoiles', 27, 238, 'FORTUNE'),
(73, 'Ce Sim veut avoir le stand de nourriture le plus rentable !', 'https://static.wikia.nocookie.net/sims/images/7/7c/Magnat_du_march%C3%A9.webp/revision/latest?cb=20250427053618&path-prefix=fr', 'Magnat du marché', 140, 239, 'FORTUNE'),
(74, 'Ce Sim veut être à la fois cultivé et manuel !', 'https://static.wikia.nocookie.net/sims/images/0/07/Cerveau_exceptionnel.webp/revision/latest?cb=20220313165714&path-prefix=fr', 'Cerveau exceptionnel', 6, 240, 'CONNAISSANCE'),
(75, 'Ce Sim veut tout savoir sur les ordinateurs, des jeux aux opportunités professionnelles !', 'https://static.wikia.nocookie.net/sims/images/7/72/G%C3%A9nie_de_l%27informatique.webp/revision/latest?cb=20220313165050&path-prefix=fr', 'Génie de l\'informatique', 6, 241, 'CONNAISSANCE'),
(76, 'Ce Sim veut être compétent dans de nombreux domaines à la fois !', 'https://static.wikia.nocookie.net/sims/images/e/e3/Sim_aux_multiples_talents.webp/revision/latest?cb=20220313163420&path-prefix=fr', 'Sim aux multiples talents', 6, 242, 'CONNAISSANCE'),
(77, 'Ce Sim veut devenir un vampire sage et puissant !', 'https://static.wikia.nocookie.net/sims/images/5/5f/Ma%C3%AEtre_vampire.webp/revision/latest?cb=20220313162332&path-prefix=fr', 'Maître vampire', 36, 243, 'CONNAISSANCE'),
(78, 'Ce Sim veut devenir un expert en archéologie !', 'https://static.wikia.nocookie.net/sims/images/c/c9/Erudit_en_arch%C3%A9ologie.webp/revision/latest?cb=20220313164005&path-prefix=fr', 'Érudit en archéologie', 37, 244, 'CONNAISSANCE'),
(79, 'Ce Sim rêve d\'avoir une connaissance approfondie des arts magiques ésotériques.', 'https://static.wikia.nocookie.net/sims/images/a/aa/Sorts_et_sorcellerie.webp/revision/latest?cb=20220313170418&path-prefix=fr', 'Sorts et sorcellerie', 121, 245, 'CONNAISSANCE'),
(80, 'Ce Sim veut aller à l\'université et trouver un emploi, mais surtout... \"apprendre\" !', 'https://static.wikia.nocookie.net/sims/images/6/6e/Etudes_universitaires.webp/revision/latest?cb=20220313172858&path-prefix=fr', 'Études universitaires', 21, 246, 'CONNAISSANCE'),
(81, 'Ce Sim veut tout savoir sur les fantômes pour écrire des romans d\'horreur !', 'https://static.wikia.nocookie.net/sims/images/7/7c/Historien_des_fantomes.webp/revision/latest?cb=20250427083726&path-prefix=fr', 'Historien des fantômes', 29, 247, 'CONNAISSANCE'),
(82, 'Ce Sim veut apprendre des choses auprès de mentor de talent, puis transmettre ces connaissances à d\'autres Sims.', 'https://static.wikia.nocookie.net/sims/images/d/df/Mentor_Magistral.webp/revision/latest?cb=20250427083924&path-prefix=fr', 'Mentor magistral', 30, 249, 'CONNAISSANCE'),
(83, 'Ce Sim veut apprendre tout ce qu\'il y a à savoir sur la compétence Apothicaire, et fabriquer des remèdes et élixirs puissants avec des plantes.', 'https://luniversims.fr/uploads/monthly_2025_07/Track_Knowledge_NatureMeds_0x1eaabe6f457ad7be_Normal.thumb.png.a46d3447abfcc989d6657cc03223ef3b.png', 'Spécialiste des élixirs', 31, 248, 'CONNAISSANCE'),
(84, 'Ce Sim est passionné par la vie en ville.', 'https://static.wikia.nocookie.net/sims/images/b/bb/Sims_originaire_de_la_ville.webp/revision/latest?cb=20220313192314&path-prefix=fr', 'Sim originaire de la ville', 17, 250, 'LIEU'),
(85, 'Ce Sim veut se la couler douce et profiter de la vie à la plage.', 'https://static.wikia.nocookie.net/sims/images/9/9c/Vie_%C3%A0_la_plage.webp/revision/latest?cb=20220313193132&path-prefix=fr', 'Vie à la plage', 20, 251, 'LIEU'),
(86, 'StrangerVille cache un sombre et profond secret, et ce Sim veut découvrir pourquoi tous les habitants ont un comportement un peu étrange.', 'https://static.wikia.nocookie.net/sims/images/6/64/Le_myst%C3%A8re_de_StrangerVille.webp/revision/latest?cb=20220313174831&path-prefix=fr', 'Mystère de Strangerville', 38, 256, 'LIEU'),
(87, 'Ce Sim veut explorer la culture de Mont Komorebi et découvrir tout ce qu\'elle a à offrir.', 'https://static.wikia.nocookie.net/sims/images/5/59/Visiteur_de_Mont_Komorebi.webp/revision/latest?cb=20220313180122&path-prefix=fr', 'Visiteur de Mont Komorebi', 22, 255, 'LIEU'),
(88, 'Ce Sim se sent bien dans les maisons sales et en désordre, et évite à tout prix de faire le ménage. Procrastinez, esquivez les corvées, revoyez votre niveau d\'exigence à la baisse et trouvez des moyens créatifs de vous épanouir dans les environnements les plus dégoutants.', 'https://static.wikia.nocookie.net/sims/images/a/a7/Fabuleusement_sale.webp/revision/latest?cb=20220313185626&path-prefix=fr', 'Fabuleusement sale', 142, 254, 'LIEU'),
(89, 'Ce Sim aime que sa maison soit présentable et propre en permanence. Fiers de leurs maisons impeccables, ces Sims visent la perfection et s\'épanouissent lorsqu\'ils peuvent frimer avec leur maison immaculée devant leurs invités.', 'https://static.wikia.nocookie.net/sims/images/b/b3/Parfaitement_impeccable.webp/revision/latest?cb=20220313190804&path-prefix=fr', 'Parfaitement impeccable', 142, 253, 'LIEU'),
(90, 'Ce Sim veut se plonger dans tout ce que Tomarang a à offrir', 'https://static.wikia.nocookie.net/sims/images/2/20/Specialiste_de_tomarang.webp/revision/latest?cb=20250427093520&path-prefix=fr', 'Spécialiste de Tomarang', 27, 252, 'LIEU'),
(91, 'Ce Sim veut montrer au monde entier le type de fée qu\'il peut être.', 'https://luniversims.fr/uploads/monthly_2025_07/Fairy_FairyStories_Initiation_0x358b1c2160e3497a_Normal.thumb.png.7bec88dbfb4db0a98e50fbbc36464092.png', 'Histoires de fée', 31, 257, 'FEE'),
(92, 'Ce Sim satisfait son envie de manipuler le monde qui l\'entoure, que ce soit en influençant la chance ou les émotions ou en cassant instantanément des objets, et cela l\'amuse beaucoup.', 'https://luniversims.fr/uploads/monthly_2025_07/Fairy_FairyStories_DarkPath_0x9146eb9b4bfba5a6_Normal.thumb.png.539ec7784ba5a0c32a366100a519ee7a.png', 'Fée discordante', 31, 258, 'FEE'),
(93, 'Ce Sim s\'épanouit en aidant les autres. Vous le trouverez en train de prendre soin de plantes et d\'animaux, ou de guérir des syndromes.', 'https://luniversims.fr/uploads/monthly_2025_07/Fairy_FairyStories_LightPath_0x1aa4979f907f2aa6_Normal.thumb.png.47a139a7a1223e61024e79a18b27a8da.png', 'Fée harmonieuse', 31, 259, 'FEE'),
(94, 'Ce Sims veut tailler des pierres précieuses, fabriquer des bijoux et utiliser le pouvoir des cristaux !', 'https://static.wikia.nocookie.net/sims/images/2/28/Aspiration_TS4_Crystal_Crafter.png/revision/latest?cb=20240229202508', 'Artisan du cristal', 59, 260, 'NATURE'),
(95, 'Ce Sim veut explorer tout ce que l’amour a à offrir.', 'https://luniversims.fr/uploads/monthly_2024_07/Explorateurromantique.thumb.png.7de082fc2fef7cab75fbc0aadc284cd3.png', 'Explorateur romantique', 28, 261, 'AMOUR'),
(96, 'Ce Sim veut avoir des relations réussies avec au moins deux Sims.', 'https://luniversims.fr/uploads/monthly_2024_07/Partenairemodle.thumb.png.dacab744458e5c301ea9bf21af2564e6.png', 'Partenaire modèle', 28, 262, 'AMOUR'),
(97, 'Ce Sim réagit de manière excessive en permanence !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Teen_DramaLlama_0xfe84b8f1bd7c66a4_Normal.thumb.png.468ee8d79f4fef3af3aa56453bb6e4cc.png', 'Ado qui en fait des tonnes', 24, 266, 'ADO'),
(98, 'Ce Sim veut être le meilleur dans tous les domaines : résultats scolaires ? C\'est bon. Sport ? Aussi. Argent ? Idem ! Il prépare son chemin vers la réussite !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Teen_GoalOriented_0x9824a665179f5e9d_Normal.thumb.png.e387881156aae23515733bbb6da0962d.png', 'Déterminé', 24, 265, 'ADO'),
(99, 'Ce Sim veut créer les tendances, être populaire et avoir de l\'influence. Une véritable icône.', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Teen_AdmiredIcon_0x1eb09ac929769816_Normal.thumb.png.03500b1bbcae37d64dd34db8200617d7.png', 'Icône admirée', 24, 264, 'ADO'),
(100, 'Ce Sim veut profiter pleinement de la vie de façon insouciante en ne suivant aucune règle.', 'https://luniversims.fr/uploads/monthly_2023_07/Track_Teen_LiveFast_0x449efa9704fcf5c8_Normal.thumb.png.3c49d1f49e30a0ba18b9d9e29a592052.png', 'Vivre à fond', 24, 263, 'ADO'),
(101, 'Ce Sim veut devenir la star du quartier !', 'https://luniversims.fr/uploads/monthly_2025_09/Starduquartier.thumb.png.12f8cae84f210acfdf9818de74e58c3c.png', 'Star du quartier', 32, 267, 'FACULTES_SOCIALES'),
(102, 'Ce Sim souhaite explorer les mondes fantastiques des papillons et des poissons, et apprendre tout ce qu\'il y a à savoir sur les bestioles !', 'https://luniversims.fr/uploads/monthly_2025_09/Chasseurdebestioles.thumb.png.6308c08d02eb08bfecdd89d9fe2881da.png', 'Chasseur de bestioles', 32, 268, 'NATURE'),
(103, 'Ce Sim veut soulager ses sentiments de rancune envers ses adversaires en se livrant à une vengeance mesquine.', 'https://static.wikia.nocookie.net/sims/images/2/27/MasterOfGrudges.png/revision/latest?cb=20260217215807', 'Spécialiste de la rancœur', 6, 269, 'DEVIANCE'),
(104, 'Ce Sim adore jouer de façon active, et avec des amis !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_PlaytimeCaptain_0x70acdae0ab49ce4f_Normal.thumb.png.1007ffc773ddd95e7dbd244a4dd9f389.png', 'Capitaine de la récré', 119, 270, 'POLYVALENCE'),
(105, 'Ce Sim veut développer ses compétences créatives et mentales pour inspirer l\'innovation et le jeu !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_CreativeGenius_0x23d194d2f4251c50_Normal.thumb.png.646d233c5dfadd0c4327ccf0d57419bd.png', 'Génie créatif', 119, 271, 'POLYVALENCE'),
(106, 'Ce Sim veut maîtriser à la fois son corps et son esprit !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_MindAndBody_0xec3c54221795e29b_Normal.thumb.png.820d5de5220f72c302019b2b75be890a.png', 'Corps et esprit', 119, 272, 'POLYVALENCE'),
(107, 'Ce Sim veut mettre l\'ambiance lors des fêtes... d\'une manière créative unique !', 'https://luniversims.fr/uploads/monthly_2023_07/Track_SlumberPartyAnimal_0xcb108ec3ffda20b6_Normal.thumb.png.5c500e0462c38d44ea83004640e8929e.png', 'Pro des soirées pyjamas', 119, 273, 'POLYVALENCE'),
(108, 'Ce Sim souhaite tout savoir sur tout le monde et est en mesure de faire du chantage et de révéler des scandales pour arriver à ses fins !', 'https://luniversims.fr/uploads/monthly_2026_01/image.png.2b95c13aef89c17c7c0832f1d5776c6e.png', 'Marionnettiste des masses', 117, 274, 'DEVIANCE');
INSERT INTO `branche_carriere` (`id`, `description`, `img`, `nom`, `carriere_id`) VALUES
(1, 'L\'espace est sauvage et indiscipliné… un peu trop indiscipliné. Occuper un poste dans la Patrouille des planètes permet de s\'assurer que l\'espace reste un endroit sûr pour les générations futures.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/astronaute-branche-ranger-espace.png', 'Ranger de l\'espace', 68),
(2, 'Un Sim qui maîtrise la plupart des étoiles tire avantage de la frontière qui n\'est contrôlée par aucun gouvernement. Acceptez toutes les missions, même si elles impliquent de rester longtemps dans l\'espace.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/astronaute-branche-trafiquant-interstellaire.png', 'Trafiquant interstellaire', 68),
(3, 'Ne faudrait-il pas licencier tous les employés pour les remplacer par des robots ? Le logo de l\'entreprise ne devrait-il pas être redessiné en y mettant davantage de lamas ? Voici exactement le genre de décisions extrêmement importantes que vous devrez prendre si vous décidez de vous lancer dans le management.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/affaires-branche-management.png', 'Management', 69),
(4, 'Il faut des simflouz pour faire des simflouz. Optimisez vos investissements en faisant beaucoup de recherches et essayez de faire en sorte que vos piles de simflouz s\'élèvent encore plus haut !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/affaires-branche-investisseur.png', 'Investisseur', 69),
(5, 'Si vous êtes doués pour unir des cœurs, en utilisant votre intuition et vos compétences professionnelles pour aider les individus à trouver leur âme sœur : ne cherchez plus, la carrière Entremetteur est faite pour vous.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/zzzzz-1763840258ts4careermatchmaker.png', 'Entremetteur', 70),
(6, 'Vous avez la capacité d\'aider les Sims à affronter leurs peurs, à gérer leurs émotions et à retrouver l\'amour au sein de leurs relations ? Alors la branche Thérapeute de couple est peut-être faite pour vous !', 'https://luniversims.fr/uploads/monthly_2024_07/image.png.07f7105c67c7a6361d9f0674d18a10d6.png', 'Thérapeute de couple', 70),
(7, 'Si ce Sim a apprécié l\'art de la fabrication d\'élixirs, la voie Pro des remèdes sera pour lui une évidence. Il devra maîtriser son art et continuer à aider d\'autres Sims.', 'https://luniversims.fr/uploads/monthly_2025_06/0x00000000!0x27f5c9573074877c.0x00b2d882.png.c1abbffc2ac38b953d5781bda293f366.png', 'Pro des remèdes', 71),
(8, 'Utilisez les ressources de la nature pour changer la vie des Sims en améliorant leur forme physique et leur alimentation. Laissez la branche Accompagnement au bien-être guider ce Sim dans son parcours !', 'https://luniversims.fr/uploads/monthly_2025_06/0x00000000!0x54dbf5576953bb27.0x00b2d882.png.cd334828d6b4f65933f654a0349f5227.png', 'Accompagnement au bien-être', 71),
(9, 'Si quelques Sims s\'occupent de l\'aspect \"nature\" du camp, les animateurs et animatrices du parc s\'occupent des touristes. Les tâches sont variées et ce Sim peut autant être amené à devoir calmer quelqu\'un avec le mal du pays qu\'à organiser des activités pour un groupe de gosses surexcités. Cette branche lui assure de devenir un jour LA référence du camp !', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.83fae927d92707aa8e82e891429ccf1f.png', 'Animateur du parc', 72),
(10, 'Est-ce que ce Sim garde son calme quand la situation dégénère ? Est-ce qu\'il garde une clé de 12 dans sa poche arrière \"juste au cas où\" ? Alors, il ferait un excellent garde-forestier. Grâce à son savoir-faire pratique, sa concentration inébranlable et son profond respect pour les bois, ce Sim est prêt à répondre à l\'appel de la nature.', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.8c4d120cb88f34ef89927a35dfa63974.png', 'Garde-forestier', 72),
(11, 'Si vous adorez la liberté d\'embellir les choses ou d\'en inventer, la vie d\'écrivain est faite pour vous. Créez un personnage, élaborez une histoire… Le monde de l\'écrit est à vous.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/auteur-branche-auteur.png', 'Écrivain', 73),
(12, 'Les mots peuvent être des armes puissantes lorsqu\'ils sont utilisés pour exposer la vérité. En tant que journaliste, vous révèlerez au grand jour des informations embarrassantes mais essentielles. Les récompenses incluent la capacité d\'interviewer d\'autres Sims à propos de leur vie.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/auteur-branche-journaliste.png', 'Journaliste', 73),
(13, 'Êtes-vous une personne ambitieuse ? Avez-vous l\'esprit de compétition ? Affronter les meilleurs ne vous fait pas peur ? Vous voulez gagner votre vie en pratiquant le sport de votre enfance ? La carrière d\'athlète professionnel est faite pour vous ! Menez cette vie et divertissez les foules grâce à vos compétences athlétiques.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/athlete-branche-athlete-professionnel.png', 'Athlète professionnel', 74),
(14, 'En tant que maître de la musculation, vous pratiquez le fitness, ferez attention à votre nutrition et soulèverez des poids. Entraînez d\'autres Sims, faites étalage de votre force devant des fans en délire et sculptez votre corps pour ressembler à un dieu.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/athlete-branche-culturiste.png', 'Culturiste', 74),
(15, 'Vous avez gravi les échelons et disposez d\'une habilitation inégalée. En tant qu\'agent de diamant, toutes vos missions sont critiques, et aucun faux pas ne sera toléré.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/agent-secret-branche-agent-diamant.png', 'Agent de diamant', 75),
(16, 'Votre intelligence et votre formation supérieures sont trop précieuses pour être gaspillées à servir le bien. Alors pourquoi ne pas devenir le meilleur méchant du monde ?', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/agent-secret-branche-mechant.png', 'Méchant', 75),
(17, 'Les croque-morts incarnent le côté scientifique de la mort. Ces Sims devront probablement endurer des vapeurs de produits chimiques bizarres et des incidents de maquillage, tout en se faisant régulièrement snober par leur clientèle. Enfin, il leur faudra exceller dans les préparations de veillées funèbres, sans pour autant réveiller les morts.', 'https://luniversims.fr/uploads/monthly_2024_10/image.png.0ae3d000f4d42f9a0081463839625960.png', 'Croque-mort', 76),
(18, 'Les responsables de pompes funèbres peuvent proposer un mouchoir propre et une magnifique composition florale. Du travail administratif aux rites de passage, et des expositions des corps aux cortèges funèbres, leur rôle est d\'aider les Sims à gérer les suites d\'un décès de façon gracieuse.', 'https://luniversims.fr/uploads/monthly_2024_10/Sims-4-EP17-Icons(91).png.17d586469eca1cfd1c1280bdccaff3da.png', 'Responsable de pompes funèbres', 76),
(19, 'Le don de la musique est fait pour être partagé ! Pianotez sur ces touches et grattez ces cordes pour voir vos fans en délire tomber amoureux de toutes vos mélodies.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/artiste-branche-musicien.png', 'Musicien', 77),
(20, 'La vie d\'un humoriste professionnel n\'est pas toujours drôle, alors peaufinez vos imitations et préparez vos meilleures blagues sur l\'actualité !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/artiste-branche-humoriste.png', 'Humoriste', 77),
(21, 'Les rues sont votre terrain de jeu. Vous savez qu\'il n\'existe que deux voies possibles : vers le haut jusqu\'au sommet du pouvoir, ou vers le bas vers la prison ou la mort. Et vous avez choisi la première !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/criminel-branche-patron.png', 'Patron', 78),
(22, 'Pourquoi contribuer à l\'ordre établi alors que vous pouvez le renverser ? Les moyens d\'arriver à vos fins sont nombreux, et vous  adorez les chercher.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/criminel-branche-oracle.png', 'Oracle', 78),
(23, 'Il faut un talent spécial pour préparer de la nourriture vraiment exquise. Commencez votre parcours dont le but ultime sera d\'époustoufler un Sim avec un plat dangereusement délicieux', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/culinaire-branche-chef.png', 'Chef', 79),
(24, 'Un grand mixologue connaît sur le bout des doigts une grande variété de boissons et les ingrédients pour créer une boisson qui enthousiasmera même le plus timide des Sims.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/culinaire-branche-mixologue.png', 'Mixologue', 79),
(25, 'La mission d\'un créateur de tendances est de lancer des tendances en utilisant la mode et les vêtements. Grâce à son influence sur l\'apparence des Sims, la véritable paix dans le monde pourrait bientôt exister.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/influenceur-style-branche-createur-tendance.png', 'Créateur de tendances', 80),
(26, 'Un coup de ciseaux par ici, une petite retouche par là, une association de ceci avec cela et voilà : un nouveau style à la mode ! Ce nouveau métier est totalement tendance.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/influenceur-style-branche-styliste.png', 'Styliste', 80),
(27, 'Vous ne vivez que pour les jeux vidéo depuis que vous êtes capable d\'utiliser une manette, et en tant qu\'E-sportif professionnel, vous pouvez en faire votre métier.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/gourou-technologies-branche-esportif-professionnel.png', 'E-sportif professionnel', 81),
(28, 'Transformez vos grandes idées en noms connus de tous en tant que génie de start-up. Il vous faudra beaucoup de connaissances et de relations mais la richesse est à votre portée.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/gourou-technologies-branche-entrepreneur-startup.png', 'Entrepreneur de start-up', 81),
(29, 'Vous avez un réel talent et les autres commencent à s\'en rendre compte. Vivez pleinement votre art, prenez-le au sérieux et le monde entier vous suivra.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/peintre-branche-maitre-reel.png', 'Maître du réel', 82),
(30, 'Votre talent pour évaluer des œuvres d\'art est impressionnant et vous pouvez aider à réaliser de grandes choses. Montrez vos connaissances en tant que mécène d\'artistes.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/peintre-branche-mecene.png', 'Mécène', 82),
(31, 'Utilisez votre expertise pour donner des conseils sur les politiques écologistes, obtenir des subventions et sensibiliser le grand public. Il est temps d\'élargir la portée de votre travail !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/ecologiste-branche-responsable-environnement.png', 'Responsable environnement', 83),
(32, 'Des récifs de corail aux tortues de mer, montrez votre amour de la vie marine et de la mer. L\'océan vous appelle !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/ecologiste-branche-biologiste-marin.png', 'Biologiste marin', 83),
(33, 'La branche Soldat vous permettra de continuer à gagner des médailles en gravissant les échelons officiels de l\'armée jusqu\'au grade le plus élevé : maréchal. Pour développer vos compétences de chef, vous devrez donner des ordres aux autres et développer au maximum votre forme physique. Un maréchal ne peut être battu par une autre recrue !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/militaire-branche-soldat.png', 'Soldat', 84),
(34, 'La branche Opérations secrètes est la division de l\'armée dont personne ne parle. Vous devrez faire des tâches secrètes en plaçant des micros pour mettre sur écoute des Sims qui ne se douteront de rien. Vous devrez interroger tout individu suspect. Vous ne pourrez faire confiance à personne, et tout le monde mijotera quelque chose. Vous sentez-vous à la hauteur de cette mission ?', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/militaire-branche-operations-secretes.png', 'Opérations secrètes', 84),
(35, 'Vous vous intéressez au côté scientifique des plantes ? Alors utilisez vos connaissances pour améliorer la nature ! Les botanistes analysent des plantes, rédigent des articles et peuvent finir par obtenir des subventions. Vous pourrez également vous faire manger par... euh... travailler avec beaucoup de plantes vaches.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/jardinier-branche-botaniste.png', 'Botaniste', 85),
(36, 'Les designers floraux font pousser des plantes qu\'ils utilisent dans un but artistique. Leur principal moyen d\'expression est d\'utiliser la Table de composition florale pour créer des chefs d\'œuvre. Cela dit, vous commencerez par couper des tiges et des feuilles.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/jardinier-branche-designer-floral.png', 'Designer floral', 85),
(37, 'Définissez les standards pour toutes les œuvres d\'art.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/critique-branche-art-ep03.png', 'Critique d\'art', 86),
(38, 'Si vous n\'aimez pas quelque chose, personne ne le mangera.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/critique-branche-gastronomique-ep03.png', 'Critique gastronomique', 86),
(39, 'Utilisez vos prouesses politiques pour le bien du plus grand nombre. Collectez de l\'argent et trouvez une solution pour la cause que vous soutenez !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/politique-branche-evenements-caricatifs.png', 'Organisation d\'évènements caritatifs', 87),
(40, 'Obtenez des votes, faîtes des discours et devenez le leader national ! Vous feriez mieux de rafraîchir votre politique publique !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/politique-branche-sim-politique.png', 'Sim politique', 87),
(41, 'Tout le monde peut devenir célèbre sur Internet. Continuez à agrandir votre armée d\'abonnés grâce à des farces et des blagues pour atteindre votre but ultime : être une superstar sur Internet !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/reseaux-sociaux-branche-personnalite-internet-ep03.png', 'Personnalité d\'Internet', 88),
(42, 'Le monde de l\'entreprise n\'est pas toujours négatif : il vous permet d\'entrer en contact avec les plus grandes célébrités et de promouvoir de gros produits. Convaincre les gens de se mettre en avant est l\'un de vos plus grands talents. Il n\'y a rien que vous ne puissiez tourner à votre avantage.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/reseaux-sociaux-branche-relations-publiques-ep03.png', 'Relations publiques', 88);
INSERT INTO `carriere` (`id`, `description`, `img`, `nom`, `nom_carriere_generale`, `dlc_id`, `type`) VALUES
(3, 'Appel à tous les cerveaux ! Êtes-vous du genre geek qui aspire à porter un jour de l’aluminium sur sa tête et qui décore son studio avec d’immenses réservoirs remplis de liquide bouillonnant ? Un scientifique prouvant qu’il a assez de matière grise pour changer le monde peut débloquer de nouvelles tenues, comme celle du chasseur d’ovnis, ou encore comme le fantastique laboratoire de chimie pour préparer de nouvelles inventions et des sérums.', 'https://tiermaker.com/images/media/template_images/2024/15057677/sims-4-careers-15057677/ts4careerscientist.png', 'Scientifique', '', 7, 'ACTIVE'),
(12, 'Vous êtes jeune et en bonne santé, alors faites-vous payer par des gens qui ne le sont plus. Tondre des pelouses ou conduire de grosses machines : votre force physique va vous faire gagner de l\'argent.', 'https://tiermaker.com/images/media/template_images/2024/15057677/sims-4-careers-15057677/ts4careermanuallaborer.png', 'Ouvrier', NULL, 6, 'MI_TEMPS'),
(15, 'Si vous savez manier une clé à molette, cette carrière est faite pour vous ! Sous le regard vigilant des propriétaires en détresse, rafistolez et réparez des objets pour votre plus grand plaisir (et celui de votre porte-monnaie) !', 'https://tiermaker.com/images/media/template_images/2024/15057677/sims-4-careers-15057677/ts4careerhandyperson.png', 'Sim à tout faire', NULL, 27, 'MI_TEMPS'),
(16, 'Qui n’aurait pas envie d’être responsable de la santé et du bien-être d’un autre Sim ? Un médecin qui gravit les échelons sera récompensé par des objets comme un éclairage vertical et un squelette grandeur nature pour décorer une chambre d’enfant. Mieux encore : vous pourrez débloquer vos propres blouses d’hôpital et robes de patients pour jouer au docteur chez vous !', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerdoctor.png', 'Médecin', '', 7, 'ACTIVE'),
(19, 'Gagnez de l\'argent de poche en servant à manger à des gens que vous connaissez. Et en nettoyant derrière eux, du moins au début.', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerfastfoodemployee.png', 'Employé de fast-food', NULL, 6, 'MI_TEMPS'),
(20, 'Pensez à votre avenir en débutant dès maintenant votre carrière dans la vente. C\'est en créant des vitrines ou en convainquant des clients que vous gravirez les échelons vers les avantages en nature, les rabais et les simflouz.', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerretailemployee.png', 'Employé de commerce', NULL, 6, 'MI_TEMPS'),
(21, 'Vous avez envie d’être le genre de policier qui n’arrête jamais vraiment de travailler ? Si oui, ce travail est fait pour vous et nous vous offrons des récompenses assez attrayantes pour compenser ce mode de vie pas vraiment sain ! Débloquez des tenues comme votre uniforme de police à porter en pyjama. Donnez une bonne leçon à votre ado pour cette mauvaise note en lui faisant porter une combinaison de prisonnier et en transformant sa chambre avec des murs Barreaux de prison et une caméra de sécurité décorative. De plus, vous pourrez garder un œil sur lui grâce à votre propre miroir tain.', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerdetective.png', 'Détective', '', 7, 'ACTIVE'),
(22, 'Si vous aimez passer du temps dans les cafés et que vous connaissez déjà par cœur tous les noms des boissons sophistiquées, pourquoi ne pas en faire votre métier ?', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerbarista.png', 'Barista', NULL, 6, 'MI_TEMPS'),
(25, 'Soyez payé pour jouer avec des enfants... et assurer leur sécurité. C\'est une grande responsabilité...', 'https://tiermaker.com/images/template_images/2022/337287/sims-4-all-careersupdated-july-2023--337287/ts4careerbabysitter.png', 'Baby-sitter', NULL, 6, 'MI_TEMPS'),
(36, 'Vous pourrez bientôt porter une robe et devenir une Faucheuse ! En tant qu\'employé de la Faucheuse, vous pourrez gravir les échelons de son système tétraédrique et obtenir des récompenses comme le fait de pouvoir discuter d\'affaires mortelles et de posséder un Sablier éternel. Faites en sorte de prédire votre parcours jusqu\'au sommet et parvenez à être le bras droit de la Faucheuse, tout en débloquant une tenue vraiment digne de la Faucheuse en utilisant le Toucher mortel partout où vous allez.', 'https://luniversims.fr/uploads/monthly_2024_10/Sims-4-EP17-Icons(81).png.3984768efadac49083ba9906b94d7b89.png', 'Faucheuse', '', 29, 'ACTIVE'),
(37, 'Envie de jouer aux jeux vidéos pour vous amuser et gagner des simflouz ? Devenez streameur de jeux vidéo pour associer une grande habilité et de l\'humour de base et devenir la star du spectacle (virtuel) !', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.1ee17894018a3742f986778919d2e791.png', 'Streameur de jeux vidéo', NULL, 24, 'MI_TEMPS'),
(38, 'Vive les Womp Womps volants de Copperdale ! Rejoignez l\'équipe de compétition de pom-pom Sims pour améliorer votre forme physique et apprendre de fantastiques mouvements. Entraînez-vous avec votre équipe et participez à la compétition de pom-pom Sims une fois par semaine. Il vous faudra un tapis de pom-pom Sim pour commencer, mais atteignez le titre de capitaine de l\'équipe pour gagner un tapis de pom-pom Sim doré, un drapeau de l\'équipe et un trophée.', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.4f3524898669a13bf0a5b5c81d3f9b11.png', 'Membre de l\'équipe de pom-pom Sims', NULL, 24, 'EXTRASCOLAIRE'),
(39, 'Rejoignez l\'équipe de football américain et améliorez votre forme physique ! Vous pourrez vous entraîner à lancer et à recevoir un ballon et frimer avec ces compétences lors de la Journée du sport. Grâce à ces entraînements de football américain, vous pourrez aussi atteindre le poste de capitaine et gagner un ballon de football américain doré, un drapeau de l\'équipe et un trophée !', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.bb8befdf599a4f7cc7c24315c09a6c50.png', 'Membre de l\'équipe de football américain', NULL, 24, 'EXTRASCOLAIRE'),
(40, 'Sortez votre clavier RVB et rejoignez l\'équipe d\'informatique du lycée ! Développez votre expérience en code en vous entraînant à programmer sur un ordinateur. Si vous commencez cette activité, vous pourrez demander une Foire de la science pendant laquelle vous pourrez participer à un concours de création de jeu vidéo et affronter des invités ! Gravissez les échelons au sein de l\'équipe jusqu\'au titre de capitaine pour gagner un ordinateur portable doré, un drapeau de l\'équipe et un trophée !', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.5353882f4b07252e5bf30ecbf8e9943e.png', 'Membre de l\'équipe d\'informatique', NULL, 24, 'EXTRASCOLAIRE'),
(41, 'Rejoignez l\'équipe d\'échecs du lycée ! Mettez vos compétences logiques à l\'épreuve en participant à cette activité et en rencontrant des membres de l\'équipe avec qui améliorer vos compétences aux échecs. En pratiquant cette activité, vous pourrez demander une Foire de la science du lycée pendant laquelle vous pourrez participer aux problèmes d\'échecs avec d\'autres invités. Gravissez les échelons jusqu\'à celui de capitaine qui vous permet de gagner un échiquier spécial, un drapeau de l\'équipe et un trophée !', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.7a3339493af18afff75e67b277b70ff0.png', 'Membre de l\'équipe d\'échecs', NULL, 24, 'EXTRASCOLAIRE'),
(42, 'Vous avez une webcam ? Vous avez un minimum de personnalité ? Devenez influenSim et de grosses entreprises feront appel à vous pour faire la promotion de leurs derniers produits. Pour commencer à faire des évaluations, trouvez des objets de style de vie comme un échiquier, un chevalet, etc.', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.b47cbe4c401eba58bfea3775d3d5ea70.png', 'InfluenSim', NULL, 24, 'MI_TEMPS'),
(56, 'Soyez votre propre patron ! Choisissez vos horaires de travail ! Cela a l’air génial, n’est-ce pas ? Si vous avez de l’auto-discipline et de la détermination, une carrière d’indépendant pourrait être un très bons choix ! Plusieurs métiers sont disponibles et les agences  sont là pour mettre en contact avec des clients enthousiastes dès aujourd’hui !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/independant-branche-artistes-electrises-artiste.png', 'Artiste indépendant', 'Indépendant', 6, 'INDEPENDANT'),
(57, 'Soyez votre propre patron ! Choisissez vos horaires de travail ! Cela a l’air génial, n’est-ce pas ? Si vous avez de l’auto-discipline et de la détermination, une carrière d’indépendant pourrait être un très bons choix ! Plusieurs métiers sont disponibles et les agences  sont là pour mettre en contact avec des clients enthousiastes dès aujourd’hui !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/independant-branche-mots-percutants-auteur.png', 'Auteur indépendant', 'Indépendant', 6, 'INDEPENDANT'),
(58, 'Soyez votre propre patron ! Choisissez vos horaires de travail ! Cela a l’air génial, n’est-ce pas ? Si vous avez de l’auto-discipline et de la détermination, une carrière d’indépendant pourrait être un très bons choix ! Plusieurs métiers sont disponibles et les agences sont là pour mettre en contact avec des clients enthousiastes dès aujourd’hui !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/independant-branche-experts-informatique-programmeur.png', 'Programmeur indépendant', 'Indépendant', 6, 'INDEPENDANT'),
(59, 'Hé, jeune Sim ! Avez-vous les qualités nécessaires pour devenir scout ? Pour le découvrir, sortez votre boussole et faites du bénévolat dès aujourd\'hui ! En tant que scout vertueux, vous ferez des activités amusantes avec votre troupe et apprendrez tout ce qu\'il faut pour devenir un membre exemplaire de votre communauté.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/scout.png', 'Scout', NULL, 9, 'EXTRASCOLAIRE'),
(60, 'Prenez votre tuba, et au travail ! Un plongeur a pour mission d\'explorer les profondeurs de l\'océan.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/plongeur.png', 'Plongeur', NULL, 20, 'MI_TEMPS'),
(61, 'Détendez-vous au bord de l\'eau et laissez le poisson venir. Pour un pêcheur, le choix du matériel (hameçon, ligne et plomb) est essentiel !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/pecheur.png', 'Pêcheur', NULL, 20, 'MI_TEMPS'),
(62, 'La crème solaire, les sifflets et un requin de temps en temps font partie du quotidien d\'un maître-nageur. Vous adorez nager, la sécurité et hurler sur des enfants turbulents qui essaient de noyer leurs amis ?Alors cette carrière à temps partiel est faite pour vous !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/maitre-nageur.png', 'Maître-nageur', NULL, 20, 'MI_TEMPS'),
(67, 'Le feu des projecteurs vous appelle, les caméras sont braquées sur vous et vous êtes prêtes pour votre gros plan. C\'est à vous d\'insuffler de l\'énergie dans les répliques du script et de vraiment donner vie à vos personnages.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/acteur.png', 'Acteur', NULL, 19, 'ACTIVE'),
(68, 'Qui ne rêve pas d\'aller dans l\'espace ? Devenez astronaute et la galaxie toute entière sera votre terrain de jeu.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/astronaute-branche-commune.png', 'Astronaute', NULL, 6, 'INACTIVE'),
(69, 'Synergie ! Efficacité ! Planification ! Si ces mots à la mode dans les grandes entreprises vous font vibrer alors vous devriez songer à faire carrière dans le monde des affaires !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/affaires-branche-commune.png', 'Affaires', NULL, 6, 'INACTIVE'),
(70, 'Vous avez un don pour interpréter les sentiments, vous adorez le côté excitant des rencontres amoureuses et vous avez envie d\'aider les autres à trouver le grand amour ? Votre destin est peut-être de devenir consultant en amour !', 'https://luniversims.fr/uploads/monthly_2024_07/image.png.a5a4bef667798a84adc2f5c1dddb85df.png', 'Consultant en amour', NULL, 28, 'INACTIVE'),
(71, 'L\'herbaliste s\'appuie sur un savoir approfondi allant de la fabrication d\'élixirs à la fouille du sol pour aider d\'autres Sims à se sentir bien. Si les soins et l\'équilibre vous attirent, cette carrière est faite pour vous ! Débloquez 3 tenues de carrière, de nouvelles interactions sociales comme Informer à propos de l\'équilibre, des interactions de travail inédites dont la possibilité de recevoir des Sims en souffrance à son domicile, des traits de caractère et des objets décoratifs (comme le Lot de cadres Erudition sur Everdew) parfaits pour un bureau.', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.e3f342767d876b8d20602f73396a1f95.png', 'Herbaliste', NULL, 31, 'SEMI_ACTIVE'),
(72, 'Ce n\'est pas un boulot classique. Ici, une journée de travail peut en réalité s\'étirer sur plusieurs jours et chaque petite action permet de faire fonctionner le camp. Que ce soit en nettoyant des cabanes ou en guidant les touristes, préparez-vous à passer vos journées (et vos nuits) au parc Miceli à tenter de faire de la nature un doux foyer ! Le parc Miceli est bien plus difficile d\'accès que le camping Gibbi Gibbi. Il est isolé et situé sur un terrain accidenté. Seules les personnes les plus courageuses pourront l\'atteindre en suivant un sentier peu visité qui part du poste forestier.', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.85eca9cf01a1ddc5f31ea89b35f71d73.png', 'Personnel du parc', NULL, 32, 'INACTIVE'),
(73, 'Soyez payé pour exprimer vos idées avec de belles tournures de phrases et des mots... de merveilleux mots !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/auteur-branche-commune---copie.png', 'Auteur', NULL, 6, 'INACTIVE'),
(74, 'Un athlète doit être fort physiquement, rapide, endurant et intelligent. Lancez-vous dans une carrière dans laquelle les fans enthousiastes crieront votre nom, porteront votre maillot et se souviendront de vos prouesses pour toujours.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/athlete-branche-commune.png', 'Athlète', NULL, 6, 'INACTIVE'),
(75, 'Vivez dans le secret en tant qu\'agent sous couverture. De l\'infiltration du QG ennemi à l\'art de l\'interrogatoire, plus vous apprendrez de choses, moins vous aurez de chances d\'être découvert.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/agent-secret-branche-commune.png', 'Agent secret', NULL, 6, 'INACTIVE'),
(76, 'Embrassez cette carrière pour assister les morts et les vivants ! Que ce soit en creusant des tombes ou en embaumant des corps, les Sims qui travaillent dans l\'industrie funéraire s\'assurent que rien ne vienne troubler le repos éternel de leurs congénères. Cette spécialisation vous prépare à affronter des moments difficiles comme Discuter des services funéraires ou Réfléchir à l\'existence. Pour récompenser votre travail six pieds sous terre, vous pourrez obtenir un masque de médecin de la peste, un buste de Murphy Membrane ou une plaque commémorative en souvenir de vos accomplissements.', 'https://luniversims.fr/uploads/monthly_2024_10/image.png.0821e24f330d9b9876cb79c2f4213d15.png', 'Personnel de pompes funèbres', NULL, 29, 'INACTIVE'),
(77, 'Vous rêvez de voir votre nom en haut de l\'affiche depuis que vous savez l\'épeler (peut-être même avant). Satisfaites votre vocation et devenez célèbre en tant qu\'artiste professionnel : soit en faisant rire le public avec vous, soit en faisant fondre leurs cœurs avec vos mélodies.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/artiste-branche-commune.png', 'Artiste', NULL, 6, 'INACTIVE'),
(78, 'Certains Sims n\'ont aucune envie de respecter les règles. Une vie d\'hors-la-loi peut aussi être amusante et permettre de gagner beaucoup de simflouz.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/criminel-branche-commune.png', 'Criminel', NULL, 6, 'INACTIVE'),
(79, 'Tout le monde peut préparer un dîner ou une boisson. La carrière culinaire est destinée à ceux qui veulent passer au niveau supérieur et gagner leur vie en cuisinant.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/culinaire-branche-commune.png', 'Culinaire', NULL, 6, 'INACTIVE'),
(80, 'En identifiant les bonnes couleurs, les motifs tendance et l\'association novatrice puis en identifiant la bonne personne pour incarner cette vision, l\'influenceur de style peut  peut changer le monde pour lui donner plus de cohésion.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/influenceur-style-branche-commune.png', 'Influenceur de style', NULL, 6, 'SEMI_ACTIVE'),
(81, 'Qui a besoin d\'aller à l\'université avec des compétences en programmation telles que les vôtres ? Les opportunités sont là, et vous et votre gros cerveau êtes prêts à les saisir.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/gourou-technologies-branche-commune.png', 'Gourou des technologies', NULL, 6, 'INACTIVE'),
(82, 'Créez votre propre univers avec quelques coups de pinceaux ! Faites-vous une place dans le monde de l\'art avec des chefs d\'œuvre hyper réalistes ou des œuvres abstraites d\'une beauté déconcertante.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/peintre-branche-commune.png', 'Peintre', NULL, 6, 'INACTIVE'),
(83, 'Vous avez regardé tous les documentaires sur la nature disponibles, et vous savez à quel point la planète est en danger. De l\'éducation du public aux expéditions  de recherche, vous voulez vraiment faire une différence. Le changement ne se fera pas en un jour, mais si vous persistez, votre dur travail pourrait permettre à des écosystèmes de prospérer !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/ecologiste-branche-commune.png', 'Écologiste', NULL, 20, 'SEMI_ACTIVE'),
(84, 'La forme physique et la discipline seront essentielles pour réussir une carrière militaire. Gravir les échelons ne sera pas facile à moins de réussir à démontrer vos capacités physiques ainsi que votre talent pour recruter et diriger d\'autres Sims. Allez-vous suivre la voie permettant de devenir un jour maréchal, ou opter pour une voie plus secrète afin de découvrir ce que des Sims pourraient cacher ?', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/militaire-branche-commune.png', 'Militaire', NULL, 38, 'SEMI_ACTIVE'),
(85, 'Vous avez toujours eu la main verte et espérez désormais vous en servir pour gagner votre vie. Au début, vous passerez beaucoup de temps à planter des graines et à jardiner, mais continuez vos efforts et vous pourrez réussir dans la science OU l\'art des plantes !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/jardinier-branche-commune.png', 'Jardinier', NULL, 9, 'SEMI_ACTIVE'),
(86, 'Tout le monde a une opinion : mais tout le monde n\'est pas payé pour en avoir une ! Les Sims convaincus d\'avoir un avis supérieur peuvent se lancer dans une carrière de critique. Qu\'il s\'agisse de gastronomie ou d\'art, votre Sim aura quelque chose à dire et tout le monde l\'écoutera !', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/critique-branche-commune-ep03.png', 'Critique', NULL, 17, 'SEMI_ACTIVE'),
(87, 'Rejoignez une vie au service du public ! Des manifestations contre les injustices aux collectes de dons pour les bonnes causes, voire même des pots-de-vin lorsque cela est nécessaire, la politique est toujours intéressante.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/politique-branche-commune.png', 'Politique', NULL, 17, 'SEMI_ACTIVE'),
(88, 'Qu’est-ce qui est populaire ? Où est la meilleure nourriture de la ville ? Qui est la célébrité la plus intéressante ? Commencez une carrière dans les médias sociaux pour être la personne qui répond à ces questions pour ses abonnés. Écrivez sur votre blog et signalez votre présence dans différents endroits afin de fidéliser vos abonnés.', 'https://tiermaker.com/images/media/template_images/2024/18879229/sims-4-careers-18879229/reseaux-sociaux-branche-commune-ep03.png', 'Réseaux sociaux', NULL, 17, 'SEMI_ACTIVE');
INSERT INTO `competence` (`id`, `description`, `img`, `niveau_max`, `nom`, `dlc_id`, `categorie_sim`) VALUES
(2, 'Tout le monde peut cuisiner, mais les Sims qui aiment manger de bonnes choses ont tout intérêt à accorder un peu plus de temps et d\'attention à la cuisine.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/cooking.png', 10, 'Cuisine', 6, 'ADULTE'),
(3, 'Du téléphone à l\'appareil photo sophistiqué : les Sims compétents en Photographie auront plus de succès s\'ils peaufinent leurs compétences en prenant beaucoup de photos, en achetant du matériel plus avancé, en testant différents paramètres d\'image et en utilisant le studio photo Flash.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/photography.png', 5, 'Photographie', 7, 'ADULTE'),
(4, 'Faîtes-le vous même ! Telle est la devise d\'une personne bricoleuse. Les personnes bricoleuses n\'ont pas peur de réparer les choses lorsqu\'elles se brisent, peuvent améliorer des objets communs du foyer et même faire un peu d\'ébénisterie.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/handiness.png', 10, 'Bricolage', 6, 'ADULTE'),
(5, 'Lors d\'une conversation, la compétence Charisme peut être votre meilleure alliée. Que ce soit pour lier des amitiés, séduire quelqu\'un ou calmer des personnes inconnues, les Sims charismatiques savent s\'y prendre.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/charisma.png', 10, 'Charisme', 6, 'ADULTE'),
(6, 'Dès que l\'on réalise que la vie entière est une blague, devenir humoriste devient le seul choix de carrière logique.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/comedy.png', 10, 'Comédie', 6, 'ADULTE'),
(7, 'Envie de poser de nouveaux jalons en matière de cuisine ? La compétence Cuisine gastronomique vous permet de préparer de l\'excellente nourriture pour vous-même et vos convives.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/gourmet-cooking.png', 10, 'Cuisine gastronomique', 6, 'ADULTE'),
(8, 'Coucher ce que l\'on ressent sur papier (ou, le plus souvent, sur écran), n\'est pas une ennemie redoutable, mais chaque jour, les Sims qui écrivent relèvent le défi de mettre des mots sur les émotions.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/writing.png', 10, 'Écriture', 6, 'ADULTE'),
(9, 'Même si tout le monde veut rester en forme, les Sims fans de fitness font bien plus que le strict minimum pour être au top de leur forme.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/fitness.png', 10, 'Fitness', 6, 'ADULTE'),
(10, 'Il y a des gens qui gardent les pieds sur terre et la tête baissée. Mais ce n\'est pas votre cas ! Libérez-vous des chaînes du quotidien et repoussez les frontières de l\'infini. Construisez, améliorez et volez là où personne n\'est jamais allé avec la compétence Fuséologie.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/rocket-science.png', 10, 'Fuséologie', 6, 'ADULTE'),
(11, 'La guitare : le seul instrument utilisé par tout le spectre musical, et dans tous les pays. Elle est particulièrement bien adaptée à un dîner romantique, une petite soirée entre potes ou un concert à guichets fermés.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/guitar.png', 10, 'Guitare', 6, 'ADULTE'),
(12, 'Comment pousse votre jardin ? Vous pouvez y cultiver des fleurs et des fruits à foison, mais un tel projet demande du temps et des efforts ainsi qu\'un niveau élevé de compétence Jardinage.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/gardening.png', 10, 'Jardinage', 6, 'ADULTE'),
(13, 'Autrefois, avoir un bon niveau en jeux vidéo ne servait qu\'à se vanter devant ses frères et sœurs, mais dans notre fantastique nouveau monde, les prouesses aux jeux vidéo peuvent rapporter beaucoup d\'argent et vous rendre célèbre ! Notre époque est tellement loufoque.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/videogaming.png', 10, 'Jeux vidéo', 6, 'ADULTE'),
(14, 'Avoir l\'esprit agile, c\'est formidable, et les Sims qui se concentrent sur la compétence Logique exercent leur esprit jusqu\'à ce que celui-ci soit plus affûté que la corne d\'une lamacorne.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/logic.png', 10, 'Logique', 6, 'ADULTE'),
(15, 'Les Sims ayant la compétence Malice ont généralement un comportement sournois et adorent jouer des tours, faire des farces ou se lancer dans toute autre activité leur permettant de ridiculiser d\'autres Sims. La vie est une fête, et les Sims malicieux et malicieuses comptent bien s\'y inviter.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/mischief.png', 10, 'Malice', 6, 'ADULTE'),
(16, 'Préparer des boissons tout en discutant de tout et de rien peut sembler assez facile, mais déterminer les bonnes proportions de jus de fruits et la bonne quantité de discussion est une compétence subtile.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/mixology.png', 10, 'Mixologie', 6, 'ADULTE'),
(17, 'L\'art de manier le pinceau sur une toile et de créer quelque chose qui provoquera une réaction émotionnelle n\'est pas aisé. Pour les Sims qui explorent la compétence Peinture, l\'avenir est pavé de créations colorées, et peut-être de chefs-d\'œuvre qui se vendront à prix d\'or.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/painting.png', 10, 'Peinture', 6, 'ADULTE'),
(18, 'Il n\'y a que les pianistes qui peuvent apaiser l\'ouïe des Sims en pianotant sur des touches noires et blanches. Pratiquez encore et encore cette compétence Piano; même si vous ne devenez jamais une rockstar, votre musique sera jouée dans les ascenseurs pour toujours.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/piano.png', 10, 'Piano', 6, 'ADULTE'),
(19, 'Comme savoir parler une seconde langue, savoir programmer  est de plus en plus essentiel de nos jours. Si vous savez programmer, les machines feront tout le sale boulot pour vous !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/programming.png', 10, 'Programmation', 6, 'ADULTE'),
(20, 'La plupart des Sims ayant cette compétence se sentent comme un poisson dans l\'eau à l\'idée de parler de leur passion, mais les autres essaieront plutôt de noyer le poisson !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/fishing.png', 10, 'Pêche', 6, 'ADULTE'),
(21, 'Entre air qui prend aux tripes et dans folklorique, le violon peut évoquer une multitude d\'émotions. Passez des sons grinçants désagréables aux accords harmonieux avec la compétence Violon.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/violin.png', 10, 'Violon', 6, 'ADULTE'),
(22, 'La pâtisserie est une véritable science; impossible de se contenter de jeter des ingrédients au hasard dans un saladier ! Il faut avoir un plan. Heureusement, ce plan implique de grosses quantités de sucre.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/baking.png', 10, 'Pâtisserie', 7, 'ADULTE'),
(23, 'Tout le monde peut faire tourner un disque, mais seuls les Sims ayant la compétence DJ sont toujours prêts à mixer. Ils peuvent utiliser la cabine de DJ, créer des mix et divertir un public.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/dj-mixing.png', 10, 'DJ', 16, 'ADULTE'),
(24, 'Les Sims ayant cette compétence ne peuvent pas résister à l\'envie de danser. Ils adorent bouger sur de la musique et sont toujours prêts à aller sur la piste de danse.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/dancing.png', 5, 'Danse', 16, 'ADULTE'),
(25, 'Tout le monde peut chante, mais bien chanter est une autre affaire ! Les Sims ayant la compétence Chant adorent pousser la chansonnette n\'importe où.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/singing.png', 10, 'Chant', 17, 'ADULTE'),
(26, 'Faire des tours fait partie des choses basiques qu\'on attend d\'un chien. Une fois dressé, le chien peut faire un tour sur commande.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/pet-training.png', 5, 'Dressage', 18, 'ADULTE'),
(27, 'Être un fantastique vétérinaire nécessite des mains qui ne tremblent pas, un cœur plein de compassion et de bonnes connaissances en anatomie animale.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/veterinarian.png', 10, 'Vétérinaire', 18, 'ADULTE'),
(28, 'Un Sim possédant la compétence Production de médias connaît bien les technologies actuelles qui permettent de produire de la musique et des vidéos. Ces Sims diffusent et mettent en ligne du contenu pour le partager avec le monde entier ou gagnez quelques simflouz.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/media-production.png', 5, 'Production de médias', 19, 'ADULTE'),
(29, 'Associer des fleurs de manière complexe nécessite d\'incroyables compétences. Développer celles-ci permet non seulement de créer de magnifiques œuvres naturelles, mais aussi de susciter chez les Sims des sentiments qui peuvent les surprendre.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/flower-arranging.png', 10, 'Compositions florales', 9, 'ADULTE'),
(30, 'La capacité de donner vie à un personnage, de raconter une histoire et d\'émouvoir les Sims aux larmes est un véritable art. La vie est la toile de ces artistes.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/acting.png', 10, 'Jeu d\'acteur', 19, 'ADULTE'),
(31, 'La compétence Recherche et débat implique d\'apprendre des informations puis de les utiliser, que ce soit lors d\'un débat ou pour influencer quelqu\'un.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/research-and-debate.png', 10, 'Recherche et débat', 21, 'ADULTE'),
(32, 'La technologie devrait permettre d\'améliorer la vie des Sims. Créer des robots pour faire les corvées, protéger les Sims et les divertir permet aux Sims de faire... autre chose !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/robotics.png', 10, 'Robotique', 21, 'ADULTE'),
(33, 'Pourquoi acheter neuf quand on peut fabriquer quelque chose soi-même ? Recyclez de vieux objets délabrés et utilisez les débris et morceaux pour fabriquer votre propre création !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/fabrication.png', 10, 'Fabrication d\'objets', 12, 'ADULTE'),
(34, 'Les Sims ayant cette compétence ont une curiosité naturelle pour l\'art de la pétillerie. Qu\'il s\'agisse d\'un loisir ou d\'un emploi à temps partiel, l\'expérimentation est essentielle. Ces Sims sont donc souvent en train de tester différents ingrédients et processus pour peaufiner leur compétence.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/juice-fizzing.png', 5, 'Pétillerie', 12, 'ADULTE'),
(35, 'Les Sims aventureux adorent relever le défi de grimper sur les parois de montagnes, et progresser dans cette compétence physique débloque de nouvelles façons de grimper ainsi que l\'accès à de nouvelles zones et vues.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/rock-climbing.png', 10, 'Escalade', 22, 'ADULTE'),
(36, 'Les Sims ayant la compétence Ski vivent pour sentir le vent froid sur leur visage et glisser avec aisance sur les pistes.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/skiing.png', 10, 'Ski', 22, 'ADULTE'),
(37, 'Envie de frimer avec des figures ? Ce Sim peut améliorer sa compétence Snowboard pour ressentir des sensations fortes incomparables !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/snowboarding.png', 10, 'Snowboard', 22, 'ADULTE'),
(38, 'Rien n\'évoque mieux l\'amour et la patience qu\'une œuvre d\'art minutieusement brodée ! Les créations au point de croix sont parfaites pour décorer votre intérieur, être vendues ou être offertes aux petits animaux qui se baladent dans votre jardin. Faites votre choix parmi 3 tailles de cercler et lancez-vous ! Vous allez vous amuser au plus haut point !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/cross-stitch.png', 5, 'Point de croix', 23, 'ADULTE'),
(39, 'Vous voulez transformer votre idée pour qu\'elle devienne une petite entreprise puis un empire commercial ? Développez votre compétence Entrepreneuriat en progressant dans vos carrières à temps partiel et en excellant dans les petits boulots et les carrières en indépendant !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/entrepreneur.png', 5, 'Entrepreneuriat', 24, 'ADULTE'),
(40, 'La fabrication de nectar associe l\'art subtil d\'extraire les saveurs essentielles d\'une grande variété d\'ingrédients avec l\'art moins subtil d\'écraser ces ingrédients pour en faire de la pulpe.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/nectar-making.png', 5, 'Fabrication de nectar', 26, 'ADULTE'),
(41, 'L\'équitation peut être une activité  de loisir, un moyen de transport ou un outil pour gagner des concours. Cette compétence reflète les capacités en équitation de votre Sim plutôt que celles du cheval.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/riding.png', 10, 'Équitation', 26, 'ADULTE'),
(42, 'Tout le monde peut être romantique, mais bientôt, ces Sims respireront le romantisme. Les Sims romantiques réussiront plus souvent les actions liées à leurs histoires de cœur.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/romance.png', 10, 'Romantique', 28, 'ADULTE'),
(43, 'Plongez un orteil dans le Marécage funeste de la connaissance en étudiant la mort et la perte. Les Sims attirés par cette vocation morose finiront par pouvoir participer à l\'expression d\'une langue mourante ou à la création d\'une friandise pleine d\'âme qui fait du bien aux besoins. Cette compétence est vraiment une tuerie !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/thanatology.png', 5, 'Thanatologie', 29, 'ADULTE'),
(44, 'Comment un amoureux de la nature peut-il profiter au mieux des cadeaux de la forêt ? Les herbes rares et merveilleuses ne sont pas que de jolis végétaux, ce sont aussi de précieux ingrédients !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/herbalism.png', 10, 'Herboristerie', 33, 'ADULTE'),
(45, 'Un Sim qui acquiert la compétence Bien-être est un Sim qui sait réguler ses humeurs et son ressenti à mesure qu\'il avance sur le chemin chaotique de la vie.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/wellness.png', 10, 'Bien-être', 34, 'ADULTE'),
(46, 'Les Sims assoiffés de connaissance planteront leurs dents dans ces livres. Il faudrait être fou pour se priver des précieux conseils qu\'ils contiennent.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/vampire-lore.png', 15, 'Coutumes de Vampires', 36, 'ADULTE'),
(47, 'L\'orgue est l\'instrument idéal pour els pianistes qui veulent se surpasser. C\'est le plus grand instrument au monde. Il fera à coup sûr grande impression lors de votre prochaine jam.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/pipe-organ.png', 10, 'Orgue', 36, 'ADULTE'),
(48, 'L\'art du tatouage permet aux Sims de décorer le corps des autres avec de magnifiques tatouages, tout en gagnant beaucoup de simflouz par la même occasion. Les tatouages peuvent même être un hommage permanent à un être cher (du moins jusqu\'à ce que la personne paie pour un détatouage).', 'https://luniversims.fr/uploads/monthly_2025_03/large.0x00000000!0x3FFE4A5F24FB2745_0x00B2D882.png.9dc894639e47b54806cb6375f21ea9b6.thumb.png.9ba59a69bf455904ce5bfdf14e138934.png', 10, 'Tatouage', 30, 'ADULTE'),
(49, 'Transformez des morceaux d\'argile informes en magnifiques chefs-d\'œuvre ! Les Sims qui ont la compétence Poterie fabriquent leurs propres créations en céramique qui peuvent décorer une maison ou être vendues à une clientèle enthousiaste !', 'https://luniversims.fr/uploads/monthly_2025_03/large.Pottery_Discord.png.fb9385638a381d2d45813e021378f2ce.thumb.png.58182280ff181e5f49602701a2d7b2f1.png', 10, 'Poterie', 30, 'ADULTE'),
(50, 'Transformez des produits à récolter ordinaires en fantastiques élixirs d\'apothicaire qui guérissent une grande variété de syndromes et améliorent la vie des Sims.', 'https://luniversims.fr/uploads/monthly_2025_06/0x00000000!0x9b3572d056258bc1.0x00b2d882.png.85a277424316dcd6a9a75170151dd214.png', 10, 'Apothicaire', 31, 'ADULTE'),
(51, 'Menez une vie de bohème avec cette compétence qui supprime la frontière entre intérieur et extérieur.', 'https://luniversims.fr/uploads/monthly_2025_06/0x00000000!0xdf2532e6c44313ca.0x00b2d882.png.2247d4044382cda693daf16195d60fa6.png', 10, 'Vie dans la nature', 31, 'ADULTE'),
(52, 'Mettre une flèche en plein dans le mille, c\'est bien plus complexe que simplement la tirer en l\'air. Maîtriser le tir à l\'arc peut demander des heures et des heures d\'entraînement.  Vous pouvez améliorer la compétence Tir à l\'arc en vous entraînant sur une cible ou en participant à des compétitions de tir à l\'arc.', 'https://luniversims.fr/uploads/monthly_2025_09/0x00000000!0x1bc98cdebfa1d610.0x00b2d882.png.da830d6a55001d1715ac1e2e325461f1.png', 5, 'Tir à l\'arc', 32, 'ADULTE'),
(53, 'Pour les Sims qui voudraient s\'envoler vers les cieux (et avoir l\'air super cool au passage), le plongeon est le sport aquatique idéal !  Le plongeon peut se faire depuis les plongeoirs en bord de piscine, qu\'ils soient bas ou hauts.', 'https://luniversims.fr/uploads/monthly_2025_09/0x00000000!0x46f0a69ce5590a27.0x00b2d882.png.593b1644630536b6a2e288a8ad1f5c0c.png', 5, 'Plongeon', 32, 'ADULTE'),
(54, 'Maîtrisez la compétence Entomologie en apprenant à attraper et examiner les papillons et papillons de nuit dans leurs habitats naturels. Prenez soin de ces insectes pendant l\'incubation et observez leur cycle de vie fascinant pour gagner de l\'expérience de terrain.', 'https://luniversims.fr/uploads/monthly_2025_09/0x00000000!0x1d3ca88df6e5364b.0x00b2d882.png.742f833fcd074a81d0cd6d30f121eb0d.png', 5, 'Entomologie', 32, 'ADULTE'),
(55, 'L\'art de créer des objets en papier en deux ou trois dimensions en découpant, pliant, assemblant, superposant ou collant du papier et bien plus. Les Sims peuvent offrir leurs créations en papier à d\'autres Sims ou les exposer fièrement dans leur maison.', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.dbb581b048cc56ec011f0a8bcae51096.png', 10, 'Art du papier', 32, 'ADULTE'),
(56, 'Un parent compétent sait quand influencer, quand encourager et quand discipliner un petit Sim. Il connait le meilleur moyen de laver un enfant et sait satisfaire ses besoins.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/parenting.png', 10, 'Éducation', 10, 'ADULTE'),
(57, 'Certains Sims se passionnent pour la recherche de connaissances et de trésors anciens. Passer un peu de temps les mains dans la terre peut être très gratifiant.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/archaeology.png', 10, 'Archéologie', 37, 'ADULTE'),
(58, 'Les Sims passionnés de culture selvadoradienne s\'y plonge totalement. Ils risquent moins de faire des commentaires gênants et ont plus de chance de réussir ces pas de danse complexes.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/selvadoradian-culture.png', 5, 'Culture selvadoradienne', 37, 'ADULTE'),
(59, 'Certains diront que le bowling est une compétence mineure, mais ce n\'est le cas que d\'un point de vue technique. En effet, même si cette compétence ne comporte que 5 niveaux, les Sims qui feront l\'effort de la développer seront incontestablement cools. Ils débloqueront des boules de bowling supplémentaires et réaliseront peut-être même un jouer un Lama parfait en ne faisant que des strikes pendant une partie.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/bowling.png', 5, 'Bowling', 51, 'ADULTE'),
(60, 'Installez-vous confortablement et mettez un peu de musique, car il est l\'heure de tricoter ! Utilisez vos talents pour habiller votre famille, décorer votre maison ou gagner quelques simflouz. Il n\'y a que de bonnes raisons de tricoter, alors n\'hésitez pas à vous lancer !', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/knitting.png', 10, 'Tricot', 14, 'ADULTE'),
(61, 'Peaufinez votre pouvoir spirituel ! Les Sims se lançant dans ce parcours finiront par pouvoir faire des choses comme invoquer les morts ou organiser leur propre séance de spiritisme avec d\'autres Sims.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/medium.png', 5, 'Médium', 57, 'ADULTE'),
(62, 'Même si tout le monde peut apprécier une pierre précieuse brillante, les Sims qui ont la compétence Gemmologie apprennent à fabriquer leurs propres créations avec des pierres précieuses pour les porter, les offrir ou en tirer des bénéfices.', 'https://tiermaker.com/images/media/template_images/2024/262376/sims-4-skills-262376/gemology.png', 10, 'Gemmologie', 59, 'ADULTE'),
(63, 'Parler est une étape essentielle pour un bambin.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/comunicacinpng.png', 5, 'Communication', 6, 'BAMBIN'),
(64, 'Les bambins ayant de l\'imagination jouent dans leur propre monde.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/imaginacinpng.png', 5, 'Imagination', 6, 'BAMBIN'),
(65, 'Les bambins qui se concentrent sur la compétence Mouvement n\'arrêtent vraiment pas de bouger.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/movilidadpng.png', 5, 'Mouvement', 6, 'BAMBIN'),
(66, 'Apprendre à un bambin à aller sur le pot permet de reléguer les couches au passé.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/control-de-pip-y-poppng.png', 3, 'Pot', 6, 'BAMBIN'),
(67, 'La compétence Réflexion permet aux bambins de piquer moins de crises et d\'être plus autonomes. Elle réduit les provocations et aide à satisfaire les besoins.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/razonamientopng.png', 5, 'Réflexion', 6, 'BAMBIN'),
(68, 'Utiliser son imagination est l\'une des principales caractéristiques de l\'enfance, et développer cette imagination peut être très payant dans l\'avenir.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/creatividadpng.png', 10, 'Créativité', 6, 'ENFANT'),
(69, 'Le cerveau d\'un enfant est plus petit que celui d\'un adulte mais il est aussi moins pollué par certaines bêtises. Les enfants capables de solliciter leur cerveau dès le plus jeune âge seront plus aptes à appréhender la logique la plus complexe plus tard.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/inteligenciapng.png', 10, 'Facultés mentales', 6, 'ENFANT'),
(70, 'La compétence Facultés motrices est essentielle pour tous les enfants; elle leur permet non seulement de marcher, courir et sauter, mais peut aussi servir à développer des muscles très tôt pour se préparer à une vie entière de sport.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/motricidadpng.png', 10, 'Facultés motrices', 6, 'ENFANT'),
(71, 'Apprendre à parler est la première étape du parcours d\'un enfant pour devenir une créature sociale. Les enfants qui décident de se concentrer sur la compétence Facultés sociales lieront plus facilement des amitiés au cours de leur vie.', 'https://tiermaker.com/images/chart/chart/the-sims-4-skills-including-children-and-toddler-skills-874726/relacin-socialpng.png', 10, 'Facultés sociales', 6, 'ENFANT'),
(72, 'La compétence Tempérament se développe lorsque quelqu\'un s\'occupe du cheval et interagit avec lui.', 'https://luniversims.fr/uploads/monthly_2023_07/image.png.3ca0c1552b1640b303f565b435035bfe.png', 10, 'Tempérament', 26, 'CHEVAL'),
(73, 'La compétence Agilité se développe grâce au dressage avec des tonneaux pour chevaux. Pour ce faire, cliquer sur les tonneaux et \"Indiquer au cheval de...\" ou bien monter le cheval et choisir l\'une des autres options.', 'https://luniversims.fr/uploads/monthly_2023_07/image.png.d376be99772f71d83ec7ea69a49c8bfe.png', 10, 'Agilité', 26, 'CHEVAL'),
(74, 'La compétence Saut d\'obstacles se développe grâce au dressage avec un obstacle pour chevaux. Pour ce faire, cliquer sur les tonneaux et \"Indiquer au cheval de...\" ou bien monter le cheval et choisir l\'une des autres options.', 'https://luniversims.fr/uploads/monthly_2023_07/image.png.92e8d51e71c190c8b7490bacc79e18a7.png', 10, 'Saut d\'obstacles', 26, 'CHEVAL'),
(75, 'La compétence Endurance se développe en faisant des promenades.', 'https://luniversims.fr/uploads/monthly_2023_07/image.png.29d8b83f2c87ad5310aa35f650285ece.png', 10, 'Endurance', 26, 'CHEVAL'),
(76, 'Une compétence parfaite pour les Sims qui souhaitent en provoquer d\'autres en duel et remporter des récompenses grâce à leur maîtrise de l\'épée !', 'https://luniversims.fr/uploads/monthly_2026_02/image.png.90fba952abcf07b1a0eeba1505f92cc6.png', 10, 'Maniement de l\'épée', 117, 'ADULTE');
INSERT INTO `dlc` (`id`, `date_sortie`, `description`, `img`, `nom`, `type`) VALUES
(6, '2014-09-05', 'Libérez votre imagination et créez un monde de Sims totalement unique. Explorez et personnalisez les moindres détails de vos Sims et de vos maisons, et bien plus encore. Choisissez l\'apparence, le comportement et le look de vos Sims. Déterminez la manière dont ils vivront au quotidien. Concevez et construisez des maisons incroyable pour chaque famille, puis décorez-les avec vos meubles et objets préférez. Allez dans différents quartiers où vous pourrez rencontrer d\'autres Sims et en savoir plus à leur sujet. Découvrez de magnifques endroits aux environnements distinctifs et vivez des aventures spontanées. Gérez les hauts et les bas du quotidien de vos Sims et découvrez ce qui se passe lorsque vous créez des scénarios réalistes ou fantaisistes. Racontez vos histoires à votre manière en développant des relations, en menant des carrières et en réalisant des aspirations à long terme dans ce jeu extraordinaire où les possibilités sont illimitées.', 'https://tiermaker.com/images/media/template_images/2024/15649919/sims-4-all-packs-franais---2024-15649919/zzzzz-1737837397bg.png', 'Les Sims 4', 'BASE'),
(7, '2015-04-02', 'Avec Les Sims 4 Au Travail, contrôlez des lieux de travail ! Contrôlez activement vos Sims au travail et décidez s\'ils vont décrocher une grosse promotion ou devenir une menace sur leur lieu de travail. Portez secours à d\'autres Sims et sauvez d\'innombrables vies en tant que médecin, tourmentez vos voisins avec des inventions malicieuses en tant que scientifique ou enquêtez sur des scènes de crime et résolvez de grosses affaires en tant que détective. Si vous préférez être votre propre patron, vous pouvez même créer, personnaliser et gérer vos propres magasins pour devenir simflouzionnaire ! À vous de choisir comment vos Sims se mettent au travail.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/03png.png', 'Au Travail', 'EXTENSION'),
(8, '2022-06-16', 'Hurlez à la lune dans le pack de jeu Les Sims 4 Loups-garous ! Vos Sims vont se transformer, rejoindre des meutes et laisser libre cours à leur instinct pendant la pleine lune. Explorez le monde de Moonwood Mill et découvrez les secrets des loups-garous en menant votre nouvelle vie de lycanthrope. Vos Sims débloqueront de nouvelles compétences, géreront de nouveaux tempéraments et rencontreront peut-être même leurs partenaires prédestinés.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/55png.png', 'Loups-Garous', 'JEU'),
(9, '2018-06-22', 'Ajoutez la météo dans la vie de vos Sims pour raconter de nouvelles histoires, profiter d\'activités saisonnières et célébrer des jours fériés riches en émotions avec Les Sims 4 Saisons. Profitez pleinement de la météo toute l\'année, des chutes de neige glaciales aux canicules accablantes : chaque monde est influencé par les saisons de manière unique. Créez une histoire hivernale où vos Sims font du patin à glace, liez-vous d\'amitié avec un épouvantail magique pendant la récolte d\'automne, vivez une amourette de printemps sous une averse ou organisez une fête près de la piscine en été. Réunissez vos amis et votre famille pour célébrer des jours fériés incluant des traditions, des cadeaux et des invités spéciaux. Restez au chaud ou au frais grâce à des tenues inédites faites pour affronter les éléments. Vous pouvez même commencer une carrière florissante dans le jardinage en tant que botaniste ou créateur de compositions florales !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/26png.png', 'Saisons', 'EXTENSION'),
(10, '2017-05-30', 'Développez les compétences en éducation de votre Sim pour lui permettre d’accompagner ses enfants jusqu’à l’âge adulte avec Les Sims 4 Être parents. Choisissez quand sanctionner ou encourager les comportements des enfants, enseignez-leur de bonnes valeurs et ayez un impact durable sur leur avenir. Découvrez des activités en famille amusantes et personnalisez votre foyer avec de nouvelles décorations d’intérieur et des vêtements inédits pour toute la famille.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/19png.png', 'Être parents', 'JEU'),
(12, '2020-06-05', 'Vous souhaitez que vos Sims aient un impact sur leur monde ? Emménagez dans une communauté de créateurs collaboratifs dans le pack d\'extension Les Sims 4 Écologie ! Jouez pour changer les choses et faire la différence dans le nouveau monde d\'Evergreen Harbor. Aidez vos nouveaux voisins à décider d’un projet d\'espace communautaire, réduisez votre empreinte écologique et observez la transformation de votre quartier. Vous serez surpris de ce qui se passera lorsque vos Sims commenceront à définir les règles.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/34png.png', 'Écologie', 'EXTENSION'),
(14, '2020-07-27', 'Préparez votre laine et vos aiguilles à tricoter : dans le kit d\'objets Les Sims 4 Tricot de pro, les Sims peuvent fabriquer leurs propres vêtements, jouets et objets décoratifs tricotés ! Les Sims de tout âge peuvent s\'asseoir dans leur nouveau fauteuil à bascule et commencer à créer. Quand vous aurez terminé, portez ce que vous avez tricoté ou vendez-le sur la nouvelle plateforme de shopping en ligne, Plopsy. Maîtrisez le tricot — Tricotez des vêtements pour toute la famille ou des décorations pour votre maison comme des porte-plantes suspendus, des tapis et même des jouets pour les enfants ! Une fois que vous avez amélioré vos compétences, enseignez le tricot à d\'autres Sims pour transmettre votre savoir. Basculez dans un univers de détente — Installez-vous dans l\'une des quatre nouvelles variantes de fauteuil à bascule pour vous détendre, tricoter, faire la sieste ou lire. Les Sims âgés disposent également d\'une interaction inédite pour se remémorer le passé. Rappelez-vous de votre jeunesse en profitant d\'un confort total. Faites du shopping en ligne avec Plopsy — Plus vous tricotez, plus vous pouvez gagner de simflouz sur Plopsy, le nouveau marché en ligne d\'objets artisanaux. Vendez ou achetez toute sortes de choses, des chaussettes aux pulls en passant par des toiles et des projets d\'ébénisterie.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/35png.png', 'Tricot de pro', 'OBJETS'),
(16, '2015-12-10', 'Créez et rejoignez des groupes avec des centres d\'intérêt, des personnalités et des styles différents dans lesquels vous pouvez définir les règles, choisir le look des membres et personnaliser leurs lieux de prédilection. Retrouvez d\'autres Sims pour faire des activités collectives excitantes et profiter pleinement de la vie dans le magnifique monde de Windenburg !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/09png.png', 'Vivre Ensemble', 'EXTENSION'),
(17, '2016-11-03', 'Vos Sims ont envie de quitter leur banlieue résidentielle ? Réalisez leurs rêves dans la ville de San Myshuno, où ils pourront découvrir des quartiers excitants, emménager dans un nouvel appartement, aller à des festivals amusants, et bien plus encore. Dans Les Sims 4 Vie Citadine, vos Sims peuvent découvrir les joies et les défis de vivre à proximité d’autres Sims. Gravissez les échelons pour passer du petit appartement à l’appartement-terrasse en faisant mener de nouvelles carrières à vos Sims !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/15png.png', 'Vie Citadine', 'EXTENSION'),
(18, '2017-11-10', 'Créez une grande variété de chiens et de chats, faîtes-les adopter par vos foyers de Sims pour changer leurs vies pour toujours et occupez-vous des animaux du quartier en tant que vétérinaire avec Les Sims 4 Chiens et Chats. Le nouvel outil puissant Créer un animal vous permet de personnaliser les chiens et les chats et de leur donner une apparence unique, un comportement distinct et, pour la première fois, des tenues expressives ! Ces merveilleux compagnons seront aux côtés de vos Sims toute leur vie et changeront leur quotidien de manière inédite et spéciale. Soignez leurs maladies en tant que vétérinaire et gérez votre propre clinique dans un magnifique monde au bord de la mer avec toutes sortes de choses à découvrir pour vos Sims et leurs animaux .', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/22png.png', 'Chiens et Chats', 'EXTENSION'),
(19, '2018-11-16', 'Ayez de grandes ambitions et devenez une célébrité avec Les Sims 4 Heure de gloire. Développez votre notoriété en vous lançant dans une carrière dans le cinéma, devenez un acteur ou une actrice en vue et guidez vos Sims sur le chemin semé d\'embûches vers la célébrité. Du studio aux fêtes de stars, à vous de choisir comment vos Sims vont acquérir leur renommée mondiale ! Personnalisez et montrez fièrement votre look de célébrité, et décorez la maison luxueuse de vos Sims sur les collines avec des accessoires extravagants comme des toilettes en or massif. Préparez-vous à briller sous les projecteurs et à profiter au maximum de votre vie de célébrité.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/27png.png', 'Heure de gloire', 'EXTENSION'),
(20, '2019-06-21', 'Explorez un monde agréable rempli de soleil, de plages et de divertissement sans fin dans lequel vos Sims créeront leur propre paradis avec Les Sims 4 Îles paradisiaques. Qu\'ils participent aux efforts de préservation ou qu\'ils préfèrent vivre sans eau courante ni électricité, vos Sims pourront se jeter à l\'eau et profiter de tout ce que cette culture unique a à leur offrir. Participez à des événements traditionnels, portez des vêtements locaux ou sirotez du kava. Tout cela fait partie de la vie dans les îles de Sulani.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/29png.png', 'Îles paradisiaques', 'EXTENSION'),
(21, '2019-11-15', 'Explorez toutes les expériences qu\'offre l\'université. Prenez des cours qui permettront à vos Sims de réussir une carrière dans l\'ingénierie, l\'enseignement ou le droit. Découvrez la robotique et le ping-pong, ou faites des farces amusantes aux étudiants de l\'établissement rival. Étudiez beaucoup, faites la grasse matinée et rencontrez la mascotte de l\'université ; veillez juste à toujours avoir de bonnes notes !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/32png.png', 'À la fac', 'EXTENSION'),
(22, '2020-11-13', 'Accédez à des sports d\'hiver palpitants, des sources chaudes naturelles et des maisons japonaises dans le pack d\'extension Les Sims 4 Escapade enneigée. Découvrez des aventures inédites : défiez vos Sims de grimper jusqu\'au sommet et de nouer des liens avec d\'autres Sims dans le monde de Mont Komorebi. De la luge et du snowboard à la fondue japonaise autour de la table kotatsu, il y a de quoi satisfaire tous les styles de vie.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/37png.png', 'Escapade enneigée', 'EXTENSION'),
(23, '2021-07-22', 'Profitez du charme pittoresque du pack d\'extension Les Sims 4 Vie à la campagne avec des amis animaux, des repas à base d\'ingrédients du jardin et une communauté soudée. Chez vous, cuisinez en famille en utilisant les ingrédients les plus frais. Explorez la forêt pour lier des amitiés avec des créatures des bois ou chercher de la nourriture, ou allez en ville pour rencontrer les locaux. Que les Sims fassent un câlin à une vache, deviennent amis (ou ennemis) avec leurs volailles, ou cultivent les plus gros légumes de la région, la campagne regorge de nouvelles expériences et de moyens d\'entrer en contact avec le monde qui les entoure.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/44png.png', 'Vie à la campagne', 'EXTENSION'),
(24, '2022-07-28', 'Rejoignez le rang des bons ou des mauvais élèves, participez à un club, lancez une tendance et profitez pleinement de la vie d\'ado avec le pack d\'extension Les Sims 4 Années lycée. Vivez des expériences emblématiques de l\'adolescence comme aller au bal de promo, faire des farces, explorer son identité et les tendances, et lier des amitiés et des rivalités lors d\'événements extrascolaires. Il y a beaucoup de choses à faire avant la remise des diplômes : les Sims adolescents peuvent aller en cours, interagir avec les professeurs et même gagner de l\'argent en tant qu\'influenceurs de style ou streameurs.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/56png.png', 'Années lycée', 'EXTENSION'),
(26, '2023-07-20', 'Travaillez beaucoup et amusez-vous davantage avec des amis animaux sur votre propre lopin de terre dans le pack d\'extension Les Sims 4 Vie au ranch. Élevez et dressez de majestueux chevaux qui sont des membres personnalisables de votre famille, et nouez des liens spéciaux avec eux. Vous pouvez également vous occuper de mini-moutons et de mini-chèvres, ou gagner votre vie en vendant du nectar fait maison. Façonnez votre vie unique au ranch.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-168816414768.png', 'Vie au ranch', 'EXTENSION'),
(27, '2023-12-05', 'Réunissez (littéralement) les voisins et testez les terrains multifamiliaux en tant que locataire ou propriétaire dans le pack d\'extension Les Sims 4 À louer. Votre Sim peut désormais posséder et gérer plusieurs terrains de type Locations résidentielles ou emménager dans un logement pour être plus proche que jamais de ses voisins (idéal pour fouiner !). Des buffets entre voisins aux expulsions, il y a beaucoup de choses à faire dans un nouveau monde animé.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1698978961ep15.png', 'À louer', 'EXTENSION'),
(28, '2024-07-25', 'Explorez l’amour en rencontrant des Sims qui vous plaisent et organisez des rencards enthousiasmants dans le pack d\'extension Les Sims 4 Amour fou. Créez le profil de votre Sim sur l\'application de rencontres Le Coin de Cupidon, et commencez à rencontrer vos matchs ! De nouvelles interactions intimes vous attendent, comme se faire un câlin dans un lit ou se rejoindre pour une danse de séduction. Votre dynamique sera torride ou tendue en fonction de ce que votre Sim trouve attirant. Faites particulièrement attention aux préférences en amour et aux tue-l\'amour !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1719067782image2024-06-22164935065.png', 'Amour fou', 'EXTENSION'),
(29, '2024-10-31', 'Découvrez le secret de la vie et de la mort pour enrichir l\'expérience de vos Sims de leur vivant et dans l\'au-delà avec le pack d\'extension Les Sims 4 À la vie, à la mort. Réalisez vos rêves de votre vivant en cochant tous les éléments de votre liste de souhaits, ou continuez vos projets inachevés en tant que fantôme avec des affaires à régler. Il y a un nouveau monde effrayant à hanter, une carrière qui vous rapprochera de la Faucheuse, des testaments à rédiger, des cryptes à explorer et des compétences fantomatiques à maîtriser. Il n\'y a pas de véritables fins - seulement des transitions - lorsque vous explorez la vie, l\'au-delà et même la réincarnation.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1730250755ep17.png', 'À la vie, à la mort', 'EXTENSION'),
(30, '2025-03-06', 'Développez de nouvelles compétences et vivez une vie pleine de satisfaction dans le pack d’extension Les Sims 4 Business et loisirs. Installez-vous à Nordhaven, un monde d’opportunités où vous pourrez réaliser vos rêves au sein d’une communauté passionnée. Créez des œuvres artistiques corporelles avec la nouvelle compétence Tatouage tout en gagnant des simflouz. Fabriquez des objets fonctionnels avec la nouvelle compétence Poterie et faites-vous payer pour des leçons à mesure que vous progressez. Les Sims astucieux peuvent transformer leurs rêves les plus fous en entreprises rentables, alors utilisez votre imagination pour créer quelque chose de spécial. Gérez votre entreprise depuis chez vous ou achetez un terrain pour petite entreprise, engagez des employés, décidez comment facturer et déterminez les règles.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1739205759image2025-02-10174202530.png', 'Business et loisirs', 'EXTENSION'),
(31, '2025-07-10', 'Vivez en profitant de la magie de la nature dans le pack d\'extension Les Sims 4 Nature enchantée. Adoptez un mode de vie rempli de liberté qui vous permet de fouiller le sol et de dormir à la belle étoile, ou de rapporter les cadeaux de la nature à l\'intérieur avec des pots de plante polyvalents. Un monde charmant vous attend, dans lequel vous pouvez fabriquer des élixirs, guérir des maladies, rencontrer Mère Nature en personne et même devenir une fée !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-175139907997.png', 'Nature enchantée', 'EXTENSION'),
(32, '2025-10-02', 'Évadez-vous du quotidien grâce à des activités et des escapades hors du commun dans le pack d\'extension Les Sims 4 À l\'aventure. Encouragez le goût du jeu et faîtes-en le moteur d\'une vie d\'audace et d\'aventure. Les enfants s\'en donneront à cœur joie dans les camps de vacances conçus par vos soins et pourront même se faire des Amimaginaires !', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1758227057ep20.png', 'À l\'aventure', 'EXTENSION'),
(33, '2015-01-13', 'Aventurez-vous dans les bois pour découvrir de nouvelles surprises, dont des herbes extraordinaires et dangereuses, de nouvelles espèces de poissons, des insectes effrayants et... des ours ? Détendez-vous près du feu de camp avant de tenter de trouver l\'ermite qui vivrait au plus profond de la forêt.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/02png.png', 'Destination Nature', 'JEU'),
(34, '2015-07-14', 'Offrez à vos Sims une journée de détente avec Les Sims 4 Détente au Spa. Allez au tout nouveau spa Équilibre Parfait pour profiter d\'un massage revitalisant et développer la compétence inédite Bien-être grâce à la pratique du yoga. Après un bain de boue relaxant, entrez dans le sauna pour oublier vos tracas du quotidien. Vous obtiendrez également une grande variété de nouveaux objets et décorations qui vous permettront d\'amener tellement de sérénité chez vos Sims qu\'ils ne pourront que trouver la paix intérieure !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/06png.png', 'Détente au spa', 'JEU'),
(36, '2017-01-24', 'Transformez vos Sims en puissants vampires et vivez pour l\'éternité dans une nouvelle destination étrange avec Les Sims 4 Vampires. Créez des vampires variés à l\'aide d\'outils inédits et débloquez des pouvoirs uniques donnant à vos Sims des capacités surnaturelles. Évadez-vous à Forgotten Hollow, construisez un repaire et côtoyez d\'autres immortels.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/17png.png', 'Vampires', 'JEU'),
(37, '2018-02-27', 'Explorez un paysage sauvage unique comprenant un temple, des obstacles dans la jungle, des reliques maudites et des trésors. Plongez dans la culture et les coutumes de Selvadorada, de la dégustation de délicieux plats locaux à l\'apprentissage de nouveaux pas de danse.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/24png.png', 'Dans la jungle', 'JEU'),
(38, '2019-02-26', 'Commencez votre enquête et percez le mystère d\'une ville dans le désert qui cache un sombre et profond secret dans Les Sims 4 StrangerVille. Dans cette ville sinistre, les Sims ont un comportement bizarre pour des raisons inconnues. Y a-t-il une conspiration ? Cette force étrange va-t-elle s\'emparer de votre Sim ? Découvrez l\'histoire du laboratoire secret où les Sims rencontreront des plantes étranges et interagiront avec des appareils singuliers. Parviendrez-vous à résoudre le mystère ?', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/28png.png', 'StrangerVille', 'JEU'),
(51, '2017-03-29', 'Construisez un bowling et emmenez vos Sims s’amuser toute une soirée sur les pistes avec Les Sims 4 Kit d\'Objets Soirée Bowling. Affrontez vos amis et améliorez vos compétences en bowling pour débloquer des lancers élaborés. Personnalisez votre espace avec des décorations sur le thème du bowling et donnez à vos Sims un nouveau look qui leur donnera l’assurance nécessaire pour ne pas perdre la boule.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/18png.png', 'Soirée Bowling', 'OBJETS'),
(57, '2021-01-26', 'Allumez les bougies et préparez les rituels pour apaiser vos nouveaux colocataires effrayants dans le kit d\'objets Les Sims 4 Paranormal !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/38png.png', 'Paranormal', 'OBJETS'),
(59, '2024-02-29', 'Fabriquez des bijoux éblouissants et donnez une étincelle de pouvoir à vos créations avec le kit d’objets Les Sims 4 Créations en cristal. Développez une nouvelle compétence qui permettra à votre Sim d\'obtenir des matériaux et de personnaliser des pièces à porter, offrir ou vendre. Ces pierres précieuses n\'ont pas qu\'une apparence rayonnante ; une fois chargées avec la lumière de la lune, elles peuvent influencer l\'humeur, les relations, les carrières et la vie de vos Sims.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-170925046975.png', 'Créations en cristal', 'OBJETS'),
(117, '2026-02-12', 'Conspirez pour mieux régner. Bâtissez une dynastie puissante, intégrez la noblesse et évitez les scandales dans le pack d\'extension Les Sims 4 Héritage et royauté. Vivez des moments historiques en participant à des duels à l\'épée ou en embrassant des grenouilles, tandis que vous gravissez les rangs de la noblesse. Que vous soyez noble ou non, vous pourrez fonder une dynastie. Profitez des avantages de votre prestige tout en maintenant l\'unité, ou au contraire, laissez-vous séduire par les conflits et les scandales. Prenez le pouvoir, mais attention, vous pourriez le perdre et votre grâce avec. Prenez garde aux scandales, comme les romances interdites ou les enfants secrets ! Bâtissez votre héritage, tracez votre chemin royal et visez la gloire.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1770149365royalty.png', 'Héritage et royauté', 'EXTENSION'),
(118, '2021-03-02', 'Habillez vos Sims avec des tenues de sport rétro avec Les Sims 4 Look rétro ! Retrouvez des couleurs nostalgiques, des motifs audacieux et des silhouettes tendance avec des objets de Créer un Sim totalement inédits.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/39png.png', 'Look rétro', 'MINIKIT'),
(119, '2023-03-16', 'Renforcez les liens familiaux, faites-vous des amis ou des ennemis et découvrez la véritable identité de vos Sims avec le pack d’extension Les Sims 4 Grandir ensemble. Les façons dont vos Sims nouent des liens avec ceux qui les entourent, des membres de leur famille aux nouvelles rencontres, évoluent. Des événements planifiés comme des soirées pyjamas et des étapes inattendues comme une crise de la quarantaine façonnent vos Sims et leurs relations.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/63png.png', 'Grandir ensemble', 'EXTENSION'),
(120, '2016-06-07', 'Ouvrez un restaurant et emmenez vos Sims manger à l\'extérieur avec Les Sims 4 Au Restaurant. Créez et gérez une grande variété de restaurants, engagez du personnel et élaborez le menu idéal pour faire des bénéfices et développer votre établissement. Mangez à l\'extérieur avec vos Sims pour découvrir de nouveaux plats expérimentaux et passer de bons moments entre amis et en famille.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/12png.png', 'Au Restaurant', 'JEU'),
(121, '2019-09-10', 'Explorez un monde surnaturel et maîtrisez l\'art de la magie dans Les Sims 4 Monde magique. À première vue, cette petite ville à la campagne ressemble aux autres quartiers, mais une fois le portail secret débloqué, la vraie magie commence. Des potions, des baguettes magiques et même un monde flottant vont charmer votre Sim, mais attention aux sorts qui tournent mal ! Apprenez l\'art de la magie, invoquez un familier pour vous protéger et plongez dans ce monde enchanteur.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/31png.png', 'Monde magique', 'JEU'),
(122, '2020-09-08', 'Créez l\'histoire Star Wars unique de votre Sim en explorant le monde éloigné de Batuu, de Galaxy\'s Edge de Disneyland et Disney World, dans le pack de jeu Les Sims 4 Star Wars: Voyage sur Batuu.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/36png.png', 'Star Wars: Voyage sur Batuu', 'JEU'),
(123, '2021-06-01', 'Transformez le rêve de votre client en réalité avec le pack de jeu Les Sims 4 Décoration d\'intérieur. Chaque maison a un potentiel inexploité, et il n\'y a que vous qui puissiez la faire passer d\'ennuyeuse à fabuleuse ! Si vous voulez développer votre réputation professionnelle, découvrez ce que chaque Sim aime et n\'aime pas avant de commencer à décorer, puis créez la rénovation parfaite pour chaque client. Une fois que votre magie a opéré, préparez-vous à voir le visage stupéfait de votre client lors de la grande révélation !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/43png.png', 'Décoration d\'intérieur', 'JEU'),
(124, '2022-02-23', 'Marchez jusqu\'à l\'autel dans le pack de jeu Les Sims 4 Mariage. Rendez spécial le parcours de votre Sim jusqu\'au grand jour, puis organisez la cérémonie parfaite. De la demande en mariage à la réception, personnalisez chaque aspect pour célébrer l\'histoire d\'amour de chaque Sim d\'une manière véritablement unique. Dans le monde de Tartosa, (presque) tout peut être romantique.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/51png.png', 'Mariage', 'JEU'),
(125, '2015-05-19', 'Vos Sims optent pour la sophistication avec Les Sims 4 Soirées de Luxe ! Organisez une fête luxueuse avec une grande variété de décorations extravagantes. Améliorez les garde-robes de vos Sims avec des robes éblouissantes et des tenues habillées vraiment élégantes. Enfin, créez le centre de table idéal pour vos événements avec la nouvelle table de banquet, et servez de délicieux plats à vos Sims !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/04png.png', 'Soirées de Luxe', 'OBJETS'),
(126, '2015-06-01', 'Attirez vos Sims à l\'extérieur avec des bains à remous et de nouveaux meubles, décorations, coiffures, etc., dans le kit d\'objets Les Sims 4 Ambiance Patio. Allumez le barbecue et enfilez une tenue plus décontractée pour vous détendre de manière stylée. Servez de délicieux rafraichissements avec le nouveau bar de patio et détendez-vous grâce aux bulles apaisantes du bain à remous et son eau chaude d\'une température idéale.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/05png.png', 'Ambiance Patio', 'OBJETS'),
(127, '2015-08-11', 'Transformez les cuisines de vos Sims et donnez-leur un style moderne avec des appareils élégants en acier inoxydable et des meubles inédits parfaits pour les gourmets. Découvrez les nouvelles saveurs étonnantes que vos Sims peuvent créer avec la nouvelle sorbetière ! De plus, vos Sims seront à croquer grâce à des tenues et coiffures inédites.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/07png.png', 'En Cuisine', 'OBJETS'),
(128, '2015-09-29', 'Transformez la maison de votre Sim avec des décorations drôles et macabres. Faites votre choix parmi une grande variété de déguisements et maquillages inédits pour créer un nouveau look amusant pour vos Sims. Découvrez un moyen inédit de fabriquer des objets avec la nouvelle station de sculpture de citrouilles et aidez vos Sims à organiser une fête effrayante à laquelle tout le monde mourra d\'envie de venir.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/08png.png', 'Accessoires Effrayants', 'OBJETS'),
(129, '2016-01-12', 'Pourquoi sortir quand vous pouvez rester chez vous dans une ambiance détendue et regarder des films ? Invitez vos amis, passez du temps ensemble, et regardez des films avec Les Sims 4 Comme au cinéma. Faites du popcorn et passez un film à vos Sims sur le tout nouvel écran de projection. Optez pour de nouveaux vêtements et de nouvelles coiffures.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/10png.png', 'Comme au cinéma', 'OBJETS'),
(130, '2016-02-09', 'Créez un jardin luxuriant pour vos Sims et préparez-vous à leur faire vivre des moments romantiques avec Les Sims 4 Jardin Romantique. Mettez vos Sims dans l’ambiance idéale avec des tenues florales romantiques et partagez un moment de jeu dans la magnifique fontaine. Allez ensuite au puits à souhaits, jetez une pièce et découvrez si les désirs les plus profonds de votre Sim se réalisent.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/11png.png', 'Jardin Romantique', 'OBJETS'),
(131, '2016-06-28', 'Stimulez l’imagination des Sims avec de nouveaux objets pour personnaliser les chambres d’enfants dans Les Sims 4 Chambre d\'enfants. Collectionnez et échangez des cartes de monstres puis donnez-leur vie avec la station de bataille électronique. Faites un spectacle de marionnettes pour raconter des histoires et divertir la famille et les amis. Mettez en valeur vos enfants Sims avec de nouveaux vêtements et coiffures qui expriment vraiment leur style individuel.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/13png.png', 'Chambre d\'enfants', 'OBJETS'),
(132, '2016-07-19', 'Offrez à vos Sims un jardin dont ils peuvent vraiment profiter avec Les Sims 4 En plein air ! Ajoutez d\'amusantes glissades d\'eau et de nouveaux objets colorés. Enfilez une tenue un peu plus confortable et n\'oubliez pas de toujours garder un verre de limonade à portée de main.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/14png.png', 'En plein air', 'OBJETS'),
(133, '2016-12-06', 'Il est temps pour vos Sims de vivre dans le luxe avec Les Sims 4 Accessoires Vintage. Habillez les Sims avec des tenues et accessoires vintage, puis maquillez-les à l’aide de la coiffeuse. Décorez la maison de votre Sim avec des meubles sophistiqués et engagez même un majordome pour satisfaire le moindre de ses besoins.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/16png.png', 'Accessoires Vintage', 'OBJETS'),
(134, '2017-06-20', 'Améliorez la forme de votre Sim et adoptez un mode de vie actif avec Les Sims 4 Fitness. Défiez vos Sims de grimper sur le mur d\'escalade roulant, un moyen amusant de brûler des calories et d\'améliorer sa silhouette. Faites votre choix parmi une collection de vêtements de sport branchés, et décorez la maison de votre Sim avec des objets et décorations s\'inspirant de la nature.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/20png.png', 'Fitness', 'OBJETS'),
(135, '2017-08-24', 'Offrez à vos bambins de nouveaux moyens d\'exprimer leur personnalité, de se défouler et de se faire des amis avec Les Sims 4 Bambins. Habillez vos petits Sims avec une grande variété de tenues adorables et de coiffures mignonnes. Utilisez des décorations colorées pour créer un espace de jeu extérieur où les bambins pourront profiter du toboggan, ramper dans des tunnels et s\'amuser dans la piscine à balles avec leurs amis.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/21png.png', 'Bambins', 'OBJETS'),
(136, '2018-01-16', 'Offrez à vos Sims des vêtements parfaitement propres tout en adoptant un mode de vie rustique avec Les Sims 4 Jour de lessive. Vos Sims peuvent désormais rassembler leur linge sale, le laver et le faire sécher pour donner une apparence impeccable à leurs tenues. Menez une vie rustique avec des décorations inédites et de nouveaux vêtements sur le thème de la campagne.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/23png.png', 'Jour de lessive', 'OBJETS'),
(137, '2018-03-13', 'Apprenez à vos Sims à s\'occuper d\'animaux de compagnie plus petits, décorez une maison avec des meubles inspirés des animaux et habillez vos animaux avec vos tenues de Sim préférées !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/25png.png', 'Premier animal de compagnie', 'OBJETS'),
(138, '2019-08-13', 'Moschino et son directeur créatif Jeremy Scott célèbrent le lancement de la nouvelle Collection capsule avec des vêtements inspirés des Sims et de leur propre prêt-à-porter dont des styles des anciennes collections.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/30png.png', 'Moschino', 'OBJETS'),
(139, '2020-01-21', 'Ayez de grandes idées pour un petit espace. Obtenez le kit d\'objets Les Sims 4 Mini-maisons pour créer la toute petite maison confortable dont rêvent vos Sims avec un type de terrain résidentiel inédit idéal pour des mini-maisons et des meubles stylés et compacts. Privilégiez le confort avec des objets de CUS parfaits pour le mode de vie douillet de vos Sims, comme des pyjamas confortables et des pulls ultra-larges en cachemire.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/33png.png', 'Mini-maisons', 'OBJETS'),
(140, '2023-09-28', 'Développez vos compétences culinaires avec de nouveaux petits appareils et transformez la cuisine en simflouz avec le kit d’objets Les Sims 4 Passion cuisine ! Concevez une cuisine efficace avec tous les outils dont vous avez besoin pour devenir un cordon-bleu magistral. Vos Sims adopteront un look approprié avec des tabliers stylés et d\'autres accessoires de cuisine, et les chefs amateurs pourront même transformer la cuisine en carrière à temps partiel lucrative avec leurs propres stands de nourriture.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1694536687sp19.png', 'Passion cuisine', 'OBJETS'),
(141, '2021-03-02', 'Transformez la cuisine de votre Sim en la partie la plus charmante de sa maison avec Les Sims 4 Cuisine rustique ! Des réfrigérateurs vintage aux cocottes, ces objets de Construction/Achat créent une vision délicieusement tendance d\'un style intemporel.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/40png.png', 'Cuisine rustique', 'MINIKIT'),
(142, '2021-03-02', 'Sortez l\'aspirateur et faites du rangement dans Les Sims 4 Nettoyage de printemps ! La poussière s\'accumule et fait apparaître des Peluches amicales et d\'ignobles Monstres de crasse dans les maisons de vos Sims.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/41png.png', 'Nettoyage de printemps', 'MINIKIT'),
(143, '2021-05-18', 'Transformez le centre de la maison de votre Sim en somptueux espace coloré s\'inspirant des riads du Maroc avec le kit Les Sims 4 Riad de rêve. Détendez-vous près de la fontaine, admirez les carrelages décoratifs et réunissez votre famille dans une harmonie totale.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/42png.png', 'Riad de rêve', 'MINIKIT'),
(144, '2021-08-26', 'Découvrez un style architectural réhabilité avec Les Sims 4 Loft industriel, inspiré des entrepôts reconvertis de Brooklyn à New York. De grandes fenêtres, des équipements apparents et des objets originaux mettent en valeur la beauté des matériaux bruts et des détails inachevés.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/45png.png', 'Loft industriel', 'MINIKIT'),
(145, '2021-10-05', 'Améliorez la garde-robe de votre Sim avec le kit Les Sims 4 Incheon Style, inspiré des tenues emblématiques vues à l\'aéroport de Séoul. Les styles coréens traditionnels sont modernisés pour devenir des looks épurés et minimalistes dans des coloris doux.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/47png.png', 'Incheon Style', 'MINIKIT'),
(146, '2021-10-05', 'Enrichissez votre style avec la collection du kit Les Sims 4 Rue de la mode, inspirée des tenues qui font les tendances de Bombay. Des couleurs riches, des silhouettes emblématiques et des motifs très contrastés donnent de l\'énergie et du dynamisme à chaque vêtement. Montrez fièrement votre individualité en portant des pièces originales tendance avec des détails traditionnels pour obtenir un style totalement inédit.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/46png.png', 'Rue de la mode', 'MINIKIT'),
(147, '2021-11-09', 'Faites de votre intérieur un jardin luxuriant grâce à une végétation qui revitalisera vos espaces, avec le kit Les Sims 4 Intérieurs fleuris. Parez la maison de votre Sim de plantes radieuses et paisibles. Des plantes suspendues aux vases décoratifs, une sérénité parfaite vous attend.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/48png.png', 'Intérieurs fleuris', 'MINIKIT'),
(148, '2021-12-02', 'Révolutionnez les classiques avec le kit Les Sims 4 Nouveaux styles masculins incluant une collection accessible et qui interpelle conçue par Stefan Cooke. Des formes réimaginées redéfinissent des looks traditionnellement masculins, tandis que des textiles et des motifs subliment chaque pièce pour un style d\'aujourd\'hui.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/49png.png', 'Nouveaux styles masculins', 'MINIKIT'),
(149, '2022-02-03', 'Apportez de l’énergie avec le kit Les Sims 4 Tenues de carnaval, conçu en partenariat avec Pabllo Vittar pour célébrer l\'effervescence du carnaval du Brésil. Incarnez l\'assurance et la créativité de la plus grande fête du monde grâce aux vêtements et aux accessoires d\'une collection unique.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/50png.png', 'Tenues de carnaval', 'MINIKIT'),
(150, '2022-03-21', 'Transformez instantanément un salon basique en pièce inspirante avec les objets expressifs et éclectiques du kit Les Sims 4 Déco Maximaliste. Cette collection se base sur des décorations colorées et audacieuses pour vous permettre d\'explorer facilement les principes du style maximaliste avec toutes sortes d\'objets.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/52png.png', 'Déco Maximaliste', 'MINIKIT'),
(151, '2022-05-26', 'Habillez-vous pour une soirée inoubliable avec le kit Les Sims 4 Tenues de soirée, inspiré par la créatrice parisienne Paola Locatelli. Admirez la couleur, la fluidité et le style moderne d’une collection qui embellira l\'apparence de votre Sim pour ses rencards et l\'aidera peut-être même à briser quelques cœurs.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/53png.png', 'Tenues de soirée', 'MINIKIT'),
(152, '2022-05-26', 'N\'allez pas dormir tout de suite, et campez dans le jardin avec les objets confortables et faits main du kit Les Sims 4 Petits campeurs ! Jouez dehors dans votre propre cabane de couvertures : cette collection a tout ce qu\'il faut pour passer une soirée en famille créative et amusante.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/54png.png', 'Petits campeurs', 'MINIKIT'),
(153, '2022-09-01', 'Un style frais pour enfants branchés. Habillez la prochaine génération de créateurs de tendances avec des tenues idéales pour jouer, avec le kit Les Sims 4 Premiers looks. Que les enfants Sims aient envie de faire forte impression dès le jour de la rentrée ou simplement de s’amuser avec leurs amis, ces styles polyvalents leur permettront d\'avoir un look à la mode (et vraiment mignon).', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/57png.png', 'Premiers looks', 'MINIKIT'),
(154, '2022-09-14', 'Profitez du soleil avec les luxueux objets d’intérieur et d’extérieur du kit Les Sims 4 Luxe dans le désert. Placez des meubles aux tons neutres assortis, des rideaux et bien plus encore pour créer un espace lumineux et sophistiqué où vos Sims pourront se détendre et recevoir des invités. Cette collection comprend des couleurs neutres inspirées du désert du sud-ouest des États-Unis et des matériaux comme la pierre et le bois. L\'esthétique générale est luxueuse et discrète : idéale pour créer une oasis relaxante dans la maison de vos Sims ou sur leur patio. Placez un bar, une causeuse, une cheminée et bien plus encore de manière à ce qu\'ils deviennent des éléments architecturaux fonctionnels intégrés à votre espace, et créez l\'endroit parfait pour la prochaine grosse fête ou le prochain dîner romantique de votre Sim.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/58png.png', 'Luxe dans le désert', 'MINIKIT'),
(155, '2022-11-10', 'Créez une chambre douce et joyeuse propice à la rêverie avec Les Sims 4 Chambre pastel ! Associez du simple au psychédélique avec des imprimés pastel excentriques, des formes irrégulières et des styles vintage. Cette collection est idéale pour le dortoir, la chambre ou le studio de votre Sim.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/59png.png', 'Chambre pastel', 'MINIKIT'),
(156, '2022-11-10', 'Créez des espaces qui ont l\'air aimés et habités avec Les Sims 4 Objets du quotidien ! Racontez les histoires des personnalités de vos Sims à travers des objets en vrac liés à leurs loisirs et à leur vie quotidienne comme des tasses à café usagées, des piles de magazines ou des produits de beauté.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/60png.png', 'Objets du quotidien', 'MINIKIT'),
(157, '2023-01-19', 'Créez une ambiance intimiste avec les tenues d\'intérieur amusantes et affriolantes du kit Les Sims 4 Collection Simtimité. Sortez le grand jeu lors des séances de crac-crac avec des tenues séduisantes incluant de la dentelle, des bretelles et des silhouettes flatteuses pour tous les corps. Mettez à jour la garde-robe intime de vos Sims avec des vêtements basés sur les matières, couleurs et motifs à la mode. Des bodys en dentelle, une grande variété de styles de sous-vêtements et des boxers aux motifs amusants donneront l\'impression à vos Sims que leur chambre est un podium de défilé. Pour donner de la confiance en soi à chaque Sim, nous avons collaboré avec MeUndies pour créer des styles qui sont flatteurs pour une grande variété de morphologies afin d\'aider chaque Sim à avoir de l\'audace et à séduire.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/61png.png', 'Collection Simtimité', 'MINIKIT'),
(158, '2023-01-19', 'Recréez le désordre de la vie quotidienne ou élaborez une oasis bien organisée avec le kit Les Sims 4 Objets de salle de bain. Ce kit inclut des décorations pour tous les âges, des adorables stickers muraux pour enfants aux dentiers de mamie. Créez une image réaliste d\'une famille en ajoutant de petites touches pour chaque âge. Transformez la salle de bain de votre Sim en refuge élégant pour s\'évader du chaos de la vie, ou laissez ce chaos envahir aussi cet espace. Avec ce kit, vous pouvez créer des espaces reflétant la personnalité d\'une grande diversité de Sims.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/62png.png', 'Objets de salle de bain', 'MINIKIT'),
(159, '2023-04-20', 'Créez un endroit où vos Sims passeront de bons moments avec leurs plantes avec le kit Les Sims 4 Havre végétal. Qu\'ils préfèrent profiter de la verdure apaisante ou organiser l\'espace de jardinage parfait, utilisez des fenêtres et portes vitrées pour construire un refuge lumineux et paisible que vos Sims vont adorer.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1682105208kit20.png', 'Havre végétal', 'MINIKIT'),
(160, '2023-04-20', 'Des meubles récupérés et des objets oubliés vous attendent dans le kit Les Sims 4 Trésors du grenier. Parfois, le fauteuil préféré de la maison est celui qui est un peu abîmé. C\'est pour cela que cette collection est remplie d\'objets usés par de nombreuses années d\'utilisation et d\'amour.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1682105208kit21.png', 'Trésors du grenier', 'MINIKIT'),
(161, '2023-06-01', 'Explorez des styles rebelles et personnalisez-les avec Les Sims 4 Retour du grunge. Qu’il s’agisse d\'enfiler un vieux t-shirt de groupe ou un sweat large à capuche venant de friperie, ce kit est là pour apporter une énergie nouvelle et de l\'audace aux looks du quotidien.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1685656860kit22.png', 'Retour du grunge', 'MINIKIT'),
(162, '2023-06-01', 'Détendez-vous dans un espace confortable et évadez-vous grâce à un bon livre avec Les Sims 4 Coin lecture. Créez l\'endroit idéal pour vous pelotonner après une longue journée ou pour profiter d\'une après-midi ensoleillée. Concevez le coin lecture de votre Sim de façon à ce qu\'il devienne son endroit préféré de la maison.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1685656870kit23.png', 'Coin lecture', 'MINIKIT'),
(163, '2023-09-07', 'Faites tourner des têtes à la piscine avec les maillots de bain joyeux et colorés du kit Les Sims 4 À la piscine. Les motifs colorés et les coupes tendance de cette collection vont à une grande variété de couleurs de peau et de morphologies. Que votre Sim cherche à draguer dans le bain à remous ou à faire la fête au bord de la piscine, ces looks joyeux l’aideront à se démarquer. Assortissez les différents éléments pour obtenir des résultats uniques et éblouissants. Complétez votre tenue de piscine avec des lunettes de soleil stylées, des ongles arc-en-ciel, des sandales, de fabuleuses bouées gonflables et bien plus encore. Amusez-vous !', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1694210911sp44.png', 'À la piscine', 'MINIKIT');
INSERT INTO `dlc` (`id`, `date_sortie`, `description`, `img`, `nom`, `type`) VALUES
(164, '2023-09-07', 'Offrez-vous de luxueux meubles modernes qui montrent que vous avez réussi dans la vie avec le kit Les Sims 4 Luxe moderne. Votre Sim a travaillé dur ; il est temps de célébrer sa réussite. Avec ce kit, nous laissons la sobriété dans le passé et choisissons des œuvres d’art élégantes, des décorations sophistiquées et un confort incroyable. Créez un espace stylé et accueillant avec des objets haut de gamme. Améliorez votre mode de vie avec un peu d’extravagance. Affirmez votre style avec des objets de luxe comme une télévision cachée derrière une œuvre murale, des sacs à main de créateur, des sculptures et une platine qui fonctionne.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1694210911sp45.png', 'Luxe moderne', 'MINIKIT'),
(165, '2024-01-18', 'Recréez la splendeur classique d\'un château avec le kit Les Sims 4 Châteaux de caractère. Cette collection choisie par la communauté inclut des murs de pierre, du verre au plomb et tout ce qu\'il vous faut pour créer le décor spectaculaire idéal pour votre prochaine histoire. Construisez quelque chose de grandiose — Inspirez-vous de la majesté des châteaux et construisez le vôtre en utilisant des arches gothiques, des fenêtres décorées empilables, des escaliers grandioses, une magnifique maçonnerie et un grand portail avec une herse. La gravité est essentielle. Rien ne vaut les classiques — Les parapets, les vitraux, les meurtrières et même une gargouille font partie des détails classiques qui rendront votre manoir magnifique.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-170562336073.png', 'Châteaux de caractère', 'MINIKIT'),
(166, '2024-01-18', 'Montrez votre côté obscur avec les nouveaux styles gothiques du kit Les Sims 4 Style gothique. Vous avez voté pour ce kit ; préparez-vous désormais à habiller vos Sims avec des tenues inspirées de la scène gothique contemporaine avec des vêtements ajourés, du cuir et ce fameux maquillage morose. La variété n’est pas toujours une question de couleur, cela peut aussi être une question de textures et de fioritures. Ajoutez des détails intéressants avec des vêtements ajourés, des ceintures, des boucles, des lanières et des harnais. Vos Sims exprimeront leur côté obscur avec des chaussures à semelles compensées et des silhouettes élégantes idéales pour le quotidien, les fêtes ou toute autre occasion où vos Sims ont envie de se démarquer.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-170562336074.png', 'Style gothique', 'MINIKIT'),
(167, '2024-04-18', 'Pavanez-vous dans des vêtements rétro emblématiques tout en étant totalement de votre époque avec Les Sims 4 Mode urbaine. La joueuse Ebonix a participé à chaque détail de cette collection qui comprend des couleurs expressives, des motifs frappants et des accessoires qui inspirent la confiance en soi.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1713337886kit28.png', 'Mode urbaine', 'MINIKIT'),
(168, '2024-04-18', 'Coordonnez votre décoration pour créer l\'ambiance festive idéale avec Les Sims 4 Fête parfaite. Donnez le ton avec des décorations assorties disponibles dans des couleurs parfaites pour n\'importe quel type de fête, ainsi qu\'une boule à facettes pour apporter plus de lumière et une machine à brouillard pour ajouter plus de mystère.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1713337886kit29.png', 'Fête parfaite', 'MINIKIT'),
(169, '2024-05-30', 'Profitez du paysage rustique qui entoure votre piscine paisible et à l\'abri des regards avec le kit Les Sims 4 Riviera italienne. Il est temps de vous détendre dans un fauteuil en osier en regardant la lumière du soleil passer à travers la pergola recouverte de plantes et scintiller dans votre chute d\'eau privée. Créez le lieu secret parfait pour votre Sim pour passer des moments agréables en solo ou avec quelqu\'un de spécial. Installez vos meubles confortables recouverts de tissu au milieu de décorations rustiques et d\'éléments terreux comme des pavés en pierre. Cet espace intemporel mélange le frais et l\'épuré au naturel pour créer un endroit où les soucis disparaissent.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1716941401sp52.png', 'Riviera italienne', 'MINIKIT'),
(170, '2024-05-30', 'Passez dans votre bistrot secret préféré et profitez de l’ambiance rétro du kit Les Sims 4 Bistrot charmant. Concevez un espace où seuls le bon nectar et la très bonne compagnie comptent. Décorez-le avec tous les éléments typiques d\'un bistrot local populaire dont des murs en lambris, des détails en métal poli et des meubles vintage magnifiquement conservés. Servez le meilleur nectar le soir et le café le plus savoureux le jour. Remplissez votre bistrot de bougies et de décorations classiques afin de créer pour vos Sims l’endroit idéal où retrouver leurs potes ou leurs rencards.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1716941401sp53.png', 'Bistrot charmant', 'MINIKIT'),
(171, '2024-09-19', 'Entourez les nouveaux membres de la famille de l’élégance qu’ils méritent dans le kit Les Sims 4 Chambre d\'enfant enchantée. Cette chambre d\'enfant est un espace raffiné apportant une ambiance sophistiquée, avec des meubles décorés ainsi que des jouets fantaisistes. Conçue en collaboration avec SixamCC, cette collection est un équilibre parfait entre la joie d\'une naissance et un charme incroyable. Certains objets rendent même hommage aux coutumes et à l\'héritage des jeux Les Sims.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1726694062sp55.png', 'Chambre d\'enfant enchantée', 'MINIKIT'),
(172, '2024-09-19', 'Concevez un espace inspirant où vos Sims pourront perfectionner leurs compétences créatives avec le kit Les Sims 4 Atelier d\'artiste. Votre chevalet est entouré de vos outils indispensables : pinceaux, pots de peinture, références de natures mortes et bien plus encore, éparpillés de façon stylée, exactement comme vous l’aimez. Vous connaissez votre studio - son désordre, ses tiroirs et ses étagères, et chaque goutte de peinture éclaboussée - parce que vous y avez laissé votre empreinte, exactement comme sur vos toiles.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1726694062sp54.png', 'Atelier d’artiste', 'MINIKIT'),
(173, '2024-11-14', 'Adoptez un look mignon même lorsque votre soirée se déroule dans votre propre chambre avec Les Sims 4 Soirée pyjama. Les couleurs pastel, les tissus doux ainsi que les modèles et motifs adorables vous donneront l\'impression d\'être dans un rêve. Complétez vos tenues de nuit avec des ongles mignons, des chaussettes et chaussons douillets et des produits de soin pour la peau amusants à utiliser. Des créations de Trillyke.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1731070929kit34.png', 'Soirée pyjama', 'MINIKIT'),
(174, '2024-11-14', 'Adoptez des couleurs vives et un style moderne d\'il y a plusieurs décennies avec Les Sims 4 Salon rétro. Inspirée des années 60 et 70, cette collection d’objets de salon inclut des associations audacieuses de couleurs et de motifs, des surfaces stylées et d\'adorables objets décoratifs remplis de personnalité. Ajoutez des détails subtils à votre pièce ou affirmez votre style avec chaque objet. Des créations de myshunosun.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1731070929kit35.png', 'Salon rétro', 'MINIKIT'),
(175, '2025-01-16', 'Installez-vous confortablement devant l’ordinateur avec le kit Les Sims 4 Bureau gaming cosy. Avec cette collection, vous créerez des espaces chaleureux et accueillants avec un grand bureau, des objets amusants et bien sûr une chaise de jeu confortable. Ce kit a été créé en collaboration avec Lilsimsie pour être amusant et relaxant avec des références subtiles au jeu Les Sims.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1737059461sp58.png', 'Bureau gaming cosy', 'MINIKIT'),
(176, '2025-01-16', 'Offrez-vous des tenues emblématiques et des décorations enchanteresses avec le kit Les Sims 4 Boudoir secret. Créez un luxueux espace rempli de meubles somptueux cachés derrière un passage secret dans une bibliothèque. Une fois dans votre planque, laissez le monde disparaître en vous détendant sur votre chaise longue ou essayez des tenues inspirées de l’Italie devant votre miroir pleine longueur.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1737059461sp59.png', 'Boudoir secret', 'MINIKIT'),
(177, '2025-01-16', 'Impressionnez vos invités avec un espace de divertissement moderne et les tenues élégantes du kit Les Sims 4 Repaire de Casanova. Cette mode décontractée et masculine donnera confiance à vos Sims, et le style contemporain de la décoration de votre tanière — un bar stylé, une table basse élégante, et plus encore — garantira la bonne ambiance, que ce soit pour une soirée jeux ou un rencard.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1737059461sp60.png', 'Repaire de Casanova', 'MINIKIT'),
(178, '2025-01-30', 'Optez pour l\'élégance et le raffinement avec Les Sims 4 Salon élégant. Grâce à un mélange astucieux de meubles modernes et rétro, vous pouvez créer la base parfaite. Donnez-lui ensuite plus de caractère avec des objets chics et uniques. Et voilà, vous obtenez un salon digne d\'un magazine de décoration. Des créations de Pierisim.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1737059461sp61.png', 'Salon élégant', 'MINIKIT'),
(179, '2025-01-30', 'Offrez à vos Sims un look professionnel avec des tenues chics et stylées dans Les Sims 4 Chic professionnel. Des costumes sur mesure aux robes élégantes, vos Sims déborderont d\'assurance tout en étant tendance. Complétez chaque tenue avec des chaussures élégantes et des accessoires sophistiqués pour encore plus de classe. Avec le kit Chic professionnel, vos Sims auront toujours une tenue à la hauteur. Des créations de Madlen.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1737059461sp62.png', 'Chic professionnel', 'MINIKIT'),
(180, '2025-04-10', 'Offrez à vos Sims une salle de bain moderne et apaisante incluant un design minimaliste et des détails raffinés avec le kit Les Sims 4 Salle de bain sophistiquée. Cette collection apporte une ambiance relaxante et une esthétique stylée. Le mélange de lignes épurées et de matériaux naturels crée un équilibre harmonieux entre un côté chaleureux et un côté élégant. De douces couleurs pastel s\'associent naturellement à des détails en métal brossé, tandis que des touches de verdure apportent de la vie dans votre espace, transformant n\'importe quelle salle de bain en sanctuaire chic. Créé par Syboulette.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1740593977kit41.png', 'Salle de bain sophistiquée', 'MINIKIT'),
(181, '2025-04-10', 'Ajoutez des couleurs douces et des vêtements ornés de rubans et de nœuds à la garde-robe de vos Sims avec le kit Les Sims 4 Adorables détails. Avec des couleurs claires, des volants et des froufrous, les vêtements et accessoires de ce kit apportent des looks élégants à porter au quotidien. Dévoilez un côté plus délicat du style de vos Sims en leur offrant des tenues à la fois coquettes et décontractées. Créé par aharris00britney.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1740593977kit42.png', 'Adorables détails', 'MINIKIT'),
(182, '2025-05-01', 'Effectuez des réparations gratifiantes dans votre propre atelier polyvalent avec Les Sims 4 Atelier de bricolage. Prenez de vieux appareils cassés et donnez-leur une nouvelle vie grâce à votre compétence Bricolage. Ce kit vous permettra de vivre l\'expérience complète du bricolage avec des étagères, des établis et d\'autres détails pour créer un espace fonctionnel.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1745958455kit43.png', 'Atelier de bricolage', 'MINIKIT'),
(183, '2025-05-01', 'Habillez vos Sims âgés et âgées avec des tenues pratiques, décontractées et adaptées avec Les Sims 4 Âge d\'or. Ces Sims ont vécu de longues vies intéressantes. Ces looks confortables leur permettent de montrer leur personnalité quel que soit l\'endroit où leur histoire les amène, qu\'il s\'agisse du jardin, de la salle de sport ou du quartier pour une promenade.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1745958455kit44.png', 'Âge d\'or', 'MINIKIT'),
(184, '2025-05-01', 'La cuisine est le centre de la vie de famille ; alors donnez un style habité à la vôtre avec Les Sims 4 Accessoires de cuisine. Racontez des histoires du quotidien avec des objets courants, dont certains sont ouverts ou semblent en cours d\'utilisation comme des courses ou un étendoir. Ce kit inclut toutes les touches familières dont vous avez besoin pour créer des cuisines plus réalistes.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1745958455kit45.png', 'Accessoires de cuisine', 'MINIKIT'),
(185, '2025-08-21', 'Décorez et organisez votre entrée pour en faire le vestibule parfait, avec un assortiment d\'objets, de murs, de décorations et de sols. Que votre Sim vive dans un ranch ou dans un appartement urbain et aime s\'adonner au jardinage ou d\'autres activités, un vestibule est l\'allié parfait d\'un mode de vie actif et en plein air. Utilisez cet espace pour représenter les passions et les passe-temps de votre Sim, en y ajoutant par exemple quelques paires de bottes en caoutchouc pour aller jouer dehors dans la boue. Vous pouvez également représenter la vie quotidienne de la maison en y laissant traîner une pile de courrier. Un vestibule, c\'est la porte d\'entrée de la vie de vos Sims. Création de Peacemaker_ic.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1755629341kit47.png', 'Entrée bien rangée', 'MINIKIT'),
(186, '2025-08-21', 'Complétez la collection de maquillage de votre Sim. Passez facilement d\'un look de jour délicat avec un fard à paupières léger et un gloss neutre, à un look plus osé avec un smoky eyes et un rouge à lèvres coloré. Relookez vos Sims grâce à du maquillage, tel que du fond de teint, du contouring et de l\'highlighter. Ajoutez des détails uniques, tels que des fausses taches de rousseur ou des grains de beauté pour peaufiner votre look. Que ce soit pour des rencards nocturnes, des mariages, des remises de prix ou des remises de diplômes, ce kit permet à chaque Sim d\'afficher son propre style. Création de CRYPTICSIM.', 'https://tiermaker.com/images/template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1755629341kit46.png', 'Maquillage glamour', 'MINIKIT'),
(187, '2025-10-09', 'Respirez l\'air frais de l\'automne, regardez les feuilles rougeoyer et emmitouflez-vous dans des vêtements chauds avec Les Sims 4 Tenues d\'automne. Cette collection vous offre des tenues à composer et des accessoires. Quand il sera trop tard pour les maillots de bain et trop tôt pour les bottes de neige, ce kit sera là pour vous ! Il vous apportera des pulls bien confortables, des écharpes et des bonnets assortis et plein d\'autres tenues pour braver le froid. Ne craignez plus la fraîcheur grâce à des tissus de haute qualité et des coloris d\'automne. Pas besoin de choisir entre le confort et le style grâce à ces tenues élégantes et à composer. Les Sims pourront porter des accessoires qui respirent le charme, tels que des chapeaux à larges bords, des sacs à main et des bottes tendance.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1758227057jesieniara.png', 'Tenues d\'automne', 'MINIKIT'),
(188, '2025-11-13', 'Ajoutez une touche de modernité et de nature dans le salon de vos Sims avec Les Sims 4 Refuge moderne. Ce kit regroupe des sièges confortables, des meubles élégants et des objets fabriqués à la main avec des matériaux naturels. Il célèbre le savoir-faire qui transforme des matériaux naturels bruts en pièces modernes intemporelles, au croisement entre simplicité et sophistication. Création de TudTuds.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1762284530102.png', 'Refuge moderne', 'MINIKIT'),
(189, '2025-11-13', 'Transformez votre salle à manger extérieure en une escapade rustique où vos récoltes personnelles sont au cœur de chaque plat avec Les Sims 4 Du jardin à l\'assiette. Alliez le charme rustique à l’élégance moderne grâce à des meubles polyvalents en bois naturel et en pierres des champs empilées. Ces matériaux bruts émettent une douce chaleur naturelle, tandis que les parties en métal ou en céramique apportent une touche de modernité. Gardez une palette neutre pour une ambiance rustique, ou ajoutez des touches de couleur pour un côté moderne. Assemblez le tout et donnez vie à votre espace extérieur. Ajoutez des décorations végétales et des plantes en pot luxuriantes. Création de BrazenLotus’.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1762284530103.png', 'Du jardin à l\'assiette', 'MINIKIT'),
(190, '2025-12-04', 'Décorez une chambre avec des meubles tirés du célèbre dessin animé avec Les Sims 4 Chambre d\'enfant Bob l\'éponge. Si vous appréciez les absurdités sous-marines, remplissez la pièce de jouets et de tenues confortables qui célèbrent Bob l\'éponge et son univers.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1764703279105.png', 'Chambre d\'enfant Bob l\'éponge', 'MINIKIT'),
(191, '2025-12-04', 'Créez votre propre maison ananas avec des décorations nautiques avec Les Sims 4 Maison de Bob l\'éponge. Récupérez une collection de bibelots et de meubles tirés directement du dessin animé, comme la télévision scaphandre de Bob l\'éponge et le réveil en corne de brume. Aidez vos Sims à révéler leur côté spongieux au monde entier !', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1764703279104.png', 'Maison de Bob l\'éponge', 'MINIKIT'),
(192, '2025-12-11', 'Mélangez de charmantes tenues des plaines et des accessoires vintage dans Les Sims 4 Plaines oniriques. Du style rustique à l\'élégant, ces looks rappellent le charme de la campagne. Avec des vêtements comme la salopette short, les bottes en cuir, les bijoux inspirés des marguerites et les robes taillées dans la dentelle, l\'ambiance douce et onirique de la vie dans les plaines peut désormais faire partie du quotidien de vos Sims. Adoptez la vie des plaines, dotez vos Sims de tenues élégantes et rustiques comme la salopette short et envoyez-les découvrir les grands espaces. Donnez à vos Sims un style charmant et intemporel. Que ce soit pour un rencard pour ou un après-midi détendu au soleil, arborez des tenues vintage, des motifs floraux et des accessoires apaisants. Création de Miiko.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1764703279106.png', 'Plaines oniriques', 'MINIKIT'),
(193, '2026-02-12', 'Sirotez votre thé sous le soleil et au milieu d\'un décor élégant, le tout en bonne compagnie, avec Les Sims 4 Thé au soleil. Concevez un espace social avec des baies vitrées, un treillis en fleurs, une enceinte discrète en forme de pierre et des meubles parfaitement adaptés à un jardin ou à une salle de séjour. Pour prendre le thé avec élégance, il faut un espace magnifique, un bon sujet de conversation et, évidemment, du thé et d\'autres rafraîchissements. Cette collection comprend un superbe service à thé et un plateau de friandises, chacun aussi somptueux que fonctionnel. Créez le parfait endroit pour prendre le thé et partager vos potins en bonne compagnie.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1770149365tea.png', 'Thé au soleil', 'MINIKIT'),
(194, '2026-02-12', 'Incarnez un rôle iconique et adoptez des looks remarquables inspirés du charme d\'une période classique dans Les Sims 4 Styles classiques du cinéma. Associez une tenue iconique et des accessoires audacieux pour imposer votre pouvoir avec grâce ! Après tout, vous êtes à la tête d\'une famille. Sinon, profitez d\'un style intrigant et unique avec un imperméable et un chapeau, afin de cacher vos yeux pendant vous cherchez à dénicher des secrets. Prenez confiance en vous avec des bijoux, un manteau en fausse fourrure, des chaussures élégantes et une robe de soirée ou un costume de classe internationale. Ce kit a pour but de vous faire entrer dans le rôle de personnages hauts en couleur.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1770149365silver.png', 'Styles classiques du cinéma', 'MINIKIT'),
(195, '2026-02-26', 'Pour ajouter du charme à la pelouse de vos Sims, oubliez la perfection. C\'est la personnalité qui compte. Décorez votre jardin à fond avec Les Sims 4 Cour et jardin ! Cette collection ludique transforme des porches ordinaires et des pelouses abîmées en coins confortables et colorés. Mélangez des tons et des textures modernes à des détails intemporels pour créer un style propre à chaque quartier. Que les gens du quartier passent vous déposer un cake aux fruits ou vous observent par-dessus la haie, vos Sims resteront sociables et exhiberont leur superbe style. Et les Gothik n\'auront aucun secret pour eux. Création de Ravasheen.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1770149365wtf.png', 'Cour et jardin', 'MINIKIT'),
(196, '2026-02-26', 'Utilisez un superbe décor pour créer un espace de jeu fantaisiste avec Les Sims 4 Salle de jeu au pays des merveilles. Voilà un endroit où l\'imagination peut se développer, et ce, que vos enfants aient envie de jouer ou d\'apprendre. Avec ses étagères fantaisistes, son bureau assorti et son échiquier, cette salle de jeux permettra aux enfants de grandir tout en apprenant. Un adorable lapin en peluche, des chapeaux haut-de-forme suspendus ou un décor mural aux motifs de dodos ou de chats souriants. Tout ça, ainsi que les nombreux autres éléments de ce kit vous feront voyager dans un monde à la fois familier et fantastique.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1770149365alice.png', 'Salle de jeu au pays des merveilles', 'MINIKIT'),
(197, '2026-05-14', 'Recréez la salle de bal que vous connaissez toutes et tous et organisez l\'événement principal de la saison avec Les Sims 4 Salle de bal de Lady Bridgerton. Créez une ambiance romantique qui captivera vos convives. Pour créer une lumière envoûtante, misez sur le chandelier ! Ajoutez quelques pointes florales sur les murs et toutes les personnes présentes auront droit à leurs propres moments somptueux. Créez un décor parfait et préparez une scène où chaque danse, chaque regard, a son importance.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1778629372kit59.png', 'Salle de bal de Lady Bridgerton', 'MINIKIT'),
(198, '2026-05-14', 'Habillez-vous pour l\'événement principal de la saison avec Les Sims 4 Styles du bal masqué de Lady Bridgerton. Émerveillez les convives avec des queues-de-pie élégantes, éblouissez les curieux avec des robes soirée somptueuses et frôlez le scandale avec des accessoires raffinés comme une tiare ou un masque mystérieux. Certains de ces styles sont directement inspirés des salles de bal de la haute société britannique.', 'https://tiermaker.com/images//template_images/2022/1054531/the-sims-4-every-pack-and-dlc-up-to-growing-together-1054531/zzzzz-1778629372kit58.png', 'Styles du bal masqué de Lady Bridgerton', 'MINIKIT');
