INSERT INTO `trait_de_caractere` (`id`, `description`, `img`, `nom`, `dlc_id`, `categorie_sim`, `type`) VALUES
(8, 'Les Sims ayant une présence menaçante inspirent plus de peur aux Sims à proximité, parfois au point que ces derniers s\'évanouissent. Et Greg ? Eh bien, pour eux, c\'est un genre de chiot mignon.', 'https://static.wikia.nocookie.net/sims/images/f/fc/Trait_TS4_Threatening_Presence.png/revision/latest?cb=20230304085159', 'Présence menaçante', 8, 'ADULTE', 'ASPIRATION'),
(9, 'Ces Sims ont tendance à se concentrer facilement et peuvent partager des idées avec d\'autres Sims ; leur état risque de se détériorer s\'ils n\'ont pas améliorer leurs compétences mentales depuis longtemps.', 'https://tiermaker.com/images/media/template_images/2024/15984247/sims-4-traits-15984247/traitts4genius.png', 'Génie', 6, 'ADULTE', 'BASE'),
(10, 'Les Sims collectionneurs trouvent plus souvent des objets à collectionner rares !', 'https://static.wikia.nocookie.net/sims/images/9/9d/Collectionneur.webp/revision/latest/scale-to-width-down/50?cb=20220314130132&path-prefix=fr', 'Collectionneur', 6, 'ADULTE', 'BONUS'),
(11, 'Les Sims ayant une immunité résistante ont moins de chances de tomber malades et se remettent plus vite des maladies.', 'https://static.wikia.nocookie.net/sims/images/7/79/R%C3%A9sistance_%C3%A0_la_maladie.webp/revision/latest/scale-to-width-down/50?cb=20220319105533&path-prefix=fr', 'Résistance à la maladie', 7, 'ADULTE', 'CARRIERE'),
(12, 'Waouh ! Le Père Hiver est en fait le père de votre Sim ! C\'est incroyable ! Je me demande si il a hérité de pouvoirs magiques ?', 'https://static.wikia.nocookie.net/sims/images/6/60/B%C3%A9b%C3%A9_du_P%C3%A8re_Hiver.webp/revision/latest/scale-to-width-down/50?cb=20220318182736&path-prefix=fr', 'Bébé du Père Hiver', 9, 'ADULTE', 'HERITAGE'),
(13, 'Les Sims irresponsables sont mal à l\'aise au travail, mais ressentent beaucoup de joie lorsqu\'ils ignorent les factures ou font le minimum d\'efforts. Ils peuvent également vivre des situations inédites au travail.', 'https://static.wikia.nocookie.net/sims/images/d/d6/Irresponsable.webp/revision/latest/scale-to-width-down/50?cb=20220318185803&path-prefix=fr', 'Irresponsable', 10, 'ADULTE', 'EDUCATION'),
(14, 'Les Sims ayant le trait de caractère Vessie d\'acier n\'ont presque jamais à se soucier des besoins de leur vessie.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/steel-bladder.png', 'Vessie d\'acier', 6, 'ADULTE', 'BOUTIQUE'),
(21, 'Ce Sim a été dévoré par la Plante Mère et profitera pour toujours de l\'avantage de ne jamais voir baisser le niveau de ses besoins.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4consumedbythemother.png', 'Dévoré par la Plante Mère', 38, 'ADULTE', 'FANTOME'),
(22, 'Ces Sims obtiennent des états d\'esprit puissants grâce à leurs réussites professionnelles et des états d\'esprit négatifs en cas d\'échec professionnel ; leur état risque de se détériorer s\'ils n\'obtiennent pas de promotion.', 'https://tiermaker.com/images/media/template_images/2024/15984247/sims-4-traits-15984247/traitts4ambitious.png', 'Ambitieux', 6, 'ADULTE', 'BASE'),
(23, 'Les Sims ayant ce trait de caractère sont en permanence emportés par le tourbillon de l\'amour. Il tombent amoureux facilement et expriment souvent ouvertement leurs sentiments.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316lovebug.png', 'A un cœur d\'artichaut', 28, 'ADULTE', 'BASE'),
(24, 'Ces Sims ont tendance à être inspirés et peuvent partager des idées créatives avec d\'autres Sims ; leur état risque de se détériorer s\'ils ne sont pas créatifs pendant une trop longue période.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315creative.png', 'Créatif', 6, 'ADULTE', 'BASE'),
(25, 'Les Sims délicats ont la nausée en voyant des bestioles dégoûtantes, des Sims en train de vomir, de la violence ou un décès. Ces Sims sont mal à l\'aise dès qu\'ils sont à proximité de quelque chose de sale.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316squeamish.png', 'Délicat', 33, 'ADULTE', 'BASE'),
(26, 'Ces Sims nécessitent plus d\'efforts pour être heureux. Leurs problèmes peuvent parfois sembler triviaux, et peuvent même sortir de nulle part. Vous pouvez remédier à ces épreuves grâce à des activités relaxantes qui mettent ces Sims dans un état de catharsis.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316high-maintenance.png', 'Exigeant', 34, 'ADULTE', 'BASE'),
(27, 'Ces Sims deviennent tendus à proximité des Sims enjôleurs et sont rarement enjôleurs eux-mêmes. Il est difficile pour eux d\'être romantiques en public.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316unflirty.png', 'Froid', 17, 'ADULTE', 'BASE'),
(28, 'Ces Sims obtiennent des états d\'esprit puissants en regardant la chaîne pour enfants, deviennent joueurs lorsqu\'ils jouent avec des enfants et sont heureux lorsqu\'ils s\'amusent avec des jouets pour enfants.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315childish.png', 'Immature', 6, 'ADULTE', 'BASE'),
(29, 'Ces Sims peuvent se parler à eux-mêmes ou ont des émotions imprévisibles.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315erratic.png', 'Imprévisible', 6, 'ADULTE', 'BASE'),
(30, 'Ces Sims ont tendance à être plus heureux que les autres Sims.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315cheeful.png', 'Joyeux', 6, 'ADULTE', 'BASE'),
(31, 'Ces Sims ont tendance à échouer plus souvent lors des activités physiques et à rire de ces échecs au lieu de mal les prendre.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315clumsy.png', 'Maladroit', 6, 'ADULTE', 'BASE'),
(32, 'Ces Sims ont tendance à être tristes et peuvent partager leurs pensées mélancoliques avec d\'autres Sims. Leur compétence Créativité s\'améliore particulièrement lorsqu\'ils sont tristes.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316gloomy.png', 'Morose', 6, 'ADULTE', 'BASE'),
(33, 'Les Sims paranoïaques ont l\'impression qu\'un danger se cache à chaque coin de rue et que les gens parlent d\'eux en permanence. Ils se sentent en sécurité lorsqu\'ils sont dans un sous-sol.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316paranoid.png', 'Paranoïaque', 38, 'ADULTE', 'BASE'),
(34, 'Ces Sims ont tendance à être joueur.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316goofball.png', 'Pitre', 6, 'ADULTE', 'BASE'),
(35, 'Ces Sims se comportent souvent de façon prudente dans le domaine de l\'amour, et préfèrent prendre leur temps de bâtir des connexions émotionnelles solides avant de se lancer la tête la première dans une relation amoureuse.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316romantically-reserved.png', 'Prudent en amour', 28, 'ADULTE', 'BASE'),
(36, 'Ces Sims ont tendance à être enjôleurs et risquent d\'être tristes s\'ils n\'ont aucune interaction sociale romantique pendant trop longtemps.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316romantic.png', 'Romantique', 6, 'ADULTE', 'BASE'),
(37, 'Ces Sims ont tendance à se mettre en colère, peuvent énerver d\'autres Sims et peuvent aussi se mettre en colère lorsqu\'ils sont la cible d\'actes malicieux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316hot-headed.png', 'Sang chaud', 6, 'ADULTE', 'BASE'),
(38, 'Ces Sims ont généralement confiance en eux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316self-assured.png', 'Sûr de lui', 6, 'ADULTE', 'BASE'),
(39, 'Ces Sims peuvent s\'enthousiasmer à propos de la nature devant d\'autres Sims et sont heureux lorsqu\'ils sont à l\'extérieur.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316loves-outdoors.png', 'Adore la nature', 6, 'ADULTE', 'BASE'),
(40, 'Ces Sims obtiennent des états d\'esprit puissants et améliorent leur besoin Divertissement en écoutant de la musique ; ils sont heureux lorsqu\'ils jouent d\'un instrument.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316music-lover.png', 'Aime la musique', 6, 'ADULTE', 'BASE'),
(41, 'Ces Sims obtiennent des états d\'esprit puissants en voyant des œuvres d\'art et peuvent admirer ces dernières et discuter d\'art de manière unique.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315art-lover.png', 'Amateur d\'art', 6, 'ADULTE', 'BASE'),
(42, 'Ces Sims sont heureux lorsqu\'ils fabriquent des choses. Ils deviennent tristes lorsque cela fait longtemps qu\'ils n\'ont pas créé quelque chose avec la Machine à fabriquer, la Station de fabrication de bougies, le pétilleur ou l\'établi d\'ébéniste. Ne pas réussir à créer ou réparer des objets n\'a pas d\'effets négatifs sur eux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316maker.png', 'Fabricant', 12, 'ADULTE', 'BASE'),
(43, 'Ces Sims sont heureux lorsqu\'ils lisent de la science-fiction ou jouent à des jeux vidéo et peuvent devenir tendus s\'ils n\'ont pas beaucoup joué. Ils sont plus doués que les autres Sims pour trouver des objets à collectionner et peuvent discuter de trucs de geeks avec d\'autres geeks.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315geek.png', 'Geek', 6, 'ADULTE', 'BASE'),
(44, 'Ces Sims sont heureux et gagnent en divertissement lorsqu\'ils mangent de la bonne nourriture. Ils se sentent mal à l\'aise lorsqu\'ils mangent de la mauvaise nourriture et peuvent regarder des émissions de cuisine pour s\'inspirer.', 'https://tiermaker.com/images/media/template_images/2024/15984247/sims-4-traits-15984247/traitts4foodie.png', 'Gourmand', 6, 'ADULTE', 'BASE'),
(45, 'Ces Sims mettent plus de temps à fabriquer des objets mais ces derniers sont également de meilleure qualité ; ils obtiennent des états d\'esprit puissants en fabriquant un objet de qualité élevée, et des états d\'esprit négatifs s\'ils fabriquent un objet de mauvaise qualité.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316perfectionist.png', 'Perfectionniste', 6, 'ADULTE', 'BASE'),
(46, 'Ces Sims obtiennent des états d\'esprit puissants en lisant des livres ; ils peuvent aussi analyser des livres et discuter de livres de manière unique.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315bookworm.png', 'Rat de bibliothèque', 6, 'ADULTE', 'BASE'),
(47, 'Ces Sims ont tendance à être énergisés et peuvent mettre d\'autres Sims en forme ; leur état risque de se détériorer s\'ils ne font pas d\'exercice pendant trop longtemps.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315active.png', 'Actif', 6, 'ADULTE', 'BASE'),
(48, 'Ces Sims sont obsédés par les animaux et recherchent souvent leur compagnie. S\'occuper des animaux et nouer des liens avec eux est plus facile pour eux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315animal-enthusiast.png', 'Adore les animaux', 23, 'ADULTE', 'BASE'),
(49, 'Ces Sims ont tendance à faire des chats leurs compagnons, et préfèrent la compagnie de ces animaux à celle des autres Sims.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315cat-lover.png', 'Amoureux des chats', 18, 'ADULTE', 'BASE'),
(50, 'Ces Sims adorent être avec des chiens. Ils développent leurs relations avec eux plus rapidement et interagissent davantage avec eux que la plupart des Sims.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315dog-lover.png', 'Amoureux des chiens', 18, 'ADULTE', 'BASE'),
(51, 'Ces Sims sont à la recherche d\'expériences inédites et uniques !', 'https://tiermaker.com/images/media/template_images/2024/15984247/sims-4-traits-15984247/traitts4adventurous.png', 'Aventureux', 22, 'ADULTE', 'BASE'),
(52, 'Ces Sims ne sont pas dérangés par un environnement sale et salissent plus rapidement les objets du foyer.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316slob.png', 'Crasseux', 6, 'ADULTE', 'BASE'),
(53, 'Ces Sims sont des acharnés du recyclage. Recycler et fouiller des poubelles pour trouver des débris et morceaux leur est bénéfique ; par contre, il vaut mieux qu\'ils ne restent pas trop longtemps sans pratiquer ce loisir.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316recycle-disciple.png', 'Disciple du recyclage', 12, 'ADULTE', 'BASE'),
(54, 'Répondez à l\'appel de l\'océan ! Les Sims ayant ce trait de caractère préfèrent les activités liées à l\'eau et se sentent plus proches des habitants de la mer.', 'https://static.wikia.nocookie.net/sims/images/4/40/Trait_TS4_Child_of_the_Ocean.png/revision/latest?cb=20190630214655', 'Enfant de l\'océan', 20, 'ADULTE', 'BASE'),
(55, 'Ces Sims ressentent un lien spirituel avec les îles de Sulani. Honorez les îles en participant à leur culture, faites venir de puissants éléments et obtenez les récompenses de leurs bénédictions... ou les conséquences de leur colère.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315child-of-the-islands.png', 'Enfant des îles', 20, 'ADULTE', 'BASE'),
(56, 'Ces Sims rejettent le consumérisme et préfèrent réduire les dépenses inutiles par tous les moyens. Ils aiment trouver des objets et des aliments réutilisés ou jetés. En fait, ce sont eux qui ont le plus de chances de trouver des trésors de grande qualité dans les bennes ordures ! Ils peuvent devenir tendus ou mal à l\'aise s\'ils passent trop de temps à gagner ou dépenser des simflouz.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315freegan.png', 'Freegan', 12, 'ADULTE', 'BASE'),
(57, 'Ces Sims réagissent de manière plus négative à la faim que les autres Sims, apprécient toujours de manger (quelle que soit la qualité de la nourriture), peuvent manger de la nourriture gâtée et peuvent chercher de la nourriture dans les poubelles.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316glutton.png', 'Glouton', 6, 'ADULTE', 'BASE'),
(58, 'Les Sims hyper-écolos sont particulièrement heureux lorsqu\'ils vivent dans une rue écologique et s\'efforcent en permanence de rendre leur environnement plus écologique.', 'https://tiermaker.com/images/media/template_images/2024/15984247/sims-4-traits-15984247/traitts4greenfiend.png', 'Hyper-écolo', 12, 'ADULTE', 'BASE'),
(59, 'Ces Sims seront malade si ils mangent des produits laitiers mais se sentiront incroyablement bien s\'ils les évitent un certain temps.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316lactose-intolerant.png', 'Intolérant au lactose', 23, 'ADULTE', 'BASE'),
(60, 'Ces Sims n\'ont aucun problème à \"emprunter\" des choses aux autres d\'un simple geste, mais deviennent tendus s\'ils n\'ont rien volé depuis un certain temps.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316kleptomaniac.png', 'Kleptomane', 6, 'ADULTE', 'BASE'),
(61, 'Ces Sims n\'ont qu\'une hâte : danser et faire la fête toute la nuit ! Dans les endroits comme les bars, les boîtes de nuit et les bars à cocktail, ils peuvent obtenir un élan d\'énergie avec l\'interaction \"Que la fête commence\" ! Les machines à danser reçoivent un état d\'esprit Heureux lorsqu\'elles arrivent dans des endroits sociaux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315dance-machine.png', 'Machine à danser', 16, 'ADULTE', 'BASE'),
(62, 'Ces Sims peuvent admirer leur bien et s\'en vanter, et sont tristes s\'ils n\'ont rien acheté de nouveau depuis trop longtemps.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316materialistic.png', 'Matérialiste', 6, 'ADULTE', 'BASE'),
(63, 'Ces Sims obtiennent des états d\'esprit puissants en regardant la télévision, en faisant la sieste ou en s\'installant sur des meubles confortables ; ils sont plus rapidement fatigués s\'ils font de l\'exercice, et sont tendus lorsqu\'ils doivent faire les corvées du foyer.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316lazy.png', 'Paresseux', 6, 'ADULTE', 'BASE'),
(64, 'Ces Sims excellent dans les activités de ranch, tirent une grande fierté de leur travail et aiment les corvées de ranch et s\'occuper de leur bétail.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316rancher.png', 'Propriétaire de ranch', 26, 'ADULTE', 'BASE'),
(65, 'Ces Sims peuvent critiquer des objets de mauvaise qualité, sont blasés devant les émissions de télévision sans prétentions intellectuelles et améliorent leur confiance en eux en présence d\'autres Sims snobs.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316snob.png', 'Snob', 6, 'ADULTE', 'BASE'),
(66, 'Ces Sims sont heureux et passent un bon moment lorsqu\'ils font le ménage dans le foyer, peuvent avoir une frénésie de nettoyage et sont très mal à l\'aise dans un environnement sale.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316neat.png', 'Soigné', 6, 'ADULTE', 'BASE'),
(67, 'Ces Sims évitent activement de manger de la nourriture contenant de la viande et peuvent être malade si cela arrive.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316vegetarian.png', 'Végétarien', 6, 'ADULTE', 'BASE'),
(68, 'Ces Sims ont un lien fort avec les chevaux, et ont plus de facilités pour interagir avec les chevaux et s\'occuper d\'eux que les autres Sims.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316horse-lover.png', 'Amoureux des chevaux', 26, 'ADULTE', 'BASE'),
(69, 'Ces Sims ont tendance à désapprouver les comportements inappropriés des autres Sims, mais sont plus heureux lorsqu\'ils portent des tenues habillées et ont beaucoup plus de facilités avec les interactions sociales amicales et romantiques.', 'https://static.wikia.nocookie.net/sims/images/e/eb/Trait_TS4_Proper.png/revision/latest?cb=20201113101736', 'Bien élevé', 22, 'ADULTE', 'BASE'),
(70, 'Ces Sims sont heureux en présence de Sims avec des états d\'esprit positifs, peuvent faire des dons à une œuvre caritative, sont tristes lorsqu\'ils interagissent avec des Sims malveillants et peuvent discuter de la paix dans le monde.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316good.png', 'Bienveillant', 6, 'ADULTE', 'BASE'),
(71, 'Ces Sims sont en colère en présence d\'enfants, sont tendus après avoir essayé de faire un bébé et peuvent être méchants avec leurs enfants.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316hates-children.png', 'Déteste les enfants', 6, 'ADULTE', 'BASE'),
(72, 'Ces Sims sont totalement autocentrés ! Ils peuvent chercher des compliments, sont plus enthousiastes lorsqu\'ils reçoivent un cadeau et peuvent devenir tendus s\'ils ne reçoivent pas assez d\'attention. Généralement, ils adorent être sous les yeux des projecteurs en tant que célébrités. Après tout, tout le monde devrait les aimer autant qu\'ils s\'aiment, n\'est-ce pas ?', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316self-absorbed.png', 'Egocentrique', 19, 'ADULTE', 'BASE'),
(73, 'Ces Sims obtiennent des états d\'esprit puissants lorsqu\'ils discutent de manière amicale, ont un besoin social qui se détériore rapidement et obtiennent des états d\'esprit plus négatifs que les autres Sims lorsque le niveau de satisfaction de leur besoin Social est bas.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316outgoing.png', 'Extraverti', 6, 'ADULTE', 'BASE'),
(74, 'Ces Sims adorent faire partie de groupes et sont particulièrement heureux lorsqu\'ils sont entourés de leurs amis.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316insider.png', 'Initié', 16, 'ADULTE', 'BASE'),
(77, 'Ces Sims sont plus facilement jaloux que les autres Sims. Leur confiance en eux s\'améliore lorsque leur moitié est à leurs côtés, mais ils peuvent devenir tendus s\'ils ne l\'ont pas vue récemment.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316jealous.png', 'Jaloux', 6, 'ADULTE', 'BASE'),
(78, 'Ces Sims sont heureux lorsqu\'ils sont entourés de Sims ayant des états d\'esprit négatifs, peuvent rire de manière maléfique et discuter de projets maléfiques ; ils se mettent en colère lorsqu\'ils interagissent avec des Sims bienveillants.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315evil.png', 'Malveillant', 6, 'ADULTE', 'BASE'),
(79, 'Ces Sims peuvent faire une accolade virile à leur potes, renforcer leur confiance en eux quand ils sont avec leurs potes et devenir énergisés en regardant du sport.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315bro.png', 'Membre d\'un groupe de potes', 6, 'ADULTE', 'BASE'),
(80, 'Ces Sims trouvent leur bonheur en étant méchants ou malicieux envers d\'autres Sims et deviennent confiants après avoir gagné un combat.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316mean.png', 'Méchant', 6, 'ADULTE', 'BASE'),
(81, 'Ces Sims sont heureux lorsqu\'ils sont entourés des membres de leur famille et tristes s\'ils n\'interagissent pas avec leur famille pendant trop longtemps ; ils peuvent aussi frimer sur leur famille.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315family-oriented.png', 'Proche de sa famille', 6, 'ADULTE', 'BASE'),
(82, 'Ces Sims deviennent tendus si un emploi ou une relation dure depuis un certain temps et sont heureux lorsqu\'ils démissionnent ou mettent fin à une relation ; ils attendent plus longtemps avant de faire une demande en mariage et peuvent discuter de leur peur de l\'engagement.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316noncommittal.png', 'Réticent à s\'engager', 6, 'ADULTE', 'BASE'),
(83, 'Ces Sims sont heureux lorsqu\'ils sont seuls et ne reçoivent pas d\'états d\'esprit négatifs lorsque leur besoin Social est préoccupant ; ils sont tendus en présence d\'inconnus et sont plus souvent embarrassés par un rejet social.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316loner.png', 'Solitaire', 6, 'ADULTE', 'BASE'),
(84, 'Ce Sim est mort dans un incendie et est encore hanté par les flammes.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyfire.png', 'Mort brûlé', 6, 'ADULTE', 'FANTOME'),
(85, 'Apparemment, il est possible d\'en faire trop. Ce Sim l\'a fait jusqu\'à la mort.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyoverexertion.png', 'Mort d\'épuisement', 6, 'ADULTE', 'FANTOME'),
(86, 'Ce Sim est mort à cause d\'une exposition prolongée à de hautes températures.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyoverheating.png', 'Mort de chaud', 9, 'ADULTE', 'FANTOME'),
(87, 'Ce Sim est mort d\'apoplexie et sa rage est toujours en lui.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyanger.png', 'Mort de colère', 6, 'ADULTE', 'FANTOME'),
(88, 'Ce Sim est mort de faim et les crampes d\'estomac l\'ont suivie jusque dans l\'au-delà.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyhunger.png', 'Mort de faim', 6, 'ADULTE', 'FANTOME'),
(89, 'Ce Sim est mort à cause d\'une exposition excessive à des températures glaciales.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyfreezing.png', 'Mort de froid', 9, 'ADULTE', 'FANTOME'),
(90, 'Ce Sim était tellement mortifié qu\'il est mort de honte. Littéralement.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyembarrassment.png', 'Mort de honte', 6, 'ADULTE', 'FANTOME'),
(91, 'Ce Sim a succombé à la Fièvre du rongeur enragé et sème désormais la peur de l\'épidémie dans l\'au-delà.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyrabidrodentfever.png', 'Mort de la Fièvre du rongeur enragé', 137, 'ADULTE', 'FANTOME'),
(92, 'Ce Sim est mort d\'un fou rire qui continue à revenir de temps en temps.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbylaughter.png', 'Mort de rire', 6, 'ADULTE', 'FANTOME'),
(93, 'Ce Sim est mort quand son heure est venue.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyoldage.png', 'Mort de vieillesse', 6, 'ADULTE', 'FANTOME'),
(94, 'Ce Sim a été dévoré par une Plante vache et n\'est toujours pas très à l\'aise avec les plantes.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbycowplant.png', 'Mort dévoré par une Plante vache', 6, 'ADULTE', 'FANTOME'),
(95, 'Ce Sim est mort suite à un empoisonnement.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbypoison.png', 'Mort par empoisonnement', 37, 'ADULTE', 'FANTOME'),
(96, 'Les fantômes en excès d\'énergie sont des cibles valides pour les interactions magiques dont les duels, la formation, etc.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/spellcasteroverloadicon.png', 'Mort par excès d\'énergie magique', 121, 'ADULTE', 'FANTOME'),
(97, 'Ce Sim est mort suite à une exposition excessive à la vapeur ; il a donc toujours chaud et est constamment déshydraté.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbysteam.png', 'Mort par excès de vapeur', 34, 'ADULTE', 'FANTOME'),
(98, 'Ce Sim est mort à cause d\'une surexposition aux rayons UV nocifs !', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbysunlight.png', 'Mort par exposition au soleil', 36, 'ADULTE', 'FANTOME'),
(99, 'Ce Sim a perdu la vie en mangeant un poisson très toxique.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbypufferfish.png', 'Mort par fugu', 17, 'ADULTE', 'FANTOME'),
(100, 'Ce Sim s\'est noyé dans une étendue d\'eau et a maintenant peur de l\'eau.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbydrowning.png', 'Mort par noyade', 6, 'ADULTE', 'FANTOME'),
(101, 'La mort a frappé votre Sim sous la forme d\'une composition florale au parfum fatal. Votre Sim n\'a pas su dire non à un cadeau et l\'a payé très cher.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyflowers.png', 'Mort tué par des fleurs', 9, 'ADULTE', 'FANTOME'),
(102, 'Ce Sim a trouvé la mort en chutant de très haut.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyfalling.png', 'Mort à cause d\'une chute de très haut', 22, 'ADULTE', 'FANTOME'),
(103, 'Ce Sim n\'a pas pu supporter la force écrasante du distributeur et en est mort.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyvendingmachine.png', 'Mort écrasé par un distributeur', 22, 'ADULTE', 'FANTOME'),
(104, 'Ce Sim a trouvé la mort à cause d\'un lit escamotable vengeur.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbymurphybed.png', 'Mort écrasé par un lit escamotable', 139, 'ADULTE', 'FANTOME'),
(105, 'Ce Sim a été choqué lorsqu\'il a subi une électrocution fatale.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyelectrocution.png', 'Mort électrocuté', 6, 'ADULTE', 'FANTOME'),
(106, 'Ce Sim a été frappé par la foudre une fois de trop.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbylightning.png', 'Mort électrocuté par la foudre', 6, 'ADULTE', 'FANTOME'),
(107, 'Pour ce Sim, la mort est arrivée sous la forme d\'une boisson aux insectes bien préparée. Il peut désormais se détendre dans une maison hantée.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbybeetles.png', 'Tué par des scarabées', 12, 'ADULTE', 'FANTOME'),
(108, 'Ce Sim a trouvé la mort suite à l\'attaque d\'un essaim de mouches en colère.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbyflies.png', 'Tué par un essaim de mouches', 12, 'ADULTE', 'FANTOME'),
(109, 'Ce Sim a provoqué un lapin tueur et il l\'a payé au prix fort.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbykillerrabbit.png', 'Tué par un lapin tueur', 23, 'ADULTE', 'FANTOME'),
(110, 'Considérez que c\'est le prix à payer pour avoir agi méchamment contre une volaille.', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbykillerchicken.png', 'Tué par une volaille tueuse', 23, 'ADULTE', 'FANTOME'),
(111, 'Ce Sim est l\'incarnation, ou plutôt la \"désincarnation\" des champignons après avoir succombé à de la moisissure. Certains disent que cette moisissure lui a donné des pouvoirs, mais les utilisera-t-il pour faire quelque chose de positif ?', 'https://tiermaker.com/images/media/template_images/2024/1457058/sim-causes-of-death-sims-4-1457058/traitts4deathbymold.png', 'Tué par la moisissure', 27, 'ADULTE', 'FANTOME'),
(112, 'Les relations avec des animaux commencent à un niveau plus élevé.', 'https://static.wikia.nocookie.net/sims/images/7/7b/Trait_TS4_Animal_Affection.png/revision/latest?cb=20171114194753', 'Affection animal', 18, 'ADULTE', 'BONUS'),
(113, 'Il est plus facile de rester mince lorsque vous avez le trait Bon métabolisme.', 'https://static.wikia.nocookie.net/sims/images/6/6a/Trait_TS4_High_Metabolism.png/revision/latest?cb=20150227045559', 'Bon métabolisme', 6, 'ADULTE', 'BONUS'),
(114, 'Les muses obtiennent de meilleures améliorations de leurs compétences quand elles sont inspirées.', 'https://static.wikia.nocookie.net/sims/images/f/fc/Trait_TS4_Muser.png/revision/latest?cb=20150301185823', 'Muse', 6, 'ADULTE', 'BONUS'),
(115, 'Les Sims ignobles réalisent des interactions méchantes plus puissantes et plus efficaces.', 'https://static.wikia.nocookie.net/sims/images/5/58/Trait_TS4_Dastardly.png/revision/latest?cb=20150301190012', 'Ignoble', 6, 'ADULTE', 'BONUS'),
(116, 'Les Sims très famille ont plus vite de fortes relations familiales.', 'https://static.wikia.nocookie.net/sims/images/0/09/Trait_TS4_Domestic.png/revision/latest?cb=20150301190003', 'Très famille', 6, 'ADULTE', 'BONUS'),
(117, 'Les Sims dotés du trait Essence de saveur font mieux la cuisine et les boissons.', 'https://static.wikia.nocookie.net/sims/images/e/e0/Trait_TS4_Essence_of_Flavor.png/revision/latest?cb=20150301185942', 'Essence de saveur', 6, 'ADULTE', 'BONUS'),
(118, 'Les Sims doués en affaire gagnent plus que le salaire standard en travaillant.', 'https://static.wikia.nocookie.net/sims/images/1/18/Trait_TS4_Business_Savvy.png/revision/latest?cb=20150301190052', 'Doué en affaires', 6, 'ADULTE', 'BONUS'),
(119, 'Les Sims qui apprennent vite développent toutes les compétences un peu plus vite que les autres !', 'https://static.wikia.nocookie.net/sims/images/4/49/Trait_TS4_Quick_Learner.png/revision/latest?cb=20150301185748', 'Apprend vite', 6, 'ADULTE', 'BONUS'),
(120, 'Ces Sims sont heureux lorsqu\'ils sont dans leur quartier.', 'https://static.wikia.nocookie.net/sims/images/0/09/Trait_TS4_Domestic.png/revision/latest?cb=20150301190003', 'Attaché à son quartier', 17, 'ADULTE', 'BONUS'),
(121, 'Les Sims séduisants ont plus de succès que les autres en amour.', 'https://static.wikia.nocookie.net/sims/images/7/72/Trait_TS4_Alluring.png/revision/latest?cb=20150301190109', 'Séduisant', 6, 'ADULTE', 'BONUS'),
(122, 'Les Sims sociables nouent plus vite des liens amicaux.', 'https://static.wikia.nocookie.net/sims/images/1/1d/Trait_TS4_Gregarious.png/revision/latest?cb=20150301185857', 'Sociable', 6, 'ADULTE', 'BONUS'),
(123, 'Les voyageurs préparés améliorent légèrement le niveau de leurs besoins lors de leurs voyages.', 'https://static.wikia.nocookie.net/sims/images/7/7c/Trait_TS4_Prepared_Voyager.png/revision/latest?cb=20200909112915', 'Voyageur préparé', 122, 'ADULTE', 'BONUS'),
(124, 'Tout est gratuit au SPA pour les Sims ayant ce trait.', 'https://static.wikia.nocookie.net/sims/images/d/d9/Trait_TS4_Spa_Membership.png/revision/latest?cb=20210907210032', 'Abonnement au SPA', 34, 'ADULTE', 'BONUS'),
(125, 'Ces Sims obtiennent un bonus de relation initial lorsqu\'ils se présentent à des loups-garous (bonus positif ou négatif en fonction de leur comportement !)', 'https://static.wikia.nocookie.net/sims/images/2/21/Lunar_Confidant.png/revision/latest?cb=20220619225658', 'Confident lunaire', 8, 'ADULTE', 'BONUS'),
(126, 'Les Sims à qui on peut s\'identifier lient plus rapidement des relations amicales avec les autres ados.', 'https://static.wikia.nocookie.net/sims/images/f/f7/Trait_TS4_Relatable.png/revision/latest?cb=20220729181254', 'Sim à qui on peut s\'identifier', 24, 'ADO', 'BONUS'),
(127, 'Ces Sims développent généralement leurs compétences plus rapidement et sont heureux lorsqu\'ils terminent des tâches professionnelles, mais ont un peu plus de mal à se faire des amis et à les garder.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316overachiever.png', 'Élève brillant', 24, 'ADULTE', 'BASE'),
(128, 'Ces Sims aiment faire la fête et le font savoir à tout le monde en motivant les groupes de Sims et en faisant des trucs de fête.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316party-animal.png', 'Fêtard', 24, 'ADULTE', 'BASE'),
(129, 'Ces Sims ont du mal à gérer les situations sociales et développent plus lentement la compétence Charisme, mais obtiennent des états d\'esprit et des sentiments puissants lorsqu\'ils parviennent à surmonter leur gêne et leur nervosité pour lier des amitiés fortes.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316socially-awkward.png', 'Mal à l\'aise en société', 24, 'ADULTE', 'BASE'),
(130, 'Ces chats aiment vraiment leurs maîtres et font tout pour rester près d\'eux dès que possible.', 'https://static.wikia.nocookie.net/sims/images/3/37/Affectueux.webp/revision/latest?cb=20220317180001&path-prefix=fr', 'Affectueux', 18, 'CHAT', 'BASE'),
(131, 'Ces animaux sont généralement amicaux avec les Sims et sont ravis de les saluer.', 'https://static.wikia.nocookie.net/sims/images/0/07/Amical_%28chat%29.webp/revision/latest?cb=20220317180106&path-prefix=fr', 'Amical', 18, 'CHAT', 'BASE'),
(132, 'Ces chats adorent miauler en cœur avec les Sims. Ils essayent même de chanter si vous leur demandez !', 'https://static.wikia.nocookie.net/sims/images/f/f4/Bavard.webp/revision/latest?cb=20220317180156&path-prefix=fr', 'Bavard', 18, 'CHAT', 'BASE'),
(133, 'Ces chats sont plus curieux de ce qui les entoure. Ils aiment chercher différents objets dans la maison.', 'https://static.wikia.nocookie.net/sims/images/5/54/Curieux_%28chat%29.webp/revision/latest?cb=20220317180252&path-prefix=fr', 'Curieux', 18, 'CHAT', 'BASE'),
(134, 'Ces chats n\'ont pas vraiment besoin de maîtres ; ils sont là juste pour la nourriture gratuite.', 'https://static.wikia.nocookie.net/sims/images/7/7d/Distant.webp/revision/latest?cb=20220317180413&path-prefix=fr', 'Distant', 18, 'CHAT', 'BASE'),
(135, 'Ces chats adorent vagabonder dans le monde comme s\'ils étaient des animaux sauvages ! Mais ne vous inquiétez pas : ils reviennent toujours chez eux pour avoir à manger.', 'https://static.wikia.nocookie.net/sims/images/7/7a/Esprit_libre.webp/revision/latest?cb=20220317180517&path-prefix=fr', 'Esprit libre', 18, 'CHAT', 'BASE'),
(136, 'Ces chats sont plus actifs que les autres chats. Ils aiment vraiment bondir et courir partout.', 'https://static.wikia.nocookie.net/sims/images/8/87/Fol%C3%A2tre.webp/revision/latest?cb=20220317180600&path-prefix=fr', 'Folâtre', 18, 'CHAT', 'BASE'),
(137, 'Ces chats apprennent vite ; certains disent qu\'ils peuvent comprendre le simlish lorsqu\'on leur parle.', 'https://static.wikia.nocookie.net/sims/images/3/35/Fut%C3%A9.webp/revision/latest?cb=20220317180650&path-prefix=fr', 'Futé', 18, 'CHAT', 'BASE'),
(138, 'Ces chats sont des créatures trop gâtées. Les gronder ne change presque jamais leur comportement.', 'https://static.wikia.nocookie.net/sims/images/e/ef/G%C3%A2t%C3%A9.webp/revision/latest?cb=20220317180737&path-prefix=fr', 'Gâté', 18, 'CHAT', 'BASE'),
(139, 'Ces animaux mangent nettement plus souvent que les autres et beaucoup plus salement.', 'https://static.wikia.nocookie.net/sims/images/b/bb/Glouton_%28chien%29.webp/revision/latest?cb=20220317165518&path-prefix=fr', 'Glouton', 18, 'CHAT', 'BASE'),
(140, 'Ces animaux adorent les jouets et veulent jouer tout le temps, même lorsqu\'ils ne sont pas excités.', 'https://static.wikia.nocookie.net/sims/images/4/48/Joueur_%28chat%29.webp/revision/latest?cb=20220317180858&path-prefix=fr', 'Joueur', 18, 'CHAT', 'BASE'),
(141, 'Ces chats mijotent toujours quelque chose ! Ils se comportent souvent mal et peuvent même être incités à le faire.', 'https://static.wikia.nocookie.net/sims/images/5/5e/Malicieux.webp/revision/latest?cb=20220317180955&path-prefix=fr', 'Malicieux', 18, 'CHAT', 'BASE'),
(142, 'Ces chats ont peur de tout. Bon d\'accord, de presque tout. Ils aiment aussi beaucoup se cacher.', 'https://static.wikia.nocookie.net/sims/images/3/38/Nerveux.webp/revision/latest?cb=20220317181049&path-prefix=fr', 'Nerveux', 18, 'CHAT', 'BASE'),
(143, 'Ces chats adorent une petite sieste. Ils sont également moins enclins à sauter d\'un endroit à un autre car cela demande trop d\'efforts.', 'https://static.wikia.nocookie.net/sims/images/9/9c/Paresseux_%28chat%29.webp/revision/latest?cb=20220317181139&path-prefix=fr', 'Paresseux', 18, 'CHAT', 'BASE'),
(144, 'Ces chats ont des poils plus longs que la normale ! Ils vomissent plus souvent des boules de poils.', 'https://static.wikia.nocookie.net/sims/images/0/02/Poils_longs.webp/revision/latest?cb=20220317181225&path-prefix=fr', 'Poils longs', 18, 'CHAT', 'BASE'),
(145, 'Ces chats adorent rôder dans le quartier. Faites-les sortir et ils reviendront peut-être avec quelque chose qu\'ils ont trouvé.', 'https://static.wikia.nocookie.net/sims/images/0/08/Pr%C3%A9dateur.webp/revision/latest?cb=20220317181311&path-prefix=fr', 'Prédateur', 18, 'CHAT', 'BASE'),
(146, 'Ces chats sont très protecteurs avec leur territoire. Ils sont agressifs avec tous les inconnus qu\'ils rencontrent.', 'https://static.wikia.nocookie.net/sims/images/e/ef/Territorial.webp/revision/latest?cb=20220317181357&path-prefix=fr', 'Territorial', 18, 'CHAT', 'BASE'),
(147, 'Ces nourrissons sont sujets à l\'érythème fessier, sout souvent difficiles en matière de nourriture, et peuvent plus facilement devenir surstimulés s\'il y a trop de jeu et d\'interactions sociales. Cependant, ils se reposent aussi de façon plus paisible la nuit lorsque quelqu\'un les calme.', 'https://static.wikia.nocookie.net/sims/images/8/8f/TS4_Trait_Nourrisson_Sensible.png/revision/latest?cb=20230319165150&path-prefix=fr', 'Sensible', 6, 'NOURRISSON', 'BASE'),
(148, 'Ces Sims passent leur temps à sourire et à gazouiller et aiment interagir avec d\'autres Sims, mais ils nécessitent plus d\'attention.', 'https://static.wikia.nocookie.net/sims/images/3/32/TS4_Trait_Nourrisson_Solaire.png/revision/latest?cb=20230319165422&path-prefix=fr', 'Solaire', 6, 'NOURRISSON', 'BASE'),
(149, 'Ces sims bougent tout le temps et veulent jouer et se déplacer ; cependant, ils ont souvent du mal à s\'endormir ou à se concentrer sur quelque chose pendant de longues périodes.', 'https://static.wikia.nocookie.net/sims/images/c/ce/TS4_Trait_Nourrisson_Remuant.png/revision/latest?cb=20230319165512&path-prefix=fr', 'Remuant', 6, 'NOURRISSON', 'BASE'),
(150, 'Ces Sims aiment observer le monde, ont moins tendance à pleurer ou à se mettre en colère, et se lassent des activités moins facilement que les autres nourrissons ; par contre, ils sont moins enclins à explorer le monde spontanément.', 'https://static.wikia.nocookie.net/sims/images/4/4a/TS4_Trait_Nourrisson_Calme.png/revision/latest?cb=20230319165540&path-prefix=fr', 'Calme', 6, 'NOURRISSON', 'BASE'),
(151, 'Ces Sims aiment ce qui leur est familier mais mettent plus de temps à apprécier les expériences, endroits et Sims inédits.', 'https://static.wikia.nocookie.net/sims/images/f/f9/TS4_Trait_Nourrisson_Prudent.png/revision/latest?cb=20230319165625&path-prefix=fr', 'Prudent', 6, 'NOURRISSON', 'BASE'),
(152, 'Ces Sims ont des émotions puissantes et sont faciles à divertir, mais ils sont aussi plus difficiles à calmer lorsqu\'ils sont de mauvaise humeur.', 'https://static.wikia.nocookie.net/sims/images/0/07/TS4_Trait_Nourrisson_Intense.png/revision/latest?cb=20230319165656&path-prefix=fr', 'Intense', 6, 'NOURRISSON', 'BASE'),
(153, 'Ce Sim est mort lors de l\'explosion d\'une boule puante. Il n\'a pas supporté les émanations. Quelle manière malodorante de partir !', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.1e2c7eb90047b5a2be5ca50248ada6e5.png', 'Mort à cause d\'une boule puante', 24, 'ADULTE', 'FANTOME'),
(154, 'Ce Sim est mort à cause d\'une légende urbaine. Il n\'a pas cru aux rumeurs et a payé le prix fort pour cela. Tout le monde pense que ce Sim est mort de peur ; il est le seul à connaître la vérité.', 'https://luniversims.fr/uploads/monthly_2022_07/image.png.0e4bee5acf0e5cf7a7e606799da6c480.png', 'Mort à cause d\'une légende urbaine', 24, 'ADULTE', 'FANTOME'),
(156, 'Le trait Grande longévité permet aux Sims de vivre plus longtemps et d\'éviter les accidents.', 'https://static.wikia.nocookie.net/sims/images/9/98/Trait_gagn%C3%A9_Grande_long%C3%A9vit%C3%A9.png/revision/latest?cb=20220312153314&path-prefix=fr', 'Grande longévité', 6, 'ADULTE', 'ASPIRATION'),
(157, 'Les Sims nettoyeurs rapides nettoient tout plus vite !', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/speed-cleaner.png', 'Nettoyeur rapide', 6, 'ADULTE', 'BOUTIQUE'),
(158, 'Les Sims observateurs connaissent tout de suite les traits de ceux qu\'ils rencontrent.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/observant.png', 'Observateur', 6, 'ADULTE', 'BOUTIQUE'),
(159, 'Les piliers de salle de gym développent leur compétence Divertissement en faisant du sport et ont une bonne hygiène de vie.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/gym-rat.png', 'Pilier de salle de gym', 6, 'ADULTE', 'BOUTIQUE'),
(160, 'Les Sims toujours bienvenus se sentiront plus à l\'aise dans des résidences des autres Sims sans que cela ne gêne les hôtes !', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/always-welcome.png', 'Toujours bienvenu', 6, 'ADULTE', 'BOUTIQUE'),
(161, 'Les Sims étanches ne sont pas mouillés par la pluie.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/waterproof.png', 'Étanche', 6, 'ADULTE', 'BOUTIQUE'),
(162, 'Les fantastiques conteurs réussissent plus souvent à raconter des histoires en les rendant meilleures et plus intenses !', 'https://static.wikia.nocookie.net/sims/images/d/dd/Trait_TS4_Storyteller.png/revision/latest?cb=20180702143259', 'Fantastique conteur', 33, 'ADULTE', 'BOUTIQUE'),
(163, 'Les Sims habitués au froid ressentent les effets d\'un temps froid mais moins que les autres Sims.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/cold-acclimation.png', 'Habitué au froid', 9, 'ADULTE', 'BOUTIQUE'),
(164, 'Les Sims habitués à la chaleur ressentent les effets d\'un temps chaud mais moins que les autres Sims.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/heat-acclimation.png', 'Habitué à la chaleur', 9, 'ADULTE', 'BOUTIQUE'),
(165, 'Les Sims lecteurs rapides lisent les livres plus rapidement que les Sims normaux.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/speed-reader.png', 'Lecteur rapide', 6, 'ADULTE', 'BOUTIQUE'),
(166, 'Lorsque les enseignants atteignent le niveau 10 d\'une compétence, l\'interaction Enseigner devient disponible : ils peuvent alors aider les autres Sims à améliorer leurs compétences plus rapidement !', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/mentor.png', 'Mentor', 6, 'ADULTE', 'BOUTIQUE'),
(167, 'Les oiseaux de nuit ont des compétences supplémentaires la nuit.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/night-owl.png', 'Oiseau de nuit', 6, 'ADULTE', 'BOUTIQUE'),
(168, 'Les Sims du matin ont des compétences supplémentaires le matin.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/morning-sim.png', 'Sim du matin', 6, 'ADULTE', 'BOUTIQUE'),
(169, 'Les Sims chasseurs d\'orages adorent lorsque le temps est orageux et sont parfaitement à l\'aise dans ces conditions météorologiques terrifiantes.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/storm-chaser.png', 'Chasseur d\'orages', 9, 'ADULTE', 'BOUTIQUE'),
(170, 'Les Sims négociateurs vendent des objets qu\'ils ont fabriqués contre des simflouz !', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/marketable.png', 'Négociateur', 6, 'ADULTE', 'BOUTIQUE'),
(171, 'Ces Sims ont vécu assez de choses pour savoir ce qui compte vraiment, et aiment se rappeler des souvenirs et partager leur sagesse sur la vie, ce qui fait d\'eux d\'excellents mentors pour ceux qui les écoutent. Leurs années d\'expérience leur permettent d\'apprendre facilement et naturellement de nouvelles compétences, et leur intelligence émotionnelle réduit leur colère et leurs pensées désagréables.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316wise.png', 'Sage ', 27, 'ADULTE', 'BASE'),
(172, 'Ces Sims débordent d\'attention, d\'empathie et de patience, et apprécient particulièrement donner leur temps et leur argent pour aider les autres. Tout le monde les adore, mais leurs dons peuvent parfois être excessifs.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316generous.png', 'Généreux', 27, 'ADULTE', 'BASE'),
(173, 'Ces Sims adorent se sentir ancrés dans leur communauté et dans la culture tomaranaise. Rester en contact avec leurs proches et participer à des activités qui leur rappellent leur région d\'origine est important pour leur bonheur.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315child-of-the-village.png', 'Enfant du village', 27, 'ADULTE', 'BASE');
INSERT INTO `trait_de_caractere` (`id`, `description`, `img`, `nom`, `dlc_id`, `categorie_sim`, `type`) VALUES
(174, 'Les Sims fidèles accordent beaucoup d\'importance à leurs relations et font preuve d\'un engagement total, qu\'il s\'agisse d\'une amitié, d\'une histoire d\'amour ou même d\'une relation professionnelle ! Ils évitent de mentir et de tromper car la confiance de leurs proches est essentielle pour eux.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316loyal.png', 'Fidèle', 6, 'ADULTE', 'BASE'),
(175, 'Ces Sims ont un comportement décalé désagréable qui suscite souvent des réactions clivantes. Les Sims gênants peuvent parfois être socialement inconscients de ce qui se passe autour d\'eux, mais ils voient la vie de façon adorablement enthousiaste.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512315cringe.png', 'Gênant', 27, 'ADULTE', 'BASE'),
(176, 'Des Sims qui adorent raconter des potins, fouiner et espionner. Ils ont incroyablement peu de limites et ne comprennent pas vraiment la notion d\'espace personnel, mais ils découvriront des secrets par tous les moyens nécessaires.', 'https://tiermaker.com/images//media/template_images/2024/17822504/the-sims-4-traits-17822504/zzzzz-1757512316nosy.png', 'Indiscret', 27, 'ADULTE', 'BASE'),
(177, 'Toutes les demandes de services uniques sont gratuites.', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/free-services.png', 'Services gratuits', 6, 'ADULTE', 'BOUTIQUE'),
(178, 'Les pros des cuisinières et barbecues peuvent créer de la nourriture de qualité impeccable avec des cuisinières et des barbecues !', 'https://tiermaker.com/images/media/template_images/2024/262376/reward-store-traits-sims-4-262376/stove-and-grill-master.png', 'Pro des cuisinières et barbecues', 33, 'ADULTE', 'BOUTIQUE'),
(179, 'Ces Sims obtiennent une amélioration supplémentaire de leurs relations avec les loups-garous et les Sims non loups-garous.', 'https://static.wikia.nocookie.net/sims/images/4/40/Trait_TS4_Fanged_Friend.png/revision/latest?cb=20230728191159', 'Ami à crocs', 8, 'ADULTE', 'ASPIRATION'),
(180, 'Ces Sims détestent l\'idée de perdre le contrôle sur leur Fureur et en génèrent moins passivement au fil du temps.', 'https://static.wikia.nocookie.net/sims/images/a/a1/Trait_TS4_Refined_Lupine.png/revision/latest?cb=20230304085021', 'Loup raffiné', 8, 'ADULTE', 'ASPIRATION'),
(181, 'Les Sims transformés en loups-garous par des champions de la transformation ne réagiront pas de manière négative à leur transformation, et ils voudront rejoindre la meute du champion en question !', 'https://static.wikia.nocookie.net/sims/images/1/11/Trait_TS4_Chomp_Champion.png/revision/latest?cb=20230304085126', 'Champion de la transformation', 8, 'ADULTE', 'ASPIRATION'),
(182, 'Ces Sims conservent les avantages spéciaux du cycle de la lune et peuvent encore hurler comme au bon vieux temps.', 'https://static.wikia.nocookie.net/sims/images/c/c0/Trait_TS4_Lunar_Link.png/revision/latest?cb=20230304085303', 'Lien lunaire', 8, 'ADULTE', 'ASPIRATION'),
(183, 'Les Don Juan et les croqueuses de Sims ne rendent jamais les autres Sims jaloux, quoi qu\'ils fassent.', 'https://static.wikia.nocookie.net/sims/images/f/f2/Don_Juan.webp/revision/latest?cb=20220314095512&path-prefix=fr', 'Don Juan', 6, 'ADULTE', 'ASPIRATION'),
(184, 'Les Sims en couple ont avec leur conjoint des interactions spéciales qui leur permettent de surmonter les épreuves de la vie.', 'https://static.wikia.nocookie.net/sims/images/4/42/Trait_En_couple.webp/revision/latest?cb=20220314101026&path-prefix=fr', 'En couple', 6, 'ADULTE', 'ASPIRATION'),
(185, 'Les Sims naturalistes ne craignent pas le feu. Celui-ci ne les touche pas et ils peuvent l\'éteindre facilement.', 'https://static.wikia.nocookie.net/sims/images/1/17/Naturaliste.webp/revision/latest?cb=20220315144425&path-prefix=fr', 'Naturaliste', 6, 'ADULTE', 'ASPIRATION'),
(186, 'Les Sims ayant la sérénité du pêcheur ont l\'impression que tous leurs problèmes disparaissent lorsqu\'ils pêchent.', 'https://static.wikia.nocookie.net/sims/images/6/69/S%C3%A9r%C3%A9nit%C3%A9_du_p%C3%AAcheur.webp/revision/latest?cb=20220315145731&path-prefix=fr', 'Sérénité du pêcheur', 6, 'ADULTE', 'ASPIRATION'),
(187, 'Les experts peuvent vendre des objets tels que des métaux, des cristaux, des éléments et des fossiles au musée Simsonien pour gagner de l\'argent.', 'https://static.wikia.nocookie.net/sims/images/f/f9/Expert.webp/revision/latest?cb=20220315150345&path-prefix=fr', 'Expert', 6, 'ADULTE', 'ASPIRATION'),
(188, 'Les Sims qui parlent à la nature ont de meilleures relations avec les animaux, ce qui permet à leurs animaux de vivre plus longtemps et plus heureux. Les lapins et les oiseaux leur apportent plus de cadeaux. Ils peuvent interagir avec les plantes de façons uniques et obtiennent de meilleures récoltes. Ils bénéficient également de la livraison gratuite de leurs courses et, s\'ils habitent à Henford-on-Bagley, d\'une réduction sur leurs factures.', 'https://static.wikia.nocookie.net/sims/images/c/c6/Parle_%C3%A0_la_nature.webp/revision/latest?cb=20220314130430&path-prefix=fr', 'Parle à la nature', 23, 'ADULTE', 'ASPIRATION'),
(189, 'Les Sims survivalistes sont heureux lorsqu\'ils vivent à la dure en se nourrissant des produits de la nature. Dormir à la belle étoile ou utiliser du matériel de camping leur procure beaucoup de joie.', 'https://static.wikia.nocookie.net/sims/images/e/e0/Trait_Instinct_de_survie.webp/revision/latest?cb=20220312153055&path-prefix=fr', 'Survivaliste', 33, 'ADULTE', 'ASPIRATION'),
(190, 'En tant qu\'expert en potions, votre Sim échoue rarement lorsqu\'il utilise des potions sur lui-même.', 'https://static.wikia.nocookie.net/sims/images/1/11/Expert_en_potions.webp/revision/latest?cb=20220315143639&path-prefix=fr', 'Expert en potions', 121, 'ADULTE', 'ASPIRATION'),
(191, 'Les chasseurs de trésors obtiennent plus de trésors !', 'https://static.wikia.nocookie.net/sims/images/e/ee/Chasseur_de_tr%C3%A9sors.webp/revision/latest?cb=20220316162105&path-prefix=fr', 'Chasseur de trésors', 37, 'ADULTE', 'ASPIRATION'),
(192, 'Votre Sim est écouté dans le quartier, il peut même faire en sorte qu\'un Héros local soit acclamé ou conspué, c\'est tout dire...', 'https://static.wikia.nocookie.net/sims/images/3/3e/Sim_d%27influence1.webp/revision/latest?cb=20220318175500&path-prefix=fr', 'Sim d\'influence', 12, 'ADULTE', 'ASPIRATION'),
(193, 'Les Sims ayant ce trait de caractère trouvent leur équilibre dans la nature, et se divertissent davantage lors des rencontres avec l\'as du jardinage d\'Innisgreen.', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.3095abf618e4984b2a5cb4c1d0606fff.png', 'Pote ultime de la nature', 31, 'ADULTE', 'ASPIRATION'),
(194, 'Les confidents évitent les conversations ennuyeuses et apprennent plus rapidement à connaître les autres Sims.', 'https://static.wikia.nocookie.net/sims/images/b/b6/Confident.webp/revision/latest?cb=20220316164007&path-prefix=fr', 'Confident', 6, 'ADULTE', 'ASPIRATION'),
(195, 'Les Sims ayant une célébrité inébranlable sont des célébrités immortalisées comme telles qui ne verront jamais leur notoriété décliner. Ils sont si à l\'aise sous les feux des projecteurs qu\'ils ne réagissent jamais mal à la présence de pénibles paparazzis. Ils reçoivent également un point d\'avantage de notoriété supplémentaire.', 'https://static.wikia.nocookie.net/sims/images/7/7d/C%C3%A9l%C3%A9brit%C3%A9_in%C3%A9branlable.webp/revision/latest?cb=20220316164647&path-prefix=fr', 'Célébrité inébranlable', 19, 'ADULTE', 'ASPIRATION'),
(196, 'Vous réussissez toujours à prendre le contrôle d\'un groupe et votre Sim ne peut pas être destitué. De plus, votre Sim gagne des points de groupe beaucoup plus rapidement lors des réunions.', 'https://static.wikia.nocookie.net/sims/images/4/49/Dou%C3%A9_pour_diriger.webp/revision/latest?cb=20220316165529&path-prefix=fr', 'Doué pour diriger', 16, 'ADULTE', 'ASPIRATION'),
(197, 'Les Sims hilarants font toujours rire avec leurs blagues et en ont toujours quelques-unes en réserve.', 'https://static.wikia.nocookie.net/sims/images/8/86/Hilarant.webp/revision/latest?cb=20220316170115&path-prefix=fr', 'Hilarant', 6, 'ADULTE', 'ASPIRATION'),
(198, 'Tout le monde se souvient des Sims aimés ! Ils sont inoubliables.', 'https://static.wikia.nocookie.net/sims/images/c/c5/Aim%C3%A9.webp/revision/latest?cb=20220316170750&path-prefix=fr', 'Aimé', 6, 'ADULTE', 'ASPIRATION'),
(199, 'Les hôtes parfaits obtiennent un score plus élevé pour tous les événements sociaux qu\'ils organisent.', 'https://static.wikia.nocookie.net/sims/images/1/13/H%C3%B4te_parfait.webp/revision/latest?cb=20220316171400&path-prefix=fr', 'Hôte parfait', 6, 'ADULTE', 'ASPIRATION'),
(200, 'Ce vampire fait partie des bons vampires de ce monde. Les Sims sont donc plus enclins à accepter de lui donner leur plasma.', 'https://static.wikia.nocookie.net/sims/images/4/45/Humanit%C3%A9_regagn%C3%A9e.webp/revision/latest?cb=20220316171948&path-prefix=fr', 'Humanité regagnée', 36, 'ADULTE', 'ASPIRATION'),
(201, 'Les Sims ayant ce trait développent plus facilement leur charisme et peuvent également inspirer d\'autres Sims par leur simple présence.', 'https://static.wikia.nocookie.net/sims/images/1/13/Pr%C3%A9sence_h%C3%A9ro%C3%AFque.webp/revision/latest?cb=20220318165907&path-prefix=fr', 'Présence héroïque', 122, 'ADULTE', 'ASPIRATION'),
(202, 'Les Sims ayant ce trait ont un avantage pendant les combats et peuvent démontrer leur puissance, incitant ainsi les autres Sims à renoncer aux interactions Sociales hostiles avec eux. Ils ont également moins de chance de mourir de colère.', 'https://static.wikia.nocookie.net/sims/images/b/b9/Autorit%C3%A9_supr%C3%AAme.webp/revision/latest?cb=20220318170120&path-prefix=fr', 'Autorité suprême', 122, 'ADULTE', 'ASPIRATION'),
(203, 'Les Sims qui ont de la dextérité peuvent faire les poches d\'autres Sims et ne se feront jamais prendre lorsqu\'ils trichent au Sabacc.', 'https://static.wikia.nocookie.net/sims/images/3/3d/Dext%C3%A9rit%C3%A91.webp/revision/latest?cb=20220318170232&path-prefix=fr', 'Dextérité', 122, 'ADULTE', 'ASPIRATION'),
(204, 'Ces Sims créent une marque appréciée par tout le monde, ce qui augmente le succès de leurs petites entreprises. Toutes petite entreprise gérée par ces Sims obtiendra automatiquement plus d\'évaluations positives, et la clientèle partira avec un bonus de relation positive si elle a passé un bon moment dans l\'entreprise.', 'https://luniversims.fr/uploads/monthly_2025_02/image.png.2211fe9562cc7c5593fe8f1226ec27d0.png', 'Marque populaire', 30, 'ADULTE', 'ASPIRATION'),
(205, 'Ces Sims négocient de façon plus efficace un abandon de loyer, s\'entendent mieux avec leurs voisins, n\'ont jamais de biens saisis par leur propriétaire et organisent de meilleurs événements.', 'https://static.wikia.nocookie.net/sims/images/7/70/Trait_TS4_Neighborly.png/revision/latest?cb=20231211200736', 'Locataire sympathique', 27, 'ADULTE', 'ASPIRATION'),
(206, 'Quand ce Sim maîtrisera le bien-être cela lui permettra d\'avoir un éclat apaisant ! Utilisez cette nouvelle aptitude pour calmer des Sims à proximité, et... pour être magnifique à leurs yeux !', 'https://static.wikia.nocookie.net/sims/images/9/98/Aura_apaisante.webp/revision/latest?cb=20220317093546&path-prefix=fr', 'Aura apaisante', 34, 'ADULTE', 'ASPIRATION'),
(207, 'Tout est plus clair pour ce Sim ! Il pourra désormais avoir un bref répit de la dure réalité et recontextualiser les choses. Et se dire que tout cela est insignifiant... mais d\'une manière positive', 'https://static.wikia.nocookie.net/sims/images/1/1a/Perspective_claire.webp/revision/latest?cb=20220317092906&path-prefix=fr', 'Perspective claire', 34, 'ADULTE', 'ASPIRATION'),
(208, 'Ce Sim deviendra l\'expert en soins pour soi et développera une expertise pour tout ce qui concerne le bien-être. Les clients donneront désormais beaucoup plus d\'argent pour ses services !', 'https://static.wikia.nocookie.net/sims/images/f/f1/Expertise_en_soins_pour_soi.webp/revision/latest?cb=20220317094142&path-prefix=fr', 'Expertise en soins pour soi', 34, 'ADULTE', 'ASPIRATION'),
(209, 'Les Sims doués socialement développent les compétences sociales adultes plus rapidement.', 'https://static.wikia.nocookie.net/sims/images/8/8f/Dou%C3%A9_socialement.webp/revision/latest?cb=20220317112402&path-prefix=fr', 'Doué socialement', 6, 'ENFANT', 'ASPIRATION'),
(210, 'Les Sims au physique avantageux développent les compétences physiques adultes plus rapidement.', 'https://static.wikia.nocookie.net/sims/images/c/cb/Physique_avantageux.webp/revision/latest?cb=20220317111645&path-prefix=fr', 'Physique avantageux', 6, 'ENFANT', 'ASPIRATION'),
(211, 'Les Sims doués mentalement développent des facultés mentales d\'adultes plus vite.', 'https://static.wikia.nocookie.net/sims/images/5/5d/Dou%C3%A9_mentalement.webp/revision/latest?cb=20220317111012&path-prefix=fr', 'Doué mentalement', 6, 'ENFANT', 'ASPIRATION'),
(212, 'Les génies créatifs développent la compétence Créativité plus vite.', 'https://static.wikia.nocookie.net/sims/images/6/60/G%C3%A9nie_cr%C3%A9atif.webp/revision/latest?cb=20220317110221&path-prefix=fr', 'Génie créatif', 6, 'ENFANT', 'ASPIRATION'),
(213, 'Les Sims expressionnistes capturent l\'essence des sentiments et peuvent créer des œuvres d\'art extrêmement expressives, quelle que soit leur humeur !', 'https://static.wikia.nocookie.net/sims/images/0/05/Trait_gagn%C3%A9_Expressionniste.webp/revision/latest?cb=20220312163436&path-prefix=fr', 'Expressionniste', 6, 'ADULTE', 'ASPIRATION'),
(214, 'Ces Sims sortiront toujours indemnes des attaques d\'animaux sauvages, réussiront à éviter les blessures plus souvent que les autres Sims lorsqu\'ils feront du ski, du snowboard et de l\'escalade, et auront une résistance naturelle  aux météos peu clémentes.', 'https://static.wikia.nocookie.net/sims/images/1/1f/Instinct_de_survie.webp/revision/latest?cb=20220312181318&path-prefix=fr', 'Instinct de survie', 22, 'ADULTE', 'ASPIRATION'),
(215, 'Ces Sims dressent plus rapidement les chevaux pour leur faire acquérir des compétences, inspirent la confiance en eux et rendent confiant leur cheval lorsqu\'ils les montent et les dressent, et passent très rarement un mauvais moment sur un cheval. En fait, ils sont si doués avec les chevaux que les chevaux s\'amusent même d\'avantage quand ces Sims les montent. Enfin, ils peuvent également donner des conseils pour les concours aux Sims qui débutent en équitation.', 'https://static.wikia.nocookie.net/sims/images/8/85/Dresseur_de_champions.webp/revision/latest?cb=20250426131250&path-prefix=fr', 'Dresseur de champions', 26, 'ADULTE', 'ASPIRATION'),
(216, 'Les Sims qui murmure à l\'oreille des animaux ont plus de facilité à dresser et discipliner les animaux, et les relations avec eux progressent plus facilement.', 'https://static.wikia.nocookie.net/sims/images/1/1e/Trait_TS4_Animal_Whisperer.png/revision/latest?cb=20180216201830', 'Celui qui murmure à l\'oreille des animaux', 18, 'ADULTE', 'ASPIRATION'),
(217, 'Les Sims poétiques capturent l\'essence de la vie dans un livre et s\'en servent pour ramener ceux qu\'ils ont perdus.', 'https://static.wikia.nocookie.net/sims/images/2/2a/Trait_gagn%C3%A9_Po%C3%A9tique.webp/revision/latest?cb=20220312164410&path-prefix=fr', 'Poétique', 6, 'ADULTE', 'ASPIRATION'),
(218, 'Les musiciens envoûtants connaissent un véritable arsenal de morceaux qui ont un grand pouvoir sur les autres Sims.', 'https://static.wikia.nocookie.net/sims/images/1/17/Trait_gagn%C3%A9_Musicien_envo%C3%BBtant.webp/revision/latest?cb=20220312165543&path-prefix=fr', 'Musicien envoûtant', 6, 'ADULTE', 'ASPIRATION'),
(219, 'Les acteurs de renommée mondiale ne ratent jamais une scène... ou si peu que personne ne s\'en rend compte !', 'https://static.wikia.nocookie.net/sims/images/f/f1/Trait_gagn%C3%A9_Acteur_de_renomm%C3%A9e_mondiale.webp/revision/latest?cb=20220312162004&path-prefix=fr', 'Acteur de renommée mondiale', 19, 'ADULTE', 'ASPIRATION'),
(220, 'Les Sims ayant ce trait obtiennent des avantages améliorés lorsqu\'ils enseignent le tricot à d\'autres Sims. Ils sont également immunisés contre l\'infâme magie de la Malédiction du pull, et peuvent en libérer les Sims qui sont victimes de ses terribles effets. Enfin, ces Sims ont la possibilité de tricoter des objets uniques, comme un compagnon très spécial venant d\'un monde étrange, ou encore Le Pull interdit qui, franchement, est interdit pour une bonne raison...', 'https://static.wikia.nocookie.net/sims/images/5/5a/Trait_TS4_Sacred_Knitting_Knowledge.png/revision/latest?cb=20200728182739', 'Connaissance sacrée du tricot', 14, 'ADULTE', 'ASPIRATION'),
(221, 'Les créateurs magistraux ont appris toutes les astuces nécessaires pour fabriquer des objets à moindre coût.', 'https://static.wikia.nocookie.net/sims/images/5/50/Trait_gagn%C3%A9_Cr%C3%A9ateur_%C3%A9conome.webp/revision/latest?cb=20220312171754&path-prefix=fr', 'Créateur économe', 12, 'ADULTE', 'ASPIRATION'),
(222, 'Les Sims manipulateurs savent exactement ce qu\'il faut dire pour susciter la colère, la tristesse et la jalousie chez leur adversaires.', 'https://static.wikia.nocookie.net/sims/images/3/3f/Trait_gagn%C3%A9_Manipulateur.webp/revision/latest?cb=20220312181938&path-prefix=fr', 'Manipulateur', 6, 'ADULTE', 'ASPIRATION'),
(223, 'Les persécuteurs peuvent saboter presque tout, qu\'il s\'agisse d\'un objet ou des efforts d\'un autre Sim.', 'https://static.wikia.nocookie.net/sims/images/e/ee/Pers%C3%A9cuteur.webp/revision/latest?cb=20220312182755&path-prefix=fr', 'Persécuteur', 6, 'ADULTE', 'ASPIRATION'),
(224, 'Si vous pouviez voir le cœur de ce Sim, vous reculeriez peut-être de dégoût. Mais ce Sim ne vous laisserait jamais le voir, et cela lui convient très bien. Ce Sim satisfait davantage son besoin Social lorsqu\'il effectue des interactions sociales méchantes et malicieuses, et se débarrasse des humeurs Triste et Embarrassé beaucoup plus rapidement que les autres Sims.', 'https://static.wikia.nocookie.net/sims/images/1/13/C%C5%93ur_tordu.webp/revision/latest?cb=20220312183913&path-prefix=fr', 'Cœur tordu', 6, 'ADULTE', 'ASPIRATION'),
(225, 'Les kleptomanes améliorés ont moins de chances de se faire prendre sur le fait en volant des choses sous les yeux des autres.', 'https://static.wikia.nocookie.net/sims/images/1/1f/Kleptomane.webp/revision/latest?cb=20220317142241&path-prefix=fr', 'Kleptomanes améliorés', 6, 'ADULTE', 'ASPIRATION'),
(226, 'Les Sims qui ont la clairvoyance du tigre fouillent les endroits et trient le courrier indésirable de manière efficace. Cerise sur le gâteau, ces Sims disposent de l\'alibi parfait si on les surprend en train d\'entrer chez quelqu\'un par effraction : un badge d\'InspecTigre !', 'https://static.wikia.nocookie.net/sims/images/e/e8/Clairvoyance_du_tigre.webp/revision/latest?cb=20250426173431&path-prefix=fr', 'Clairvoyance du tigre', 27, 'ADULTE', 'ASPIRATION'),
(227, 'Si vous vivez par procuration, les compétences de vos enfants profitent aux vôtres !', 'https://static.wikia.nocookie.net/sims/images/f/fe/Vit_par_procuration.webp/revision/latest?cb=20220313151851&path-prefix=fr', 'Vit par procuration', 6, 'ADULTE', 'ASPIRATION'),
(228, 'Les Patriarches améliorent les compétences de leurs enfants lorsque ceux-ci se trouvent à proximité.', 'https://static.wikia.nocookie.net/sims/images/c/cc/Patriarche.webp/revision/latest?cb=20220313152748&path-prefix=fr', 'Patriarche', 6, 'ADULTE', 'ASPIRATION'),
(229, 'Ce Sim contrôle tous les pouvoirs de l\'esprit et a créé son héritage vampirique. Il a désormais le pouvoir de donner des ordres à ses descendants vampires de manière beaucoup plus efficace.', 'https://static.wikia.nocookie.net/sims/images/c/cc/Patriarche.webp/revision/latest?cb=20220313152748&path-prefix=fr', 'Je suis le maître', 36, 'ADULTE', 'ASPIRATION'),
(230, 'Les modèles procurent un gain supplémentaire de qualités personnelles lorsqu\'ils sont à proximité de bambins, d\'enfants et d\'adolescents.', 'https://static.wikia.nocookie.net/sims/images/e/e1/Mod%C3%A8le.webp/revision/latest?cb=20220313150735&path-prefix=fr', 'Modèle', 10, 'ADULTE', 'ASPIRATION'),
(231, 'Les chefs frais sont les meilleurs cuisiniers et leurs plats ne se gâtent jamais !', 'https://static.wikia.nocookie.net/sims/images/b/bf/Chef_frais.webp/revision/latest?cb=20220313154400&path-prefix=fr', 'Chef frais', 6, 'ADULTE', 'ASPIRATION'),
(232, 'Les Sims fondus de fromage ont suffisamment consacré leur amour et leur corps aux sandwichs au fromage fondu pour devenir de véritables Gourous du gruyère. Ils peuvent faire apparaître des sandwichs au fromage fondu et peindre des toiles représentant des sandwichs au fromage fondu.', 'https://static.wikia.nocookie.net/sims/images/b/bf/Chef_frais.webp/revision/latest?cb=20220313154400&path-prefix=fr', 'Fondu de fromage', 6, 'ADULTE', 'ASPIRATION'),
(233, 'Les pros des potions peuvent préparer des boissons puissantes qui influencent les émotions de ceux qui les boivent.', 'https://static.wikia.nocookie.net/sims/images/c/c6/Pro_des_potions.webp/revision/latest?cb=20220313155215&path-prefix=fr', 'Pro des potions', 6, 'ADULTE', 'ASPIRATION'),
(234, 'Ces Sims peuvent fabriquer du nectar pré-vieilli, ont une vessie d\'acier quand il s\'agit de boire du nectar, et ont leur humeur actuelle moins influencée par leurs émotions négatives.', 'https://static.wikia.nocookie.net/sims/images/1/19/Connaisseur_en_nectar.webp/revision/latest?cb=20250426182249&path-prefix=fr', 'Connaisseur en nectar', 26, 'ADULTE', 'ASPIRATION'),
(235, 'Les Sims ayant ce trait de caractère obtiennent des portions supplémentaires de toute recette cuisinée avec des ingrédients préparés.', 'https://static.wikia.nocookie.net/sims/images/8/84/Efficace_en_cuisine.webp/revision/latest?cb=20250426182702&path-prefix=fr', 'Efficace en cuisine', 140, 'ADULTE', 'ASPIRATION'),
(236, 'Les Sims économe bénéficient d\'une réduction de 10% sur tous leurs achat dans le mode Construction chaque semaine. Cette réduction sera automatiquement appliquée aux fonds du foyer.', 'https://static.wikia.nocookie.net/sims/images/6/67/Econome.webp/revision/latest?cb=20220313161518&path-prefix=fr', 'Économe', 6, 'ADULTE', 'ASPIRATION'),
(237, 'Les Sims astucieux reçoivent un versement chaque semaine en fonction des fonds de leur foyer.', 'https://static.wikia.nocookie.net/sims/images/6/60/Astucieux.webp/revision/latest?cb=20220313160359&path-prefix=fr', 'Astucieux', 6, 'ADULTE', 'ASPIRATION'),
(238, 'Les Sims ayant ce trait de caractère résolvent les problèmes de façon plus efficace lors des évènements des locataires type Urgence et Entretien, nouent des liens plus forts avec les locataires, et obtiennent de meilleures évaluations pour les locations résidentielles en leur possession.', 'https://static.wikia.nocookie.net/sims/images/c/c4/Pro_de_la_gestion_de_logements.webp/revision/latest?cb=20250427052944&path-prefix=fr', 'Pro de la gestion de logements', 27, 'ADULTE', 'ASPIRATION'),
(239, 'Les Sims ayant ce trait de caractère peuvent définir des marges plus élevées et sont plus efficaces pour convaincre les clients d\'acheter quelque chose à leur stand de nourriture ou leur table de vente.', 'https://static.wikia.nocookie.net/sims/images/8/8f/Sp%C3%A9cialiste_des_stands.webp/revision/latest?cb=20250427053701&path-prefix=fr', 'Spécialiste des stands', 140, 'ADULTE', 'ASPIRATION'),
(240, 'Les Sims bricoleurs peuvent réparer et améliorer instantanément n\'importe quel objet.', 'https://static.wikia.nocookie.net/sims/images/f/fc/Bricoleur.webp/revision/latest?cb=20250408154507&path-prefix=fr', 'Bricoleur', 6, 'ADULTE', 'ASPIRATION'),
(241, 'Les maîtres du Web profitent au maximum de leurs ordinateurs en débloquant des moyens extrêmement pratiques de les utiliser.', 'https://static.wikia.nocookie.net/sims/images/0/02/Pro_du_Web.webp/revision/latest?cb=20220313165156&path-prefix=fr', 'Pro du Web', 6, 'ADULTE', 'ASPIRATION'),
(242, 'Les Sims professoraux peuvent écrire un manuel sur n\'importe quel domaine dans lequel ils sont doués.', 'https://static.wikia.nocookie.net/sims/images/8/8b/Professorale.webp/revision/latest?cb=20220313163456&path-prefix=fr', 'Professoral', 6, 'ADULTE', 'ASPIRATION'),
(243, 'Véritable maître du vampirisme, ce Sim peut donner des ordres irrésistibles à tous les descendants vampires.', 'https://static.wikia.nocookie.net/sims/images/2/26/Ambitieux.webp/revision/latest?cb=20220313162411&path-prefix=fr', 'Véritable maître', 36, 'ADULTE', 'ASPIRATION'),
(244, 'Les Sims mécènes de musée adorent les musées.', 'https://static.wikia.nocookie.net/sims/images/6/68/M%C3%A9c%C3%A8ne_de_mus%C3%A9e.webp/revision/latest?cb=20220313164130&path-prefix=fr', 'Mécène de musée', 37, 'ADULTE', 'ASPIRATION'),
(245, 'En tant que jeteur de sorts délicat, ce Sim génère beaucoup moins d\'énergie lorsqu\'elle jette des sorts.', 'https://static.wikia.nocookie.net/sims/images/2/26/Jeteur_de_sorts_d%C3%A9licat.webp/revision/latest?cb=20220313170520&path-prefix=fr', 'Jeteur de sorts délicat', 121, 'ADULTE', 'ASPIRATION'),
(246, 'Ce Sim a prouvé qu\'il avait les capacités pour exceller à l\'université. Il a également appris beaucoup de choses, ce qui lui permet de développer davantage ses compétences lorsqu\'il utilise la Machine d\'archivage et de recherches électromagnétique et de gagner plus d\'argent lorsqu\'il publie des articles ou contribue à la base de données.', 'https://static.wikia.nocookie.net/sims/images/9/93/Etudes_sup%C3%A9rieures.webp/revision/latest?cb=20220313172921&path-prefix=fr', 'Études supérieures', 21, 'ADULTE', 'ASPIRATION'),
(247, 'Les Sims proches des fantômes ont accès à des interactions spéciales pour parler de leurs étranges découvertes et de leurs romans. Ces Sims n\'éprouvent aucune difficulté à se lier d\'amitié (et plus si affinités) avec des fantômes. Rien ne leur fait plus plaisir que de rencontrer des fantômes de toutes sortes, la Faucheuse et même des corbeaux !', 'https://static.wikia.nocookie.net/sims/images/3/3d/Proche_des_fant%C3%B4mes.webp/revision/latest?cb=20250427083755&path-prefix=fr', 'Proche des fantômes', 29, 'ADULTE', 'ASPIRATION'),
(248, 'Ces Sims maîtrisent l\'art de guérir et améliorent leur équilibre en fabriquant des élixirs, en guérissant des syndromes ou en aidant les autres dans la carrière Herbaliste.', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.2473bd6798332ab50a012be1b0f31271.png', 'Praticien équilibré', 31, 'ADULTE', 'ASPIRATION'),
(249, 'Ce Sim peut faire un discours motivant qui lui procurera ainsi qu\'aux Sims qui l\'écoutent un bonus de gain de compétence, une amélioration du bonheur et une plus grande chance de découvrir un avantage de compétence.', 'https://static.wikia.nocookie.net/sims/images/b/b9/Pr%C3%A9sence_motivante.webp/revision/latest?cb=20250427083943&path-prefix=fr', 'Présence motivante', 30, 'ADULTE', 'ASPIRATION'),
(250, 'Les Sims ayant ce trait obtiennent un énorme rabais sur tous leurs achats aux stands du marché.', 'https://static.wikia.nocookie.net/sims/images/1/1d/A_la_page.webp/revision/latest?cb=20220313192501&path-prefix=fr', 'À la page', 17, 'ADULTE', 'ASPIRATION'),
(251, 'Les Sims décontractés ne sont jamais tendus.', 'https://static.wikia.nocookie.net/sims/images/9/9c/Vie_%C3%A0_la_plage.webp/revision/latest?cb=20220313193132&path-prefix=fr', 'Décontracté', 20, 'ADULTE', 'ASPIRATION'),
(252, 'Les Sims ayant ce trait de caractère préparent mieux la cuisine tomaranaise, trouvent plus de pompons, s\'entendent mieux avec les Sims ayant le trait de caractère Enfant du village, et obtiennent de meilleurs résultats en explorant le sanctuaire des tigres de Sulea et le grotte de la Crique de Parmabarbe', 'https://static.wikia.nocookie.net/sims/images/1/1b/Trait_TS4_Tomarang_Expert.png/revision/latest?cb=20231211202332', 'Expert de Tomarang', 27, 'ADULTE', 'ASPIRATION'),
(253, 'Ces Sims n\'obtiennent pas d\'états d\'esprit négatifs ou ne voient pas baisser le niveau de leur besoin Divertissement lorsqu\'ils font du ménage. Ils nettoient plus rapidement et ont plus de chance de devenir concentrés en faisant du ménage. Pour une efficacité maximale, les Sims rapides et efficaces peuvent utiliser les interactions \"Nettoyer intensément\" et \"Passer l\'aspirateur intensément\".', 'https://static.wikia.nocookie.net/sims/images/7/75/Rapide_et_efficace.webp/revision/latest?cb=20220313190717&path-prefix=fr', 'Rapide et efficace', 142, 'ADULTE', 'ASPIRATION'),
(254, 'Ce Sim ne reçoit plus d\'états d\'esprit négatifs lorsqu\'il vit dans des environnements poussiéreux ou en désordre. Il déteste faire le ménage et adore la saleté, et obtient l\'état d\'esprit Heureux dans les maisons sales ou poussiéreuses. De plus, il obtient la possibilité de nouer des amitiés avec les Monstres de crasse !\n', 'https://static.wikia.nocookie.net/sims/images/a/a2/Trait_TS4_Filth_Dweller.png/revision/latest?cb=20230728193227', 'Adepte de la saleté', 142, 'ADULTE', 'ASPIRATION'),
(255, 'Ces Sims sont plus doués pour discuter avec d\'autres Sims lors des événements sociaux et aiment commander de la nourriture aux stands des marchés. Ils peuvent également \"négocier une réduction\" aux stands des marchés, ce qui leur donne un avantage sur les autres techniques de négociation.', 'https://static.wikia.nocookie.net/sims/images/d/db/Voyageur_exp%C3%A9riment%C3%A9.webp/revision/latest?cb=20220313180200&path-prefix=fr', 'Voyageur expérimenté', 22, 'ADULTE', 'ASPIRATION'),
(256, 'En tant qu\'héros de Strangerville, vous recevrez du courrier de fan et pourrez raconter comment vous avez vaincu la source de l\'infection.', 'https://static.wikia.nocookie.net/sims/images/8/83/H%C3%A9ros_de_StrangerVille.webp/revision/latest?cb=20220313174959&path-prefix=fr', 'Héros de Strangerville', 38, 'ADULTE', 'ASPIRATION'),
(257, 'Ces Sims foncent tête baissée dans leur parcours de fée et prennent de l\'avance dans la progression dans les rangs de fée, qui les divertit aussi davantage.', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.768c9eff93287b75f059024cfa93a1f5.png', 'Au cœur d\'Everdew', 31, 'ADULTE', 'ASPIRATION'),
(258, 'Ces fées adorent semer la pagaille dans la vie d\'autres Sims, et améliorent leur équilibre et le niveau de leur besoin Divertissement lorsqu\'elles utilisent leurs facultés de fée pour nuire à d\'autres Sims.', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.95a20d3d1673c6c332e067cac9820c42.png', 'Délicieusement discordant', 31, 'ADULTE', 'ASPIRATION'),
(259, 'Les fées harmonieuses savent se divertir : en partageant le parcours de fée avec d\'autres Sims, et en donnant un coup de main aux Sims et aux plantes !', 'https://luniversims.fr/uploads/monthly_2025_06/image.png.72b40eee23fd0bdb3f08da0d7e5a3eb8.png', 'Heureux d\'être harmonieux', 31, 'ADULTE', 'ASPIRATION'),
(260, 'Les Sims en harmonie connaissent bien les mystères des cristaux et peuvent ainsi absorber l\'énergie des cristaux chargés. Les bijoux que ces Sims portent restent chargés plus longtemps.', 'https://static.wikia.nocookie.net/sims/images/9/97/Trait_TS4_Attuned.png/revision/latest?cb=20240229202529', 'En harmonie', 59, 'ADULTE', 'ASPIRATION'),
(261, 'Les romantiques chevronnés voient leurs relations amoureuses avec les autres Sims évoluer plus rapidement. Ils se remettent aussi plus vite d’un embarras car ils savent qu’il n’y a pas de gêne à avoir en matière d’amour.', 'https://static.wikia.nocookie.net/sims/images/6/66/Trait_TS4_Romantic_Explorer.png/revision/latest?cb=20240725205119', 'Romantique chevronné', 28, 'ADULTE', 'ASPIRATION'),
(262, 'Les Sims qui adorent l\'affection ont une satisfaction amoureuse qui diminue plus lentement dans leurs relations avec d\'autres Sims.', 'https://static.wikia.nocookie.net/sims/images/1/1c/Trait_TS4_Affection_Aficionado.png/revision/latest?cb=20240725202746', 'Adore l\'affection', 28, 'ADULTE', 'ASPIRATION'),
(263, 'Les Sims intrépides mordent la vie à pleines dents, et la Faucheuse a un faible pour les plaidoyers intrépides quand il est question de vie ou de mort. S\'amuser en prenant des risques a clairement ses avantages.', 'https://static.wikia.nocookie.net/sims/images/b/b3/Trait_TS4_Dauntless.png/revision/latest?cb=20230304084834', 'Intrépide', 24, 'ADO', 'ASPIRATION'),
(264, 'Les Sims iconiques sont ceux que tout le monde à envie de suivre. Ils ont gagné l\'admiration de leurs pairs, et peuvent désormais jeter leur dévolu sur tout ce qu\'il y a sur Internet.', 'https://static.wikia.nocookie.net/sims/images/6/6f/Trait_TS4_Iconic.png/revision/latest?cb=20230304084843', 'Iconique', 24, 'ADO', 'ASPIRATION'),
(265, 'Les Sims de haute volée ont le potentiel pour avoir le plus de succès, surtout dans les affaires.', 'https://static.wikia.nocookie.net/sims/images/f/fb/Trait_TS4_Highflier.png/revision/latest?cb=20230304084815', 'Sim de haute volée', 24, 'ADO', 'ASPIRATION'),
(266, 'Les Sims impassibles se remettent rapidement de tout. En faire des tonnes peut rendre les relations difficiles. Rien ne définit mieux l\'insouciance que le lâcher prise et passer à autre chose.', 'https://static.wikia.nocookie.net/sims/images/3/3e/Trait_TS4_Untroubled.png/revision/latest?cb=20230304084921', 'Impassible', 24, 'ADO', 'ASPIRATION'),
(267, 'Votre Sim est maintenant la star du quartier, c\'est officiel ! Personne ne se sociabilise aussi facilement ni n\'a plus de talent pour écraser les autres dans les compétitions. En effet, ce trait lui confère un avantage pendant les parties de jeux vidéo en multijoueur, ou d\'autres jeux comme cache-cache ou pierre-papier-ciseaux. Son identité tout entière se base sur ce facteur cool et les autres enfants rêvent d\'être aussi la star du quartier.', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.765285c769282c3059b3c01e2f5b65aa.png', 'Star du quartier', 32, 'ENFANT', 'ASPIRATION'),
(268, 'Ces Sims peuvent discuter avec les papillons ainsi qu\'avec les poissons dans des bocaux ou des aquariums. Il leur est également possible de s\'enthousiasmer à propos des bestioles auprès des autres Sims. Leur connaissance de la parade nuptiale mystique des papillons leur permet d\'effectuer des interactions romantiques uniques sur le thème des papillons avec d\'autres Sims.', 'https://luniversims.fr/uploads/monthly_2025_09/image.png.5b11732d2206716ceeb0f251fae1d35b.png', 'Fan de bestioles', 32, 'ADULTE', 'ASPIRATION'),
(269, 'Ces Sims améliorent plus rapidement leurs compétences malice.', 'https://static.wikia.nocookie.net/sims/images/7/7d/Trait_TS4_Merciless.png/revision/latest?cb=20260309144325', 'Sans pitié', 6, 'ADULTE', 'ASPIRATION'),
(270, 'Ces Sims adorent s\'améliorer et aider les autres à faire de même. Ils améliorent plus rapidement leurs relations et leurs compétences lorsqu\'ils s\'entrainent avec des amis !', 'https://static.wikia.nocookie.net/sims/images/a/a1/Trait_TS4_Pack_Animal.png/revision/latest?cb=20230720210732', 'Animal de meute', 119, 'ENFANT', 'ASPIRATION'),
(271, 'Ces Sims se sont concentrés sur une combinaison de compétences mentales et créatives pendant leur enfance. Grâce à leurs efforts, ils peuvent désormais peindre, écrire, programmer et composer des morceaux plus rapidement. Toute panne d\'inspiration disparaît aussi beaucoup plus vite !', 'https://static.wikia.nocookie.net/sims/images/a/ad/Trait_TS4_Idea_Person.png/revision/latest?cb=20230720210729', 'Inventif', 119, 'ENFANT', 'ASPIRATION'),
(272, 'Ces Sims ont appris à discipliner leur corps et leur esprit. Leurs états d\'esprit Concentré et Confiant dureront plus longtemps.', 'https://static.wikia.nocookie.net/sims/images/1/11/Trait_TS4_Headstrong.png/revision/latest?cb=20230720210728', 'Déterminé', 119, 'ENFANT', 'ASPIRATION'),
(273, 'Ces Sims font partie des meilleurs organisateurs d\'événements. Pendant les fêtes, leurs interactions sociales amicales et drôles seront toujours couronnées de succès.', 'https://static.wikia.nocookie.net/sims/images/b/bb/Trait_TS4_Practiced_Host.png/revision/latest?cb=20230720210635', 'Hôte accompli', 119, 'ENFANT', 'ASPIRATION'),
(274, 'Avec une réputation blindée, ce Sim n\'a plus à se soucier de subir du chantage de la part des autres Sims ! Toutefois, s\'il se retrouve au cœur d\'un scandale, ce sera bien plus facile de s\'excuser ou de nier en bloc. Par ailleurs, s\'il tente de faire chanter les Sims, leur coopération sera plus facilement assurée.', 'https://luniversims.fr/uploads/monthly_2026_01/image.png.351f5a5408993a53833928d00094f389.png', 'Réputation blindée', 117, 'ADULTE', 'ASPIRATION'),
(275, 'La curiosité est un vilain défaut ! Cette personne a péri en essayant de bricoler une pendule à coucou agaçante.', 'https://luniversims.fr/uploads/monthly_2026_01/image.png.e506cd484cbeab23739ec34f0993d061.png', 'Mort à cause d\'un dysfonctionnement du coucou', 117, 'ADULTE', 'FANTOME'),
(276, 'Ces chiens sont vraiment énergiques. Ils adorent courir et apprécient d\'être souvent promenés.', 'https://static.wikia.nocookie.net/sims/images/a/aa/Actif_%28chien%29.webp/revision/latest?cb=20220317164020&path-prefix=fr', 'Actif', 18, 'CHIEN', 'BASE'),
(277, 'Ces chiens sont plus hostiles lorsqu\'ils saluent les autres chiens et peuvent même les attaquer s\'ils n\'ont pas été correctement dressés.', 'https://static.wikia.nocookie.net/sims/images/3/3b/Agressif.webp/revision/latest?cb=20220317164111&path-prefix=fr', 'Agressif', 18, 'CHIEN', 'BASE'),
(278, 'Ces animaux sont généralement amicaux avec les Sims et sont ravis des les saluer.', 'https://static.wikia.nocookie.net/sims/images/7/7e/Amical.webp/revision/latest?cb=20220317164210&path-prefix=fr', 'Amical', 18, 'CHIEN', 'BASE'),
(279, 'Ces chiens quittent parfois la maison pour vivre des aventures en solo, ils sont également heureux de partir à l\'aventure avec leur maître.', 'https://static.wikia.nocookie.net/sims/images/0/01/Aventureux_%28chien%29.webp/revision/latest?cb=20220317164303&path-prefix=fr', 'Aventureux', 18, 'CHIEN', 'BASE'),
(280, 'Ces chiens aiment hurler de temps en temps et peuvent même chanter sur commande.', 'https://static.wikia.nocookie.net/sims/images/d/d0/Bruyant.webp/revision/latest?cb=20220317164421&path-prefix=fr', 'Bruyant', 18, 'CHIEN', 'BASE'),
(281, 'Ces chiens sont des chasseurs nés. Envoyez-les parcourir le monde et ils chasseront et creuseront le sol pour trouver des objets.', 'https://static.wikia.nocookie.net/sims/images/6/65/Chasseur.webp/revision/latest?cb=20220317164514&path-prefix=fr', 'Chasseur', 18, 'CHIEN', 'BASE'),
(282, 'Ces chiens sont naturellement plus curieux et aiment chercher différents objets dans la maison.', 'https://static.wikia.nocookie.net/sims/images/0/05/D%C3%A9tective.webp/revision/latest?cb=20220317164557&path-prefix=fr', 'Détective', 18, 'CHIEN', 'BASE'),
(283, 'Ces chiens mijotent toujours quelque chose ! Ils se comportent souvent mal et peuvent même être incités à le faire.', 'https://static.wikia.nocookie.net/sims/images/8/83/Fauteur_de_troubles.webp/revision/latest?cb=20220317164710&path-prefix=fr', 'Fauteur de troubles', 18, 'CHIEN', 'BASE'),
(284, 'Ces chiens ont envie d\'être proches de leurs maîtres et adorent être caressés. Ils aiment suivre leurs maîtres partout.', 'https://static.wikia.nocookie.net/sims/images/8/87/Fid%C3%A8le.webp/revision/latest?cb=20220317165239&path-prefix=fr', 'Fidèle', 18, 'CHIEN', 'BASE'),
(285, 'Ces animaux mangent nettement plus souvent que les autres et beaucoup plus salement.', 'https://static.wikia.nocookie.net/sims/images/b/bb/Glouton_%28chien%29.webp/revision/latest?cb=20220317165518&path-prefix=fr', 'Glouton', 18, 'CHIEN', 'BASE'),
(286, 'Ces chiens ont généralement moins besoin d\'affection constante et peuvent même se promener tout seuls.', 'https://static.wikia.nocookie.net/sims/images/d/dc/Ind%C3%A9pendant_%28chien%29.webp/revision/latest?cb=20220317165613&path-prefix=fr', 'Indépendant', 18, 'CHIEN', 'BASE'),
(287, 'Ces chiens intelligents sont plus faciles à dresser et apprennent vite les tours. Ils peuvent même comprendre le simlish.', 'https://static.wikia.nocookie.net/sims/images/5/5b/Intelligent.webp/revision/latest?cb=20220317165702&path-prefix=fr', 'Intelligent', 18, 'CHIEN', 'BASE'),
(288, 'Ces animaux adorent les jouets et veulent jouer tout le temps, même lorsqu\'ils ne sont pas excités.', 'https://static.wikia.nocookie.net/sims/images/a/a0/Joueur.webp/revision/latest?cb=20220317165802&path-prefix=fr', 'Joueur', 18, 'CHIEN', 'BASE'),
(289, 'Ces chiens sont des créatures ayant peu d\'énergie qui préfèrent se détendre avec leurs maîtres plutôt que de courir partout.', 'https://static.wikia.nocookie.net/sims/images/a/a1/Mollasson.webp/revision/latest?cb=20220317165846&path-prefix=fr', 'Mollasson', 18, 'CHIEN', 'BASE'),
(290, 'Ces chiens laissent des touffes de poil partout. Brossez leur fourrure pour garder les lieux propres !', 'https://static.wikia.nocookie.net/sims/images/a/ac/Poilu.webp/revision/latest?cb=20220317165934&path-prefix=fr', 'Poilu', 18, 'CHIEN', 'BASE'),
(291, 'Ces chiens sont facilement effrayés et aiment se cacher plus souvent que les autres. Ils se tiennent souvent à distance de certaines choses comme les bagarres.', 'https://static.wikia.nocookie.net/sims/images/0/0c/Stress%C3%A9.webp/revision/latest?cb=20220317170028&path-prefix=fr', 'Stressé', 18, 'CHIEN', 'BASE'),
(292, 'Ces chiens n\'aiment pas qu\'on leur dise ce qu\'ils doivent faire. Les gronder a peu d\'effet sur leur mauvais comportement, mais vous pouvez essayer de les supplier d\'arrêter.', 'https://static.wikia.nocookie.net/sims/images/e/ea/T%C3%AAtu.webp/revision/latest?cb=20220317170106&path-prefix=fr', 'Têtu', 18, 'CHIEN', 'BASE');
INSERT INTO `trait_education` (`qualite`, `id`) VALUES
('Responsabilité', 13);
